import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import React, { createContext, useContext, useState } from "react";
import { IoChevronDown } from "react-icons/io5";
import { cn } from "@/lib/utils";

export interface AccordionProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Allow multiple items to be expanded at once
   * @default false
   */
  multiple?: boolean;
  /**
   * Accordion content (AccordionItem components)
   */
  children: React.ReactNode;
}

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Unique identifier for the accordion item
   */
  value: string;
  /**
   * Whether the item is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Accordion item content
   */
  children: React.ReactNode;
}

export interface AccordionTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Trigger content
   */
  children: React.ReactNode;
}

export interface AccordionContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Content to display when accordion item is expanded
   */
  children: React.ReactNode;
}

// Context for accordion state management
interface AccordionContextType {
  expandedItems: Set<string>;
  toggle: (value: string) => void;
  multiple: boolean;
}

const AccordionContext = createContext<AccordionContextType | null>(null);

interface AccordionItemContextType {
  value: string;
  isExpanded: boolean;
  disabled: boolean;
}

const AccordionItemContext = createContext<AccordionItemContextType | null>(null);

const useAccordion = () => {
  const context = useContext(AccordionContext);
  if (!context) {
    throw new Error("Accordion components must be used within an Accordion");
  }
  return context;
};

const useAccordionItem = () => {
  const context = useContext(AccordionItemContext);
  if (!context) {
    throw new Error("AccordionTrigger and AccordionContent must be used within an AccordionItem");
  }
  return context;
};

export const Accordion: React.FC<AccordionProps> = ({
  children,
  className,
  multiple = false,
  ...props
}) => {
  const [expandedItems, setExpandedItems] = useState<Set<string>>(new Set());

  const toggle = (value: string) => {
    setExpandedItems(prev => {
      const newSet = new Set(prev);
      if (newSet.has(value)) {
        newSet.delete(value);
      } else {
        if (!multiple) {
          newSet.clear();
        }
        newSet.add(value);
      }
      return newSet;
    });
  };

  const contextValue: AccordionContextType = {
    expandedItems,
    toggle,
    multiple,
  };

  return (
    <AccordionContext.Provider value={contextValue}>
      <div className={cn("w-full", className)} {...props}>
        {children}
      </div>
    </AccordionContext.Provider>
  );
};

export const AccordionItem: React.FC<AccordionItemProps> = ({
  children,
  className,
  value,
  disabled = false,
  ...props
}) => {
  const { expandedItems } = useAccordion();
  const isExpanded = expandedItems.has(value);

  const contextValue: AccordionItemContextType = {
    value,
    isExpanded,
    disabled,
  };

  return (
    <AccordionItemContext.Provider value={contextValue}>
      <div className={cn("border-border border-b last:border-b-0", className)} {...props}>
        {children}
      </div>
    </AccordionItemContext.Provider>
  );
};

export const AccordionTrigger: React.FC<AccordionTriggerProps> = ({
  children,
  className,
  ...props
}) => {
  const { toggle } = useAccordion();
  const { value, isExpanded, disabled } = useAccordionItem();

  const handleClick = () => {
    if (!disabled) {
      toggle(value);
    }
  };

  return (
    <button
      className={cn(
        "rui-focus-ring hover:text-foreground flex w-full items-center justify-between py-4 text-left text-sm font-medium transition-all disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      onClick={handleClick}
      disabled={disabled}
      aria-expanded={isExpanded}
      {...props}
    >
      <span>{children}</span>
      <IoChevronDown
        className={cn(
          "text-muted-foreground h-4 w-4 shrink-0 transition-transform duration-200",
          isExpanded && "rotate-180"
        )}
      />
    </button>
  );
};

export const AccordionContent: React.FC<AccordionContentProps> = ({
  children,
  className,
  ...props
}) => {
  const { isExpanded } = useAccordionItem();

  return (
    <div
      className={cn(
        "overflow-hidden text-sm duration-200",
        isExpanded
          ? "animate-in fade-in slide-in-from-top-2 pb-4 ease-out"
          : "animate-out fade-out slide-out-to-top-2 max-h-0 ease-in",
        className
      )}
      {...props}
    >
      <div className="text-muted-foreground">{children}</div>
    </div>
  );
};

import React from "react";
import {
  HiOutlineCheckCircle,
  HiOutlineExclamation,
  HiOutlineExclamationCircle,
  HiOutlineInformationCircle,
} from "react-icons/hi";
import { IoClose } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

type AlertVariant = "info" | "success" | "warning" | "error";
type AlertSize = "sm" | "md" | "lg";
type AlertStyle = "filled" | "outline" | "soft";
type AlertRounded = "none" | "sm" | "md" | "lg" | "xl";

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "style"> {
  /**
   * The visual style of the alert
   * @default "info"
   */
  variant?: AlertVariant;
  /**
   * The size of the alert
   * @default "md"
   */
  size?: AlertSize;
  /**
   * Control the border radius of the alert
   * @default "md"
   */
  rounded?: AlertRounded;
  /**
   * Alert content style
   * @default "filled"
   */
  style?: AlertStyle;
  /**
   * Optional left icon
   */
  startIcon?: React.ReactNode;
  /**
   * Optional right icon or custom action element
   */
  endIcon?: React.ReactNode;
  /**
   * Alert title (optional)
   */
  title?: string;
  /**
   * Whether the alert can be dismissed
   * @default false
   */
  dismissible?: boolean;
  /**
   * Dismiss handler for dismissible alerts
   */
  onDismiss?: () => void;
  /**
   * Custom dismiss icon
   */
  dismissIcon?: React.ReactNode;
  /**
   * Alert content
   */
  children: React.ReactNode;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the alert element
   */
  id?: string;
  /**
   * Role for screen readers
   * @default "alert"
   */
  role?: "alert" | "alertdialog" | "status";
}

// Base styles
const alertBase = tw`relative flex items-start gap-3 p-4 transition-all duration-150`;

// Variants - filled style
const variantsFilled: Record<AlertVariant, string> = {
  info: tw`bg-info text-info-foreground`,
  success: tw`bg-success text-success-foreground`,
  warning: tw`bg-warning text-warning-foreground`,
  error: tw`bg-destructive text-destructive-foreground`,
};

// Variants - outline style
const variantsOutline: Record<AlertVariant, string> = {
  info: tw`border border-info bg-background text-info`,
  success: tw`border border-success bg-background text-success`,
  warning: tw`border border-warning bg-background text-warning`,
  error: tw`border border-destructive bg-background text-destructive`,
};

// Variants - soft style
const variantsSoft: Record<AlertVariant, string> = {
  info: tw`border border-info/20 bg-info/10 text-info`,
  success: tw`border border-success/20 bg-success/10 text-success`,
  warning: tw`border border-warning/20 bg-warning/10 text-warning`,
  error: tw`border border-destructive/20 bg-destructive/10 text-destructive`,
};

// Sizes
const sizes: Record<AlertSize, { container: string; text: string; title: string; icon: string }> = {
  sm: {
    container: tw`gap-2 p-3`,
    text: tw`text-sm`,
    title: tw`text-sm font-medium`,
    icon: tw`h-4 w-4`,
  },
  md: {
    container: tw`gap-3 p-4`,
    text: tw`text-sm`,
    title: tw`text-sm font-semibold`,
    icon: tw`h-5 w-5`,
  },
  lg: {
    container: tw`gap-4 p-5`,
    text: tw`text-base`,
    title: tw`text-base font-semibold`,
    icon: tw`h-6 w-6`,
  },
} as const;

// Rounded options
const roundedOptions: Record<AlertRounded, string> = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
};

// Icon color variants for different styles
const iconColors: Record<AlertStyle, Record<AlertVariant, string>> = {
  filled: {
    info: tw`text-info-foreground/80`,
    success: tw`text-success-foreground/80`,
    warning: tw`text-warning-foreground/80`,
    error: tw`text-destructive-foreground/80`,
  },
  outline: {
    info: tw`text-info`,
    success: tw`text-success`,
    warning: tw`text-warning`,
    error: tw`text-destructive`,
  },
  soft: {
    info: tw`text-info`,
    success: tw`text-success`,
    warning: tw`text-warning`,
    error: tw`text-destructive`,
  },
};

// Default icons for each variant
const DefaultIcons: Record<
  AlertVariant,
  ({ className }: { className?: string }) => React.ReactElement
> = {
  info: ({ className }: { className?: string }) => (
    <HiOutlineInformationCircle className={cn("h-5 w-5", className)} />
  ),
  success: ({ className }: { className?: string }) => (
    <HiOutlineCheckCircle className={cn("h-5 w-5", className)} />
  ),
  warning: ({ className }: { className?: string }) => (
    <HiOutlineExclamation className={cn("h-5 w-5", className)} />
  ),
  error: ({ className }: { className?: string }) => (
    <HiOutlineExclamationCircle className={cn("h-5 w-5", className)} />
  ),
};

export const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      variant = "info",
      size = "md",
      rounded = "md",
      style = "filled",
      startIcon,
      endIcon,
      title,
      dismissible = false,
      onDismiss,
      dismissIcon,
      children,
      className = "",
      id,
      role = "alert",
      ...props
    },
    ref
  ) => {
    const handleDismiss = (event: React.MouseEvent) => {
      event.stopPropagation();
      if (dismissible && onDismiss) {
        onDismiss();
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (dismissible && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        onDismiss?.();
      }
    };

    // Get variant styles based on style prop
    const getVariantStyles = () => {
      switch (style) {
        case "outline":
          return variantsOutline[variant];
        case "soft":
          return variantsSoft[variant];
        default:
          return variantsFilled[variant];
      }
    };

    // Get icon color
    const getIconColor = () => {
      return iconColors[style || "filled"][variant];
    };

    // Render the appropriate icon
    const renderIcon = () => {
      if (startIcon) {
        return (
          <span className={cn("flex shrink-0 items-start", sizes[size].icon, getIconColor())}>
            {startIcon}
          </span>
        );
      }

      const DefaultIcon = DefaultIcons[variant];
      return (
        <span className={cn("flex shrink-0 items-start", getIconColor())}>
          <DefaultIcon className={sizes[size].icon} />
        </span>
      );
    };

    const alertClasses = cn(
      alertBase,
      getVariantStyles(),
      sizes[size].container,
      sizes[size].text,
      roundedOptions[rounded],
      className
    );

    return (
      <div ref={ref} className={alertClasses} role={role} id={id} {...props}>
        {renderIcon()}

        <div className="min-w-0 flex-1">
          {title && <div className={cn("mb-1", sizes[size].title)}>{title}</div>}
          <div className="break-words">{children}</div>
        </div>

        {endIcon && !dismissible && (
          <span className={cn("flex shrink-0 items-start", sizes[size].icon, getIconColor())}>
            {endIcon}
          </span>
        )}

        {dismissible && (
          <button
            type="button"
            className={cn(
              "rui-focus-ring flex shrink-0 items-start rounded-full p-1 transition-colors duration-150",
              "hover:bg-black/10 focus:outline-none",
              style === "filled" ? "text-white/80 hover:text-white" : "opacity-70 hover:opacity-100"
            )}
            onClick={handleDismiss}
            onKeyDown={handleKeyDown}
            aria-label="Dismiss alert"
          >
            {dismissIcon || <IoClose className="h-4 w-4" />}
          </button>
        )}
      </div>
    );
  }
);

Alert.displayName = "Alert";

import React, { useState } from "react";
import { HiOutlineUser } from "react-icons/hi";
import { cn, tw } from "@/lib/utils";

export interface AvatarProps {
  /**
   * The visual style of the avatar
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the avatar
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl" | "2xl";
  /**
   * Control the border radius of the avatar
   * @default "full"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Source URL for the avatar image
   */
  src?: string;
  /**
   * Alt text for the avatar image
   */
  alt?: string;
  /**
   * Fallback initials when no image is provided
   */
  initials?: string;
  /**
   * Custom fallback content (overrides initials)
   */
  fallback?: React.ReactNode;
  /**
   * Whether the avatar is clickable
   * @default false
   */
  clickable?: boolean;
  /**
   * Click handler for clickable avatars
   */
  onClick?: () => void;
  /**
   * Show online status indicator
   * @default false
   */
  showStatus?: boolean;
  /**
   * Status indicator type
   * @default "online"
   */
  status?: "online" | "offline" | "away" | "busy";
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the avatar element
   */
  id?: string;
}

// Base styles - Added border for shadow and ensured shadow-sm is always present for primary.
// We will use a border to hold the shadow, and outline for the status.
const avatarBase = tw`relative inline-flex items-center justify-center overflow-hidden bg-muted font-medium text-muted-foreground transition-all duration-150`;

// Variants
const variants = {
  primary: tw`border-2 border-background shadow-sm`,
  secondary: tw`border border-border`,
};

// Sizes
const sizes = {
  xs: { container: tw`h-6 w-6`, text: tw`text-xs` },
  sm: { container: tw`h-8 w-8`, text: tw`text-sm` },
  md: { container: tw`h-10 w-10`, text: tw`text-sm` },
  lg: { container: tw`h-12 w-12`, text: tw`text-base` },
  xl: { container: tw`h-16 w-16`, text: tw`text-lg` },
  "2xl": { container: tw`h-20 w-20`, text: tw`text-xl` },
} as const;

// Rounded options
const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

// Status outline styles
const statusOutlineStyles = {
  online: tw`outline-2 outline-offset-0 outline-success`,
  offline: tw`outline-2 outline-offset-0 outline-muted-foreground/60`,
  away: tw`outline-2 outline-offset-0 outline-warning`,
  busy: tw`outline-2 outline-offset-0 outline-destructive`,
};

// Clickable styles
const clickableStyles = tw`cursor-pointer hover:opacity-80 rui-focus-ring focus:outline-none`;

// Default user icon
const UserIcon = () => <HiOutlineUser className="text-muted-foreground/60 h-full w-full" />;

export const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "full",
      src,
      alt,
      initials,
      fallback,
      clickable = false,
      onClick,
      showStatus = false,
      status = "online",
      className = "",
      id,
      ...props
    },
    ref
  ) => {
    const [imageError, setImageError] = useState(false);

    const handleImageError = () => {
      setImageError(true);
    };

    const handleImageLoad = () => {
      setImageError(false);
    };

    const handleClick = () => {
      if (clickable && onClick) {
        onClick();
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (clickable && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        onClick?.();
      }
    };

    const avatarClasses = cn(
      avatarBase,
      variants[variant], // Always apply the variant's border (for shadow)
      showStatus && statusOutlineStyles[status], // Conditionally apply the status outline
      sizes[size].container,
      sizes[size].text,
      roundedOptions[rounded],
      clickable && clickableStyles,
      className
    );

    const showImage = src && !imageError;
    const showInitials = !showImage && initials;
    const showFallback = !showImage && !showInitials;

    return (
      <div
        ref={ref}
        className={avatarClasses}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        tabIndex={clickable ? 0 : undefined}
        role={clickable ? "button" : undefined}
        id={id}
        {...props}
      >
        {/* Image */}
        {showImage && (
          <img
            src={src}
            alt={alt || "Avatar"}
            className="h-full w-full object-cover"
            onError={handleImageError}
            onLoad={handleImageLoad}
          />
        )}

        {/* Initials */}
        {showInitials && <span className="uppercase select-none">{initials.slice(0, 2)}</span>}

        {/* Fallback */}
        {showFallback && (
          <div className="flex h-full w-full items-center justify-center">
            {fallback || <UserIcon />}
          </div>
        )}
      </div>
    );
  }
);

Avatar.displayName = "Avatar";

import React from "react";
import { IoClose } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

export interface BadgeProps {
  /**
   * The visual style of the badge
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "success" | "warning" | "error" | "info";
  /**
   * The size of the badge
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Control the border radius of the badge
   * @default "full"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Badge content style
   * @default "filled"
   */
  style?: "filled" | "outline" | "soft";
  /**
   * Optional left icon
   */
  startIcon?: React.ReactNode;
  /**
   * Optional right icon
   */
  endIcon?: React.ReactNode;
  /**
   * Whether the badge is clickable
   * @default false
   */
  clickable?: boolean;
  /**
   * Click handler for clickable badges
   */
  onClick?: () => void;
  /**
   * Whether the badge can be dismissed
   * @default false
   */
  dismissible?: boolean;
  /**
   * Dismiss handler for dismissible badges
   */
  onDismiss?: () => void;
  /**
   * Badge content
   */
  children: React.ReactNode;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the badge element
   */
  id?: string;
}

const badgeBase = tw`inline-flex items-center font-medium transition-all duration-200`;

// Filled — brand colors use tokens, semantics stay as Tailwind
const variantsFilled = {
  primary: tw`bg-primary text-primary-foreground`,
  secondary: tw`bg-secondary text-secondary-foreground`,
  success: tw`bg-green-600 text-white`,
  warning: tw`bg-yellow-600 text-white`,
  error: tw`bg-destructive text-destructive-foreground`,
  info: tw`bg-cyan-600 text-white`,
};

// Outline
const variantsOutline = {
  primary: tw`border border-primary bg-background text-primary`,
  secondary: tw`border border-secondary-foreground bg-background text-secondary-foreground`,
  success: tw`border border-green-600 bg-background text-green-600`,
  warning: tw`border border-yellow-600 bg-background text-yellow-600`,
  error: tw`border border-destructive bg-background text-destructive`,
  info: tw`border border-cyan-600 bg-background text-cyan-600`,
};

// Soft
const variantsSoft = {
  primary: tw`bg-accent text-accent-foreground`,
  secondary: tw`bg-secondary text-secondary-foreground`,
  success: tw`bg-green-50 text-green-700`,
  warning: tw`bg-yellow-50 text-yellow-700`,
  error: tw`bg-destructive/10 text-destructive`,
  info: tw`bg-cyan-50 text-cyan-700`,
};

// Hover states for clickable badges
const hoverStatesFilled = {
  primary: tw`hover:bg-primary/90`,
  secondary: tw`hover:bg-secondary/80`,
  success: tw`hover:bg-green-700`,
  warning: tw`hover:bg-yellow-700`,
  error: tw`hover:bg-destructive/90`,
  info: tw`hover:bg-cyan-700`,
};

const hoverStatesOutline = {
  primary: tw`hover:bg-accent`,
  secondary: tw`hover:bg-secondary`,
  success: tw`hover:bg-green-50`,
  warning: tw`hover:bg-yellow-50`,
  error: tw`hover:bg-destructive/10`,
  info: tw`hover:bg-cyan-50`,
};

const hoverStatesSoft = {
  primary: tw`hover:bg-accent/80`,
  secondary: tw`hover:bg-secondary/80`,
  success: tw`hover:bg-green-100`,
  warning: tw`hover:bg-yellow-100`,
  error: tw`hover:bg-destructive/15`,
  info: tw`hover:bg-cyan-100`,
};

const sizes = {
  sm: { container: tw`h-5 gap-1 px-2`, text: tw`text-xs`, icon: tw`h-3 w-3` },
  md: { container: tw`h-6 gap-1.5 px-2.5`, text: tw`text-xs`, icon: tw`h-3.5 w-3.5` },
  lg: { container: tw`h-7 gap-2 px-3`, text: tw`text-sm`, icon: tw`h-4 w-4` },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

// rui-focus-ring: keyboard-only focus via :focus-visible
const clickableStyles = tw`rui-focus-ring cursor-pointer`;

export const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "full",
      style = "filled",
      startIcon,
      endIcon,
      clickable = false,
      onClick,
      dismissible = false,
      onDismiss,
      children,
      className = "",
      id,
      ...props
    },
    ref
  ) => {
    const handleClick = () => {
      if (clickable && onClick) onClick();
    };
    const handleDismiss = (event: React.MouseEvent) => {
      event.stopPropagation();
      if (dismissible && onDismiss) onDismiss();
    };
    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (clickable && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        onClick?.();
      }
    };

    const getVariantStyles = () => {
      switch (style) {
        case "outline":
          return variantsOutline[variant];
        case "soft":
          return variantsSoft[variant];
        default:
          return variantsFilled[variant];
      }
    };

    const getHoverStyles = () => {
      if (!clickable) return "";
      switch (style) {
        case "outline":
          return hoverStatesOutline[variant];
        case "soft":
          return hoverStatesSoft[variant];
        default:
          return hoverStatesFilled[variant];
      }
    };

    const badgeClasses = cn(
      badgeBase,
      getVariantStyles(),
      sizes[size].container,
      sizes[size].text,
      roundedOptions[rounded],
      clickable && clickableStyles,
      clickable && getHoverStyles(),
      className
    );

    const Component = clickable ? "button" : "span";

    return (
      <Component
        ref={ref as React.Ref<HTMLButtonElement & HTMLSpanElement>}
        className={badgeClasses}
        onClick={clickable ? handleClick : undefined}
        onKeyDown={clickable ? handleKeyDown : undefined}
        type={clickable ? "button" : undefined}
        id={id}
        {...props}
      >
        {startIcon && (
          <span className={cn("flex items-center", sizes[size].icon)}>{startIcon}</span>
        )}
        <span className="truncate">{children}</span>
        {endIcon && !dismissible && (
          <span className={cn("flex items-center", sizes[size].icon)}>{endIcon}</span>
        )}
        {dismissible && (
          <button
            type="button"
            className={cn(
              "rui-focus-ring ml-1 flex items-center rounded-full p-0.5 hover:bg-black/10",
              sizes[size].icon
            )}
            onClick={handleDismiss}
            aria-label="Remove badge"
          >
            <IoClose className="h-3 w-3" />
          </button>
        )}
      </Component>
    );
  }
);

Badge.displayName = "Badge";

import { cn, tw } from "@/lib/utils";
import React from "react";

export interface BreadcrumbItem {
  label: string;
  href?: string;
  onClick?: () => void;
  disabled?: boolean;
  icon?: React.ReactNode;
}

export interface BreadcrumbProps {
  /**
   * The visual style of the breadcrumb
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the breadcrumb
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Control the border radius of the breadcrumb items
   * @default "sm"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Make breadcrumb take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Array of breadcrumb items
   */
  items: BreadcrumbItem[];
  /**
   * Custom separator between items
   * @default "/"
   */
  separator?: React.ReactNode;
  /**
   * Maximum number of items to show before collapsing
   */
  maxItems?: number;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * Callback when an item is clicked
   */
  onItemClick?: (item: BreadcrumbItem, index: number) => void;
}

// Design primitives matching Select component
const breadcrumbBase = tw`inline-flex items-center`;
const itemBase = tw`inline-flex items-center text-sm font-medium transition-colors duration-200`;

const variants = {
  primary: tw`text-muted-foreground hover:text-primary`,
  secondary: tw`text-muted-foreground/80 hover:text-foreground`,
};

const sizes = {
  sm: { text: tw`text-xs`, gap: tw`gap-1`, padding: tw`px-2 py-1` },
  md: { text: tw`text-sm`, gap: tw`gap-2`, padding: tw`px-3 py-1.5` },
  lg: { text: tw`text-base`, gap: tw`gap-3`, padding: tw`px-4 py-2` },
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const separatorBase = tw`mx-2 text-muted-foreground/60`;
const currentItemBase = tw`font-semibold text-foreground`;
const disabledItemBase = tw`cursor-not-allowed opacity-50`;
const animatedBase = tw`transition-all duration-200`;

const DefaultSeparator = ({ size }: { size: "sm" | "md" | "lg" }) => (
  <span className={cn("text-muted-foreground/60", sizes[size].text)} aria-hidden="true">
    /
  </span>
);

const CollapseIndicator = ({ size }: { size: "sm" | "md" | "lg" }) => (
  <button
    type="button"
    className={cn(
      itemBase,
      "hover:text-foreground hover:bg-accent cursor-pointer",
      sizes[size].text,
      sizes[size].padding,
      roundedOptions.sm
    )}
    aria-label="Show hidden breadcrumb items"
  >
    ...
  </button>
);

export const Breadcrumb = React.forwardRef<HTMLElement, BreadcrumbProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "sm",
      animation = true,
      fullWidth = false,
      items,
      separator,
      maxItems,
      className = "",
      onItemClick,
      ...props
    },
    ref
  ) => {
    // Handle item collapsing
    const displayItems = React.useMemo(() => {
      if (!maxItems || items.length <= maxItems) {
        return items;
      }

      if (maxItems <= 2) {
        return [items[0], ...items.slice(-1)];
      }

      const firstItems = items.slice(0, Math.floor(maxItems / 2));
      const lastItems = items.slice(-Math.floor(maxItems / 2));

      return [...firstItems, { label: "...", disabled: true }, ...lastItems];
    }, [items, maxItems]);

    const handleItemClick = (item: BreadcrumbItem, index: number, event: React.MouseEvent) => {
      if (item.disabled) {
        event.preventDefault();
        return;
      }

      if (item.onClick) {
        event.preventDefault();
        item.onClick();
      }

      onItemClick?.(item, index);
    };

    const containerClasses = cn(breadcrumbBase, fullWidth && "w-full", className);

    return (
      <nav ref={ref} className={containerClasses} aria-label="Breadcrumb" {...props}>
        <ol className={cn("flex items-center", sizes[size].gap)}>
          {displayItems.map((item, index) => {
            const isLast = index === displayItems.length - 1;
            const isCurrent = isLast && !item.href;
            const isCollapsed = item.label === "...";

            return (
              <li key={`${item.label}-${index}`} className="flex items-center">
                {isCollapsed ? (
                  <CollapseIndicator size={size} />
                ) : item.href ? (
                  <a
                    href={item.href}
                    className={cn(
                      itemBase,
                      variants[variant],
                      sizes[size].text,
                      sizes[size].padding,
                      roundedOptions[rounded],
                      animation && animatedBase,
                      item.disabled && disabledItemBase,
                      isCurrent && currentItemBase,
                      "hover:bg-accent hover:text-accent-foreground"
                    )}
                    onClick={e => handleItemClick(item, index, e)}
                    aria-current={isCurrent ? "page" : undefined}
                    aria-disabled={item.disabled}
                  >
                    {item.icon && <span className="mr-2 flex items-center">{item.icon}</span>}
                    {item.label}
                  </a>
                ) : (
                  <button
                    type="button"
                    className={cn(
                      itemBase,
                      variants[variant],
                      sizes[size].text,
                      sizes[size].padding,
                      roundedOptions[rounded],
                      animation && animatedBase,
                      item.disabled && disabledItemBase,
                      isCurrent && currentItemBase,
                      !item.disabled && "hover:bg-accent hover:text-accent-foreground"
                    )}
                    onClick={e => handleItemClick(item, index, e)}
                    disabled={item.disabled}
                    aria-current={isCurrent ? "page" : undefined}
                  >
                    {item.icon && <span className="mr-2 flex items-center">{item.icon}</span>}
                    {item.label}
                  </button>
                )}

                {!isLast && (
                  <span className={cn(separatorBase, sizes[size].gap)}>
                    {separator || <DefaultSeparator size={size} />}
                  </span>
                )}
              </li>
            );
          })}
        </ol>
      </nav>
    );
  }
);

Breadcrumb.displayName = "Breadcrumb";

import React from "react";
import { Loader } from "@/components/ui/";
import { cn, tw } from "@/lib/utils";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * The visual style of the button
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "outline" | "tertiary" | "destructive" | "none";
  /**
   * The size of the button
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Optional left icon - accepts any React element
   */
  startIcon?: React.ReactNode;
  /**
   * Optional right icon - accepts any React element
   */
  endIcon?: React.ReactNode;
  /**
   * Show a loading spinner and disable the button
   * @default false
   */
  loading?: boolean;
  /**
   * Make button take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Control the border radius of the button
   * @default "md"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Animation effect on user interaction
   * @default "none"
   */
  animation?: "none" | "scale" | "glow" | "lift" | "ripple" | "press";
  /**
   * Button content (text, elements, etc.)
   */
  children: React.ReactNode;
}

// rui-focus-ring provides the :focus-visible ring — 2px offset + 2px ring
const base = tw`rui-focus-ring relative inline-flex transform-gpu cursor-pointer items-center justify-center gap-2 font-medium whitespace-nowrap transition-all duration-200 select-none disabled:pointer-events-none disabled:opacity-50`;

const variants = {
  primary: tw`bg-primary text-primary-foreground shadow-sm hover:bg-primary/90 hover:shadow-md`,
  secondary: tw`bg-secondary text-secondary-foreground shadow-sm ring-1 ring-border hover:bg-secondary/80 hover:shadow-md`,
  outline: tw`border border-primary bg-transparent text-primary hover:bg-accent hover:text-accent-foreground`,
  tertiary: tw`border border-border bg-background text-foreground shadow-sm hover:bg-muted hover:shadow-md`,
  destructive: tw`bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90 hover:shadow-md`,
  none: tw``,
};

const sizes = {
  xs: tw`h-7 min-w-[1.5rem] gap-1 px-2 py-1 text-xs`,
  sm: tw`h-8 min-w-[2rem] gap-1.5 px-2.5 py-1.5 text-xs`,
  md: tw`h-9 min-w-[2.5rem] gap-2 px-3 py-1.5 text-sm`,
  lg: tw`h-10 min-w-[3rem] gap-2.5 px-4 py-2 text-sm`,
  xl: tw`h-12 min-w-[3.5rem] gap-3 px-5 py-2.5 text-base`,
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const animations = {
  none: tw``,
  scale: tw`transition-transform duration-150 ease-out hover:scale-105 active:scale-95`,
  glow: tw`transition-shadow duration-200 ease-out hover:shadow-lg hover:shadow-primary/25`,
  lift: tw`transition-[transform,box-shadow] duration-150 ease-out hover:-translate-y-[2px] hover:shadow-lg active:-translate-y-[1px]`,
  ripple: tw`overflow-hidden`,
  press: tw`transition-transform duration-75 ease-out active:scale-95`,
};

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      variant = "primary",
      size = "md",
      className = "",
      startIcon,
      endIcon,
      loading = false,
      fullWidth = false,
      rounded = "md",
      animation = "none",
      children,
      disabled,
      ...props
    },
    ref
  ) => {
    const isDisabled = disabled || loading;
    const btnRef = React.useRef<HTMLButtonElement | null>(null);
    React.useImperativeHandle(ref, () => btnRef.current as HTMLButtonElement);

    type Ripple = { id: number; x: number; y: number; size: number };
    const [ripples, setRipples] = React.useState<Ripple[]>([]);

    const createRipple = React.useCallback(
      (e: { clientX?: number; clientY?: number }) => {
        if (animation !== "ripple" || isDisabled) return;
        const el = btnRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height) * 1.8;
        let x = rect.width / 2;
        let y = rect.height / 2;
        if (typeof e.clientX === "number" && typeof e.clientY === "number") {
          x = e.clientX - rect.left;
          y = e.clientY - rect.top;
        }
        const id = Date.now() + Math.random();
        setRipples(prev => [...prev.slice(-3), { id, x, y, size }]);
        window.setTimeout(() => {
          setRipples(prev => prev.filter(r => r.id !== id));
        }, 500);
      },
      [animation, isDisabled]
    );

    const rippleVars = React.useMemo(() => {
      let opacity = 0.3;
      if (variant === "primary" || variant === "destructive") opacity = 0.35;
      else if (variant === "secondary") opacity = 0.25;
      else if (variant === "outline" || variant === "tertiary") opacity = 0.2;
      return { "--rui-ripple-opacity": String(opacity) } as React.CSSProperties & {
        "--rui-ripple-opacity": string;
      };
    }, [variant]);

    const { onPointerDown, onKeyDown, style, ...restProps } =
      props as React.ButtonHTMLAttributes<HTMLButtonElement>;

    const handlePointerDown = React.useCallback(
      (e: React.PointerEvent<HTMLButtonElement>) => {
        onPointerDown?.(e);
        createRipple(e);
      },
      [onPointerDown, createRipple]
    );

    const handleKeyDown = React.useCallback(
      (e: React.KeyboardEvent<HTMLButtonElement>) => {
        onKeyDown?.(e);
        if (e.key === "Enter" || e.key === " ") createRipple({});
      },
      [onKeyDown, createRipple]
    );

    return (
      <button
        ref={btnRef}
        className={cn(
          base,
          variants[variant],
          sizes[size],
          roundedOptions[rounded],
          animations[animation],
          fullWidth && "w-full",
          className
        )}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        onPointerDown={handlePointerDown}
        onKeyDown={handleKeyDown}
        style={{ ...style, ...rippleVars }}
        {...restProps}
      >
        {animation === "ripple" && !loading && ripples.length > 0 && (
          <span aria-hidden className="pointer-events-none absolute inset-0">
            {ripples.map(r => (
              <span
                key={r.id}
                className="rui-ripple"
                style={{ left: r.x, top: r.y, width: r.size, height: r.size }}
              />
            ))}
          </span>
        )}
        {loading && (
          <Loader
            type="spinner"
            variant="primary"
            color="currentColor"
            size={size === "xs" ? "xs" : size === "sm" ? "xs" : size === "md" ? "sm" : "md"}
            speed="normal"
            strokeWidth="thick"
          />
        )}
        {startIcon && !loading && <span className="flex shrink-0 items-center">{startIcon}</span>}
        <span className="truncate">{children}</span>
        {endIcon && !loading && <span className="flex shrink-0 items-center">{endIcon}</span>}
      </button>
    );
  }
);

Button.displayName = "Button";

import type { Locale } from "date-fns";
import {
  addDays,
  addMonths,
  eachDayOfInterval,
  endOfMonth,
  endOfWeek,
  format,
  isAfter,
  isBefore,
  isSameDay,
  isSameMonth,
  isToday,
  startOfMonth,
  startOfWeek,
} from "date-fns";
import React from "react";
import { HiChevronLeft as ChevronLeft, HiChevronRight as ChevronRight } from "react-icons/hi";
import { cn, tw } from "@/lib/utils";

export interface CalendarProps {
  /** Currently selected date (controlled). */
  selectedDate?: Date | null;
  /** Called when a day is selected. */
  onDateSelect?: (date: Date) => void;

  /** Minimum selectable date (inclusive). */
  minDate?: Date;
  /** Maximum selectable date (inclusive). */
  maxDate?: Date;
  /** Disable a specific day using a predicate. */
  isDateDisabled?: (date: Date) => boolean;

  /** 0=Sunday ... 6=Saturday. @default 0 */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  /** i18n locale from date-fns. */
  locale?: Locale;
  /** Show days from adjacent months. @default true */
  showOutsideDays?: boolean;
  /** Show native selects to pick month and year. @default true */
  showMonthYearPickers?: boolean;
  /** Disable animations between months. @default false */
  disableAnimation?: boolean;

  /** Control currently visible month (controlled). */
  month?: Date;
  /** Called when visible month changes (via navigation). */
  onMonthChange?: (nextMonth: Date) => void;

  /** Optional id for accessibility. */
  id?: string;
  /** Custom className for the outer wrapper. */
  className?: string;
}

const wrapper = tw`inline-flex flex-col rounded-md border border-border bg-card p-3 text-foreground`;
const header = tw`mb-2 flex items-center justify-between`;
const navBtn = tw`rui-focus-ring inline-flex h-8 w-8 cursor-pointer items-center justify-center rounded-md border border-border text-foreground hover:bg-accent hover:text-accent-foreground active:bg-muted`;
const monthLabel = tw`px-2 text-sm font-semibold`;
const pickerWrap = tw`flex items-center gap-2`;
const selectBase = tw`rui-field-focus h-8 rounded-md border border-input bg-background px-2 text-sm text-foreground focus:outline-none`;
const grid = tw`grid grid-cols-7 gap-1`;
const dow = tw`py-1 text-center text-xs font-medium text-muted-foreground`;
const dayBase = tw`rui-focus-ring relative flex h-9 w-9 items-center justify-center rounded-md text-sm transition-colors focus:outline-none`;

function clampToDay(date: Date) {
  // normalize to noon to avoid DST edge cases on comparisons if needed
  const d = new Date(date);
  d.setHours(12, 0, 0, 0);
  return d;
}

function isOutOfRange(date: Date, minDate?: Date, maxDate?: Date) {
  const d = clampToDay(date);
  if (minDate && isBefore(d, clampToDay(minDate))) return true;
  if (maxDate && isAfter(d, clampToDay(maxDate))) return true;
  return false;
}

export const Calendar: React.FC<CalendarProps> = ({
  selectedDate = null,
  onDateSelect,
  minDate,
  maxDate,
  isDateDisabled,
  weekStartsOn = 0,
  locale,
  showOutsideDays = true,
  showMonthYearPickers = true,
  disableAnimation = false,
  month,
  onMonthChange,
  id,
  className = "",
}) => {
  const today = React.useMemo(() => new Date(), []);

  // Controlled or uncontrolled month state
  const initialMonth = React.useMemo(() => {
    if (month) return startOfMonth(month);
    if (selectedDate) return startOfMonth(selectedDate);
    return startOfMonth(today);
  }, [month, selectedDate, today]);

  const [internalMonth, setInternalMonth] = React.useState<Date>(initialMonth);

  // Keep internal month in sync when controlled props change
  React.useEffect(() => {
    if (month) setInternalMonth(startOfMonth(month));
  }, [month]);

  React.useEffect(() => {
    // When user selects a date via external control, keep month visible to that date
    if (!month && selectedDate) setInternalMonth(startOfMonth(selectedDate));
  }, [selectedDate, month]);

  const visibleMonth = month ? startOfMonth(month) : internalMonth;

  const start = startOfWeek(startOfMonth(visibleMonth), {
    weekStartsOn,
    locale,
  });
  const end = endOfWeek(endOfMonth(visibleMonth), { weekStartsOn, locale });
  const days = eachDayOfInterval({ start, end });
  // Ensure 6 rows (42 days) to keep height stable
  if (days.length < 42) {
    const toAdd = 42 - days.length;
    const last = days[days.length - 1];
    for (let i = 1; i <= toAdd; i++) {
      days.push(addDays(last, i));
    }
  }

  const weekdayLabels = Array.from({ length: 7 }, (_, i) => {
    const d = addDays(startOfWeek(new Date(), { weekStartsOn, locale }), i);
    return format(d, "EEEEE", { locale }); // S M T W T F S
  });

  const [animDir, setAnimDir] = React.useState<"left" | "right" | null>(null);

  const goPrev = () => {
    const next = startOfMonth(addMonths(visibleMonth, -1));
    setAnimDir("right");
    if (month) onMonthChange?.(next);
    else setInternalMonth(next);
  };

  const goNext = () => {
    const next = startOfMonth(addMonths(visibleMonth, 1));
    setAnimDir("left");
    if (month) onMonthChange?.(next);
    else setInternalMonth(next);
  };

  // Clear animation marker shortly after month changes so re-renders can re-apply class
  React.useEffect(() => {
    if (!animDir) return;
    const t = setTimeout(() => setAnimDir(null), 250);
    return () => clearTimeout(t);
  }, [animDir]);

  const handleSelect = (day: Date, disabled: boolean) => {
    if (disabled) return;
    onDateSelect?.(day);
  };

  return (
    <div id={id} className={cn(wrapper, className)} role="group" aria-label="Calendar">
      {/* Header */}
      <div className={header}>
        <button type="button" className={navBtn} aria-label="Previous month" onClick={goPrev}>
          <ChevronLeft size={16} />
        </button>
        {showMonthYearPickers ? (
          <div className={pickerWrap}>
            {/* Month select */}
            <select
              aria-label="Select month"
              className={selectBase}
              value={visibleMonth.getMonth()}
              onChange={e => {
                const m = Number(e.target.value);
                const next = new Date(visibleMonth);
                next.setMonth(m);
                next.setDate(1);
                const normalized = startOfMonth(next);
                if (month) onMonthChange?.(normalized);
                else setInternalMonth(normalized);
              }}
            >
              {Array.from({ length: 12 }).map((_, i) => (
                <option key={i} value={i}>
                  {format(new Date(2020, i, 1), "LLLL", {
                    locale,
                  })}
                </option>
              ))}
            </select>
            {/* Year select: show a reasonable window around current year */}
            <select
              aria-label="Select year"
              className={selectBase}
              value={visibleMonth.getFullYear()}
              onChange={e => {
                const y = Number(e.target.value);
                const next = new Date(visibleMonth);
                next.setFullYear(y);
                next.setDate(1);
                const normalized = startOfMonth(next);
                if (month) onMonthChange?.(normalized);
                else setInternalMonth(normalized);
              }}
            >
              {(() => {
                const years: number[] = [];
                const center = today.getFullYear();
                const startY = center - 50; // 50 years back
                const endY = center + 50; // 50 years ahead
                for (let y = startY; y <= endY; y++) years.push(y);
                return years.map(y => (
                  <option key={y} value={y}>
                    {y}
                  </option>
                ));
              })()}
            </select>
          </div>
        ) : (
          <div className={monthLabel} aria-live="polite" aria-atomic>
            {format(visibleMonth, "MMMM yyyy", { locale })}
          </div>
        )}
        <button type="button" className={navBtn} aria-label="Next month" onClick={goNext}>
          <ChevronRight size={16} />
        </button>
      </div>

      {/* Grid header (days of week) */}
      <div className={grid} role="row">
        {weekdayLabels.map(label => (
          <div key={label} className={dow} role="columnheader" aria-label={label}>
            {label}
          </div>
        ))}
      </div>

      {/* Days */}
      <div
        className={cn(
          grid,
          !disableAnimation &&
            animDir === "left" &&
            "animate-in slide-in-from-right-4 fade-in duration-200 ease-out",
          !disableAnimation &&
            animDir === "right" &&
            "animate-in slide-in-from-left-4 fade-in duration-200 ease-out"
        )}
        role="grid"
        aria-readonly
      >
        {days.map(day => {
          const inCurrentMonth = isSameMonth(day, visibleMonth);
          const outOfMonth = !inCurrentMonth;
          const outOfRange = isOutOfRange(day, minDate, maxDate);
          const predicateDisabled = isDateDisabled?.(day) ?? false;
          const disabled = outOfRange || predicateDisabled || (!showOutsideDays && outOfMonth);

          const isSelected = selectedDate ? isSameDay(day, selectedDate) : false;
          const todayFlag = isToday(day);

          const dayClasses = cn(
            dayBase,
            disabled && "cursor-not-allowed opacity-40",
            !disabled && "cursor-pointer hover:bg-accent hover:text-accent-foreground",
            outOfMonth && showOutsideDays && "text-muted-foreground/60",
            isSelected &&
              "bg-primary text-primary-foreground hover:bg-primary/90 hover:text-primary-foreground",
            todayFlag && !isSelected && "ring-1 ring-ring/40 ring-inset"
          );

          return (
            <button
              key={day.toISOString()}
              type="button"
              role="gridcell"
              aria-selected={isSelected}
              aria-disabled={disabled}
              disabled={disabled}
              onClick={() => handleSelect(day, disabled)}
              className={dayClasses}
              title={format(day, "PPPP", { locale })}
            >
              <span className={tw`leading-none`}>{format(day, "d", { locale })}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

Calendar.displayName = "Calendar";

