import React from "react";
import { FaChevronLeft, FaChevronRight } from "react-icons/fa";
import { cn, tw } from "@/lib/utils";

export interface CarouselProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /**
   * Array of carousel items to display
   */
  items: React.ReactNode[];
  /**
   * Currently active slide index (controlled)
   */
  activeIndex?: number;
  /**
   * Default active slide index (uncontrolled)
   * @default 0
   */
  defaultActiveIndex?: number;
  /**
   * Called when the active slide changes
   */
  onChange?: (index: number) => void;
  /**
   * Whether the carousel is draggable/swipeable
   * @default true
   */
  draggable?: boolean;
  /**
   * Enable autoplay functionality
   * @default false
   */
  autoplay?: boolean;
  /**
   * Autoplay interval in milliseconds
   * @default 3000
   */
  autoplayInterval?: number;
  /**
   * Pause autoplay on hover
   * @default true
   */
  pauseOnHover?: boolean;
  /**
   * Show navigation arrows
   * @default true
   */
  showArrows?: boolean;
  /**
   * Show dot indicators
   * @default true
   */
  showDots?: boolean;
  /**
   * Show slide counter (e.g., "1 / 5")
   * @default false
   */
  showCounter?: boolean;
  /**
   * Infinite loop navigation
   * @default true
   */
  infinite?: boolean;
  /**
   * Animation duration in milliseconds
   * @default 300
   */
  animationDuration?: number;
  /**
   * Custom className for the carousel container
   */
  className?: string;
  /**
   * Custom className for individual slides
   */
  slideClassName?: string;
  /**
   * Custom className for navigation arrows
   */
  arrowClassName?: string;
  /**
   * Custom className for dot indicators
   */
  dotClassName?: string;
}

const carouselBase = tw`relative h-64 w-full min-w-0 overflow-hidden rounded-lg bg-muted`;
const slideContainer = tw`relative h-full w-full`;
const slideBase = tw`absolute inset-0 h-full w-full flex-shrink-0`;
const arrowBase = tw`absolute top-1/2 z-10 flex h-10 w-10 -translate-y-1/2 cursor-pointer items-center justify-center rounded-full bg-background/90 text-foreground shadow-md transition-all duration-200 hover:scale-110 hover:bg-background hover:shadow-lg rui-focus-ring focus:outline-none disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100`;
const dotsContainer = tw`absolute bottom-4 left-1/2 flex -translate-x-1/2 space-x-2`;
const dotBase = tw`h-2 w-2 rounded-full bg-background/50 transition-all duration-200 hover:bg-background/70 rui-focus-ring focus:outline-none`;
const activeDot = tw`scale-125 bg-background`;
const counterBase = tw`absolute top-4 right-4 rounded-md bg-foreground/60 px-2 py-1 text-xs font-medium text-background`;

export const Carousel = React.forwardRef<HTMLDivElement, CarouselProps>(
  (
    {
      items,
      activeIndex: controlledActiveIndex,
      defaultActiveIndex = 0,
      onChange,
      draggable = true,
      autoplay = false,
      autoplayInterval = 3000,
      pauseOnHover = true,
      showArrows = true,
      showDots = true,
      showCounter = false,
      infinite = true,
      animationDuration = 300,
      className = "",
      slideClassName = "",
      arrowClassName = "",
      dotClassName = "",
      ...props
    },
    ref
  ) => {
    const [internalActiveIndex, setInternalActiveIndex] = React.useState(defaultActiveIndex);
    const [isDragging, setIsDragging] = React.useState(false);
    const [dragStart, setDragStart] = React.useState<{
      x: number;
      y: number;
    } | null>(null);
    const [dragOffset, setDragOffset] = React.useState(0);
    const [isAutoplayPaused, setIsAutoplayPaused] = React.useState(false);

    const carouselRef = React.useRef<HTMLDivElement>(null);
    const slideContainerRef = React.useRef<HTMLDivElement>(null);
    const autoplayRef = React.useRef<NodeJS.Timeout | null>(null);

    // Combine forwarded ref and local ref
    React.useImperativeHandle(ref, () => carouselRef.current as HTMLDivElement);

    const activeIndex = controlledActiveIndex ?? internalActiveIndex;
    const totalItems = items.length;

    // Reset to first slide if activeIndex is out of bounds
    React.useEffect(() => {
      if (activeIndex >= totalItems) {
        const newIndex = totalItems > 0 ? 0 : 0;
        if (controlledActiveIndex === undefined) {
          setInternalActiveIndex(newIndex);
        }
        onChange?.(newIndex);
      }
    }, [activeIndex, totalItems, controlledActiveIndex, onChange]);

    const goToSlide = React.useCallback(
      (index: number) => {
        if (totalItems === 0) return;

        let newIndex = index;
        if (infinite) {
          if (index < 0) newIndex = totalItems - 1;
          if (index >= totalItems) newIndex = 0;
        } else {
          newIndex = Math.max(0, Math.min(totalItems - 1, index));
        }

        if (controlledActiveIndex === undefined) {
          setInternalActiveIndex(newIndex);
        }
        onChange?.(newIndex);
      },
      [totalItems, infinite, controlledActiveIndex, onChange]
    );

    const goToNext = React.useCallback(() => {
      goToSlide(activeIndex + 1);
    }, [goToSlide, activeIndex]);

    const goToPrev = React.useCallback(() => {
      goToSlide(activeIndex - 1);
    }, [goToSlide, activeIndex]);

    // Autoplay functionality
    React.useEffect(() => {
      if (autoplay && !isAutoplayPaused && totalItems > 1) {
        autoplayRef.current = setInterval(() => {
          goToNext();
        }, autoplayInterval);
      } else {
        if (autoplayRef.current) {
          clearInterval(autoplayRef.current);
          autoplayRef.current = null;
        }
      }

      return () => {
        if (autoplayRef.current) {
          clearInterval(autoplayRef.current);
        }
      };
    }, [autoplay, autoplayInterval, isAutoplayPaused, totalItems, goToNext]);

    // Drag handlers
    const handleDragStart = React.useCallback(
      (clientX: number, clientY: number) => {
        if (!draggable) return;
        setIsDragging(true);
        setDragStart({ x: clientX, y: clientY });
        setDragOffset(0);
        setIsAutoplayPaused(true);
      },
      [draggable]
    );

    const handleDragMove = React.useCallback(
      (clientX: number, clientY: number) => {
        if (!isDragging || !dragStart || !carouselRef.current) return;

        const deltaX = clientX - dragStart.x;
        const deltaY = clientY - dragStart.y;

        // Only allow horizontal dragging if horizontal movement is greater
        if (Math.abs(deltaX) > Math.abs(deltaY)) {
          const containerWidth = carouselRef.current.offsetWidth;
          const maxOffset = containerWidth * 0.3; // Allow 30% drag
          const clampedOffset = Math.max(-maxOffset, Math.min(maxOffset, deltaX));
          setDragOffset(clampedOffset);
        }
      },
      [isDragging, dragStart]
    );

    const handleDragEnd = React.useCallback(() => {
      if (!isDragging || !carouselRef.current) return;

      const containerWidth = carouselRef.current.offsetWidth;
      const threshold = containerWidth * 0.15; // 15% threshold for slide change

      if (Math.abs(dragOffset) > threshold) {
        if (dragOffset > 0) {
          goToPrev();
        } else {
          goToNext();
        }
      }

      setIsDragging(false);
      setDragStart(null);
      setDragOffset(0);
      setIsAutoplayPaused(false);
    }, [isDragging, dragOffset, goToNext, goToPrev]);

    // Mouse events
    const handleMouseDown = React.useCallback(
      (e: React.MouseEvent) => {
        handleDragStart(e.clientX, e.clientY);
      },
      [handleDragStart]
    );

    const handleMouseMove = React.useCallback(
      (e: React.MouseEvent) => {
        handleDragMove(e.clientX, e.clientY);
      },
      [handleDragMove]
    );

    const handleMouseUp = React.useCallback(() => {
      handleDragEnd();
    }, [handleDragEnd]);

    // Touch events
    const handleTouchStart = React.useCallback(
      (e: React.TouchEvent) => {
        const touch = e.touches[0];
        handleDragStart(touch.clientX, touch.clientY);
      },
      [handleDragStart]
    );

    const handleTouchMove = React.useCallback(
      (e: React.TouchEvent) => {
        if (e.touches.length === 1) {
          const touch = e.touches[0];
          handleDragMove(touch.clientX, touch.clientY);
        }
      },
      [handleDragMove]
    );

    const handleTouchEnd = React.useCallback(() => {
      handleDragEnd();
    }, [handleDragEnd]);

    // Keyboard navigation
    const handleKeyDown = React.useCallback(
      (e: React.KeyboardEvent) => {
        switch (e.key) {
          case "ArrowLeft":
            e.preventDefault();
            goToPrev();
            break;
          case "ArrowRight":
            e.preventDefault();
            goToNext();
            break;
          case "Home":
            e.preventDefault();
            goToSlide(0);
            break;
          case "End":
            e.preventDefault();
            goToSlide(totalItems - 1);
            break;
        }
      },
      [goToPrev, goToNext, goToSlide, totalItems]
    );

    // Hover handlers for autoplay pause
    const handleMouseEnter = React.useCallback(() => {
      if (pauseOnHover) {
        setIsAutoplayPaused(true);
      }
    }, [pauseOnHover]);

    const handleMouseLeave = React.useCallback(() => {
      if (pauseOnHover) {
        setIsAutoplayPaused(false);
      }
    }, [pauseOnHover]);

    if (totalItems === 0) {
      return (
        <div ref={carouselRef} className={cn(carouselBase, className)} {...props}>
          <div className="text-muted-foreground flex h-48 items-center justify-center">
            No items to display
          </div>
        </div>
      );
    }

    return (
      <div
        ref={carouselRef}
        className={cn(carouselBase, className)}
        onMouseDown={handleMouseDown}
        onMouseMove={isDragging ? handleMouseMove : undefined}
        onMouseUp={handleMouseUp}
        onMouseLeave={() => {
          handleMouseUp();
          handleMouseLeave();
        }}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onKeyDown={handleKeyDown}
        onMouseEnter={handleMouseEnter}
        tabIndex={0}
        role="region"
        aria-label="Carousel"
        aria-live="polite"
        {...props}
      >
        <div
          ref={slideContainerRef}
          className={slideContainer}
          style={{
            transform: `translateX(calc(-${activeIndex * 100}% ${
              isDragging ? `+ ${dragOffset}px` : ""
            }))`,
            transition: isDragging ? "none" : `transform ${animationDuration}ms ease-in-out`,
          }}
        >
          {items.map((item, index) => (
            <div
              key={index}
              className={cn(slideBase, slideClassName)}
              style={{
                left: `${index * 100}%`,
              }}
              role="img"
              aria-label={`Slide ${index + 1} of ${totalItems}`}
            >
              {item}
            </div>
          ))}
        </div>

        {/* Navigation Arrows */}
        {showArrows && totalItems > 1 && (
          <>
            <button
              className={cn(arrowBase, arrowClassName, "left-4")}
              onClick={goToPrev}
              disabled={!infinite && activeIndex === 0}
              aria-label="Previous slide"
              type="button"
            >
              <FaChevronLeft size={16} />
            </button>
            <button
              className={cn(arrowBase, arrowClassName, "right-4")}
              onClick={goToNext}
              disabled={!infinite && activeIndex === totalItems - 1}
              aria-label="Next slide"
              type="button"
            >
              <FaChevronRight size={16} />
            </button>
          </>
        )}

        {/* Dot Indicators */}
        {showDots && totalItems > 1 && (
          <div className={dotsContainer}>
            {items.map((_, index) => (
              <button
                key={index}
                className={cn(dotBase, dotClassName, index === activeIndex && activeDot)}
                onClick={() => goToSlide(index)}
                aria-label={`Go to slide ${index + 1}`}
                type="button"
              />
            ))}
          </div>
        )}

        {/* Slide Counter */}
        {showCounter && totalItems > 1 && (
          <div className={counterBase}>
            {activeIndex + 1} / {totalItems}
          </div>
        )}
      </div>
    );
  }
);

Carousel.displayName = "Carousel";

import React from "react";
import { FaCheck, FaMinus } from "react-icons/fa";
import { cn, tw } from "@/lib/utils";

export interface CheckboxProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> {
  /**
   * The visual style of the checkbox
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the checkbox
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Control the border radius of the checkbox
   * @default "sm"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Custom color for the checkbox (CSS color value)
   */
  color?: string;
  /**
   * Indeterminate state for partial selection
   * @default false
   */
  indeterminate?: boolean;
  /**
   * Smooth scale animation for icon transitions
   * @default false
   */
  animation?: boolean;
  /**
   * Optional label text
   */
  label?: string;
  /**
   * Position of the label relative to checkbox
   * @default "right"
   */
  labelPosition?: "left" | "right";
  /**
   * Optional description text
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display
   */
  errorMessage?: string;
  /**
   * Make checkbox required
   * @default false
   */
  required?: boolean;
}

// peer-focus-visible: keyboard-only focus ring rendered via box-shadow
const base = tw`relative inline-flex cursor-pointer items-center justify-center border-2 transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50`;

const variants = {
  primary: tw`border-input bg-background hover:border-primary`,
  secondary: tw`border-input bg-background hover:border-secondary-foreground`,
};

const checkedVariants = {
  primary: tw`border-primary bg-primary`,
  secondary: tw`border-secondary-foreground bg-secondary-foreground`,
};

const sizes = {
  xs: tw`h-3 w-3`,
  sm: tw`h-4 w-4`,
  md: tw`h-5 w-5`,
  lg: tw`h-6 w-6`,
  xl: tw`h-7 w-7`,
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const labelSizes = {
  xs: tw`text-xs`,
  sm: tw`text-xs`,
  md: tw`text-sm`,
  lg: tw`text-base`,
  xl: tw`text-lg`,
};

const iconSizes = {
  xs: tw`text-[8px]`,
  sm: tw`text-[10px]`,
  md: tw`text-xs`,
  lg: tw`text-sm`,
  xl: tw`text-base`,
};

const textMinHeights = {
  xs: tw`min-h-3`,
  sm: tw`min-h-4`,
  md: tw`min-h-5`,
  lg: tw`min-h-6`,
  xl: tw`min-h-7`,
};

// Keyboard-only focus ring via peer-focus-visible (box-shadow: offset + 2px ring)
const focusRingClass =
  "peer-focus-visible:shadow-[0_0_0_var(--ring-offset)_hsl(var(--background)),0_0_0_calc(var(--ring-offset)+var(--ring-width))_var(--ring-color)]";

export const Checkbox = React.forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "sm",
      color,
      indeterminate = false,
      animation = false,
      label,
      labelPosition = "right",
      description,
      error = false,
      errorMessage,
      required = false,
      className = "",
      disabled,
      checked,
      onChange,
      ...props
    },
    ref
  ) => {
    const [internalChecked, setInternalChecked] = React.useState(false);
    const checkboxRef = React.useRef<HTMLInputElement | null>(null);
    React.useImperativeHandle(ref, () => checkboxRef.current as HTMLInputElement);

    const isChecked = checked !== undefined ? checked : internalChecked;
    const isDisabled = disabled;

    React.useEffect(() => {
      if (checkboxRef.current) checkboxRef.current.indeterminate = indeterminate;
    }, [indeterminate]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (checked === undefined) setInternalChecked(e.target.checked);
      onChange?.(e);
    };

    const CheckIcon = indeterminate ? FaMinus : FaCheck;

    const customColorStyles = React.useMemo(() => {
      if (!color) return {};
      return { "--checkbox-color": color } as React.CSSProperties;
    }, [color]);

    const checkboxElement = (
      <div className="relative inline-flex items-center">
        <input
          ref={checkboxRef}
          type="checkbox"
          className="peer sr-only"
          checked={isChecked}
          disabled={isDisabled}
          required={required}
          onChange={handleChange}
          {...props}
        />
        <div
          className={cn(
            base,
            sizes[size],
            roundedOptions[rounded],
            "self-center",
            // Use checked/indeterminate variant or default
            (isChecked || indeterminate) && !color ? checkedVariants[variant] : variants[variant],
            error && "border-destructive",
            focusRingClass,
            "outline-none",
            className
          )}
          style={{
            ...customColorStyles,
            ...(color &&
              (isChecked || indeterminate) && {
                borderColor: color,
                backgroundColor: color,
              }),
          }}
        >
          <div className="absolute inset-0 flex items-center justify-center">
            <CheckIcon
              className={cn(
                "text-primary-foreground",
                iconSizes[size],
                animation && "transition-all duration-200 ease-out",
                isChecked || indeterminate
                  ? animation
                    ? "scale-100 opacity-100"
                    : "opacity-100"
                  : animation
                    ? "scale-0 opacity-0"
                    : "opacity-0"
              )}
            />
          </div>
        </div>
      </div>
    );

    if (!label && !description) return checkboxElement;

    return (
      <div className="flex flex-col">
        <label
          className={cn(
            "flex cursor-pointer items-center gap-2 select-none",
            isDisabled && "cursor-not-allowed opacity-50",
            labelPosition === "left" && "flex-row-reverse"
          )}
        >
          <div className="flex flex-shrink-0 items-center">{checkboxElement}</div>
          <div className={cn("flex min-w-0 flex-col justify-center", textMinHeights[size])}>
            {label && (
              <span
                className={cn(
                  "text-foreground leading-tight font-medium",
                  labelSizes[size],
                  error && "text-destructive"
                )}
              >
                {label}
                {required && <span className="text-destructive ml-1">*</span>}
              </span>
            )}
            {description && (
              <span
                className={cn(
                  "text-muted-foreground leading-tight",
                  size === "xs" ? "text-xs" : "text-sm",
                  error && "text-destructive"
                )}
              >
                {description}
              </span>
            )}
          </div>
        </label>
        {error && errorMessage && (
          <span className="text-destructive mt-1 text-sm">{errorMessage}</span>
        )}
      </div>
    );
  }
);

Checkbox.displayName = "Checkbox";

// CheckboxGroup interfaces
export interface CheckboxGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  value?: string[];
  defaultValue?: string[];
  onChange?: (value: string[]) => void;
  options: CheckboxOption[];
  direction?: "horizontal" | "vertical";
  checkboxProps?: Partial<CheckboxProps>;
  label?: string;
  description?: string;
  error?: boolean;
  errorMessage?: string;
  enableSelectAll?: boolean;
  selectAllLabel?: string;
}

export interface CheckboxOption {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
  props?: Partial<CheckboxProps>;
}

export const CheckboxGroup = React.forwardRef<HTMLDivElement, CheckboxGroupProps>(
  (
    {
      value,
      defaultValue = [],
      onChange,
      options,
      direction = "vertical",
      checkboxProps = {},
      label,
      description,
      error = false,
      errorMessage,
      enableSelectAll = false,
      selectAllLabel = "Select All",
      className = "",
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = React.useState<string[]>(defaultValue);
    const selectedValues = value !== undefined ? value : internalValue;

    const handleOptionChange = (optionValue: string, checked: boolean) => {
      const newValues = checked
        ? [...selectedValues, optionValue]
        : selectedValues.filter(v => v !== optionValue);
      if (value === undefined) setInternalValue(newValues);
      onChange?.(newValues);
    };

    const handleSelectAllChange = (checked: boolean) => {
      const newValues = checked ? options.filter(opt => !opt.disabled).map(opt => opt.value) : [];
      if (value === undefined) setInternalValue(newValues);
      onChange?.(newValues);
    };

    const enabledOptions = options.filter(opt => !opt.disabled);
    const selectedEnabledCount = enabledOptions.filter(opt =>
      selectedValues.includes(opt.value)
    ).length;
    const allSelected = selectedEnabledCount === enabledOptions.length && enabledOptions.length > 0;
    const indeterminate = selectedEnabledCount > 0 && selectedEnabledCount < enabledOptions.length;

    return (
      <div ref={ref} className={cn("flex flex-col gap-2", className)} {...props}>
        {label && (
          <div className="flex flex-col">
            <span className={cn("text-foreground font-medium", error && "text-destructive")}>
              {label}
            </span>
            {description && (
              <span className={cn("text-muted-foreground text-sm", error && "text-destructive")}>
                {description}
              </span>
            )}
          </div>
        )}

        <div
          className={cn(
            "flex",
            direction === "horizontal" ? "flex-row flex-wrap gap-6" : "flex-col gap-2"
          )}
        >
          {enableSelectAll && (
            <div>
              <Checkbox
                {...checkboxProps}
                label={selectAllLabel}
                checked={allSelected}
                indeterminate={indeterminate}
                onChange={e => handleSelectAllChange(e.target.checked)}
                className="font-semibold"
              />
            </div>
          )}

          <div
            className={cn(
              "flex",
              direction === "horizontal" ? "flex-row flex-wrap gap-6" : "flex-col gap-2",
              enableSelectAll && "pl-5"
            )}
          >
            {options.map(option => (
              <Checkbox
                key={option.value}
                {...checkboxProps}
                {...option.props}
                label={option.label}
                description={option.description}
                disabled={option.disabled}
                checked={selectedValues.includes(option.value)}
                onChange={e => handleOptionChange(option.value, e.target.checked)}
              />
            ))}
          </div>
        </div>

        {error && errorMessage && <span className="text-destructive text-sm">{errorMessage}</span>}
      </div>
    );
  }
);

CheckboxGroup.displayName = "CheckboxGroup";

import React from "react";
import { FaCopy } from "react-icons/fa";
import { LiaCheckDoubleSolid } from "react-icons/lia";
import { Tooltip } from "@/components/ui/";
import { cn, tw } from "@/lib/utils";

export interface ClipboardProps {
  /**
   * The text content to copy to clipboard
   */
  value: string;
  /**
   * The visual style of the clipboard trigger
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "outline" | "ghost";
  /**
   * The size of the clipboard trigger
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Show only the icon without text
   * @default true
   */
  iconOnly?: boolean;
  /**
   * Tooltip content to show on hover
   * @default "Copy to clipboard"
   */
  tooltip?: string;
  /**
   * Show visual feedback when text is copied
   * @default true
   */
  showFeedback?: boolean;
  /**
   * Custom feedback text to display
   * @default "Copied!"
   */
  feedbackText?: string;
  /**
   * Duration in milliseconds to show feedback
   * @default 2000
   */
  feedbackDuration?: number;
  /**
   * Callback fired when text is successfully copied
   */
  onCopy?: (value: string) => void;
  /**
   * Callback fired when copy fails
   */
  onError?: (error: Error) => void;
  /**
   * Disable the clipboard functionality
   * @default false
   */
  disabled?: boolean;
  /**
   * Animation effect on user interaction
   * @default "none"
   */
  animation?: "none" | "scale" | "glow" | "press";
  /**
   * Control the border radius
   * @default "md"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Additional CSS classes
   */
  className?: string;
}

const base = tw`relative inline-flex transform-gpu cursor-pointer items-center justify-center transition-all duration-200 select-none focus:outline-none disabled:pointer-events-none disabled:opacity-50`;

const variants = {
  primary: tw`rui-focus-ring bg-primary p-2 text-primary-foreground shadow-sm hover:bg-primary/90 hover:shadow-md`,
  secondary: tw`rui-focus-ring bg-secondary p-2 text-secondary-foreground shadow-sm hover:bg-secondary/80 hover:shadow-md`,
  outline: tw`rui-focus-ring border border-primary bg-transparent p-2 text-primary hover:bg-primary/10`,
  ghost: tw`rui-focus-ring bg-transparent p-2 text-muted-foreground hover:bg-accent hover:text-accent-foreground`,
};

const sizes = {
  sm: tw`text-sm`,
  md: tw`text-base`,
  lg: tw`text-lg`,
};

// Modified animations to work better with state changes
const animations = {
  none: tw``,
  scale: tw`transition-transform duration-150 ease-out hover:scale-105 active:scale-95`,
  glow: tw`transition-shadow duration-200 ease-out hover:shadow-lg hover:shadow-primary/25`,
  press: tw`transition-transform duration-200 ease-out active:scale-95`,
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

// Helper function to get color classes based on variant and copied state
const getColorClass = (variant: string, isCopied: boolean, showFeedback: boolean) => {
  // For outline variant, text should be primary-foreground when copied
  if (variant === "outline" && isCopied && showFeedback) {
    return "text-primary-foreground";
  }

  // Default colors for each variant
  switch (variant) {
    case "primary":
      return "text-primary-foreground";
    case "secondary":
      return "text-secondary-foreground";
    case "outline":
      return "text-primary";
    case "ghost":
      return "text-muted-foreground";
    default:
      return "text-muted-foreground";
  }
};

export const Clipboard = React.forwardRef<HTMLButtonElement, ClipboardProps>(
  (
    {
      value,
      variant = "primary",
      size = "md",
      iconOnly = true,
      tooltip = "Copy to clipboard",
      showFeedback = true,
      feedbackText = "Copied!",
      feedbackDuration = 2000,
      onCopy,
      onError,
      disabled = false,
      rounded = "md",
      animation = "none",
      className = "",
      ...props
    },
    ref
  ) => {
    const [isCopied, setIsCopied] = React.useState(false);
    const timeoutRef = React.useRef<NodeJS.Timeout | null>(null);

    const handleCopy = React.useCallback(async () => {
      if (disabled) return;

      try {
        await navigator.clipboard.writeText(value);
        setIsCopied(true);
        onCopy?.(value);

        // Clear any existing timeout
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }

        // Set timeout to hide feedback
        timeoutRef.current = setTimeout(() => {
          setIsCopied(false);
        }, feedbackDuration);
      } catch (error) {
        onError?.(error as Error);
      }
    }, [value, disabled, onCopy, onError, feedbackDuration]);

    // Cleanup timeout on unmount
    React.useEffect(() => {
      return () => {
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
      };
    }, []);

    const iconSize = size === "sm" ? 14 : size === "lg" ? 18 : 16;

    // Create a fixed-width container for icons to prevent layout shift
    const icon = (
      <div
        className="relative inline-flex flex-shrink-0 items-center justify-center"
        style={{ width: iconSize, height: iconSize }}
      >
        <FaCopy
          size={iconSize}
          className={cn(
            "absolute transition-all duration-300 ease-out",
            isCopied && showFeedback ? "scale-0 opacity-0" : "scale-100 opacity-100",
            getColorClass(variant, isCopied, showFeedback)
          )}
        />
        <LiaCheckDoubleSolid
          size={iconSize}
          className={cn(
            "absolute transition-all duration-300 ease-out",
            isCopied && showFeedback ? "scale-100 opacity-100" : "scale-0 opacity-0",
            getColorClass(variant, isCopied, showFeedback)
          )}
        />
      </div>
    );

    // Create fixed-width text container to prevent layout shift
    const textContent = !iconOnly && (
      <span
        className="relative ml-1.5 flex-shrink-0 overflow-hidden transition-all duration-300"
        style={{
          minWidth: Math.max(feedbackText.length * 0.6, "Copy".length * 0.6) + "rem",
          height: size === "sm" ? "1rem" : size === "lg" ? "1.25rem" : "1.125rem",
        }}
      >
        <span
          className={cn(
            "absolute inset-0 flex items-center transition-all duration-300",
            isCopied && showFeedback ? "translate-y-2 opacity-0" : "translate-y-0 opacity-100",
            getColorClass(variant, false, false) // Use default color for "Copy" text
          )}
        >
          Copy
        </span>
        <span
          className={cn(
            "absolute inset-0 flex items-center transition-all duration-300",
            isCopied && showFeedback ? "translate-y-0 opacity-100" : "-translate-y-2 opacity-0",
            getColorClass(variant, isCopied, showFeedback) // Use appropriate color for feedback text
          )}
        >
          {feedbackText}
        </span>
      </span>
    );

    const buttonContent = (
      <button
        ref={ref}
        className={cn(
          base,
          sizes[size],
          roundedOptions[rounded],
          // Always apply animations, but conditionally apply hover states
          animations[animation],
          // Apply base variant styles
          variants[variant],
          // Apply copied state overrides
          isCopied &&
            showFeedback &&
            [
              // Override hover states when copied
              "hover:scale-100 active:scale-100", // Reset scale transforms
              "hover:-translate-y-0", // Reset lift transforms
              // Apply copied visual state
              variant === "primary" && "bg-primary/80 shadow-md",
              variant === "secondary" && "bg-secondary shadow-md",
              variant === "outline" &&
                "border-primary bg-primary text-primary-foreground hover:bg-primary shadow-md",
            ].filter(Boolean),
          className
        )}
        disabled={disabled}
        onClick={handleCopy}
        aria-label={isCopied && showFeedback ? feedbackText : "Copy to clipboard"}
        style={{
          // Prevent layout shift by maintaining consistent dimensions
          minHeight: size === "sm" ? "2rem" : size === "lg" ? "2.75rem" : "2.25rem",
        }}
        {...props}
      >
        {icon}
        {textContent}
      </button>
    );

    if (tooltip) {
      return (
        <Tooltip content={isCopied && showFeedback ? feedbackText : tooltip} position="top">
          {buttonContent}
        </Tooltip>
      );
    }

    return buttonContent;
  }
);

Clipboard.displayName = "Clipboard";

import React, { createContext, useContext, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cn, tw } from "@/lib/utils";

// ContextMenu Context
interface ContextMenuContextType {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  position: { x: number; y: number };
  setPosition: (position: { x: number; y: number }) => void;
}

const ContextMenuContext = createContext<ContextMenuContextType | null>(null);

const useContextMenu = () => {
  const context = useContext(ContextMenuContext);
  if (!context) {
    throw new Error("ContextMenu components must be used within a ContextMenu");
  }
  return context;
};

// Base styles (same as Dropdown)
const contentBase = tw`z-50 min-w-[8rem] overflow-hidden rounded-md border border-border bg-popover text-popover-foreground p-1 shadow-md`;
const itemBase = tw`relative flex w-full cursor-pointer items-center rounded-sm px-2 py-1.5 text-sm transition-colors outline-none select-none hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground disabled:pointer-events-none disabled:opacity-50`;
const labelBase = tw`px-2 py-1.5 text-sm font-semibold text-foreground`;
const separatorBase = tw`-mx-1 my-1 h-px bg-border`;

// Animation classes
const contentAnimation = tw`animate-in fade-in-0 zoom-in-95 duration-150 ease-out`;

export interface ContextMenuProps {
  /**
   * Context menu content
   */
  children: React.ReactNode;
  /**
   * Whether the context menu is open (controlled)
   */
  open?: boolean;
  /**
   * Default open state
   */
  defaultOpen?: boolean;
  /**
   * Callback when open state changes
   */
  onOpenChange?: (open: boolean) => void;
}

export interface ContextMenuTriggerProps {
  /**
   * Trigger element content
   */
  children: React.ReactNode;
  /**
   * Whether to disable the context menu
   */
  disabled?: boolean;
}

export interface ContextMenuContentProps {
  /**
   * Content to display in the context menu
   */
  children: React.ReactNode;
  /**
   * Custom class name
   */
  className?: string;
}

export interface ContextMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Whether the item is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Callback when item is selected
   */
  onSelect?: () => void;
}

export interface ContextMenuLabelProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Label text
   */
  children: React.ReactNode;
}

export interface ContextMenuSeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Custom class name
   */
  className?: string;
}

export interface ContextMenuGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Group content
   */
  children: React.ReactNode;
}

// ContextMenu main component
export const ContextMenu: React.FC<ContextMenuProps> = ({
  children,
  open,
  defaultOpen = false,
  onOpenChange,
}) => {
  const [isOpen, setIsOpen] = useState(open ?? defaultOpen);
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const handleOpenChange = React.useCallback(
    (newOpen: boolean) => {
      if (open === undefined) {
        setIsOpen(newOpen);
      }
      onOpenChange?.(newOpen);
    },
    [open, onOpenChange]
  );

  // Update controlled state
  useEffect(() => {
    if (open !== undefined) {
      setIsOpen(open);
    }
  }, [open]);

  // Close on outside click or escape
  useEffect(() => {
    const handleClickOutside = () => {
      handleOpenChange(false);
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handleOpenChange(false);
      }
    };

    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleKeyDown);
      return () => {
        document.removeEventListener("mousedown", handleClickOutside);
        document.removeEventListener("keydown", handleKeyDown);
      };
    }
  }, [isOpen, handleOpenChange]);

  const contextValue: ContextMenuContextType = {
    isOpen,
    setIsOpen: handleOpenChange,
    position,
    setPosition,
  };

  return <ContextMenuContext.Provider value={contextValue}>{children}</ContextMenuContext.Provider>;
};

// ContextMenuTrigger component
export const ContextMenuTrigger = React.forwardRef<HTMLDivElement, ContextMenuTriggerProps>(
  ({ children, disabled = false, ...props }, ref) => {
    const { setIsOpen, setPosition } = useContextMenu();

    const handleContextMenu = (event: React.MouseEvent) => {
      if (disabled) return;

      event.preventDefault();
      event.stopPropagation();

      const x = event.clientX;
      const y = event.clientY;

      setPosition({ x, y });
      setIsOpen(true);
    };

    return (
      <div ref={ref} onContextMenu={handleContextMenu} {...props}>
        {children}
      </div>
    );
  }
);

ContextMenuTrigger.displayName = "ContextMenuTrigger";

// ContextMenuContent component
export const ContextMenuContent = React.forwardRef<HTMLDivElement, ContextMenuContentProps>(
  ({ className, children, ...props }, ref) => {
    const { isOpen, position } = useContextMenu();
    const contentRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [finalPosition, setFinalPosition] = useState({ x: 0, y: 0 });

    useEffect(() => {
      if (isOpen) {
        setIsVisible(false);

        // Use double requestAnimationFrame to ensure content is fully rendered
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            if (contentRef.current) {
              const contentRect = contentRef.current.getBoundingClientRect();
              const viewportWidth = window.innerWidth;
              const viewportHeight = window.innerHeight;

              let x = position.x;
              let y = position.y;

              // Adjust horizontal position if needed
              if (x + contentRect.width > viewportWidth) {
                x = viewportWidth - contentRect.width - 8; // 8px margin from edge
              }

              // Adjust vertical position if needed
              if (y + contentRect.height > viewportHeight) {
                y = viewportHeight - contentRect.height - 8; // 8px margin from edge
              }

              // Ensure minimum margins from edges
              x = Math.max(8, x);
              y = Math.max(8, y);

              setFinalPosition({ x, y });
              setIsVisible(true);
            }
          });
        });
      } else {
        setIsVisible(false);
      }
    }, [isOpen, position]);

    if (!isOpen) return null;

    // Render off-screen first to measure, then position correctly
    return createPortal(
      <>
        {/* Hidden measurement element */}
        <div
          ref={contentRef}
          className={cn(contentBase, "fixed", className)}
          style={{
            left: "-9999px",
            top: "-9999px",
            visibility: "hidden",
            pointerEvents: "none",
          }}
          data-context-menu-measure
        >
          {children}
        </div>

        {/* Visible positioned element */}
        {isVisible && (
          <div
            ref={node => {
              if (typeof ref === "function") ref(node);
              else if (ref) ref.current = node;
            }}
            className={cn(contentBase, contentAnimation, "fixed", className)}
            data-context-menu-content
            role="menu"
            style={{
              left: finalPosition.x,
              top: finalPosition.y,
            }}
            {...props}
          >
            {children}
          </div>
        )}
      </>,
      document.body
    );
  }
);

ContextMenuContent.displayName = "ContextMenuContent";

// ContextMenuItem component
export const ContextMenuItem = React.forwardRef<HTMLButtonElement, ContextMenuItemProps>(
  ({ className, disabled = false, onSelect, children, ...props }, ref) => {
    const { setIsOpen } = useContextMenu();

    const handleClick = () => {
      if (!disabled) {
        onSelect?.();
        setIsOpen(false);
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        handleClick();
      }
    };

    return (
      <button
        ref={ref}
        type="button"
        className={cn(itemBase, className)}
        disabled={disabled}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        role="menuitem"
        {...props}
      >
        {children}
      </button>
    );
  }
);

ContextMenuItem.displayName = "ContextMenuItem";

// ContextMenuLabel component
export const ContextMenuLabel: React.FC<ContextMenuLabelProps> = ({ className, ...props }) => {
  return <div className={cn(labelBase, className)} role="group" {...props} />;
};

// ContextMenuSeparator component
export const ContextMenuSeparator: React.FC<ContextMenuSeparatorProps> = ({
  className,
  ...props
}) => {
  return <div className={cn(separatorBase, className)} role="separator" {...props} />;
};

// ContextMenuGroup component
export const ContextMenuGroup: React.FC<ContextMenuGroupProps> = ({ className, ...props }) => {
  return <div className={cn(className)} role="group" {...props} />;
};

