  sm: tw`text-sm`,
  md: tw`text-sm`,
  lg: tw`text-base`,
  xl: tw`text-base`,
};
const widths = {
  sm: tw`w-64`,
  md: tw`w-80`,
  lg: tw`w-96`,
  xl: tw`w-[30rem]`,
} as const;

// Token placeholders for empty segments
const TOKEN_DD = "DD";
const TOKEN_MM = "MM";
const TOKEN_YYYY = "YYYY";

// Helpers
function clampToDay(d: Date) {
  const x = new Date(d);
  x.setHours(12, 0, 0, 0);
  return x;
}

function inRange(date: Date, minDate?: Date, maxDate?: Date) {
  const d = clampToDay(date);
  if (minDate && isBefore(d, clampToDay(minDate))) return false;
  if (maxDate && isAfter(d, clampToDay(maxDate))) return false;
  return true;
}

function parseMMDDYYYY(text: string): Date | null {
  if (!/^\d{2}\/\d{2}\/\d{4}$/.test(text)) return null;
  // Interpret as DD/MM/YYYY for this component
  const parsed = parse(text, "dd/MM/yyyy", new Date());
  if (!isValid(parsed)) return null;
  return parsed;
}

export const DatePicker: React.FC<DatePickerProps> = ({
  value,
  onChange,
  minDate,
  maxDate: maxDateProp,
  label,
  description,
  error,
  disabled,
  placeholder = "MM/DD/YYYY",
  withCalendar = true,
  order = "dmy",
  variant = "primary",
  size = "md",
  rounded = "sm",
  fullWidth = false,
  width = "md",
  className = "",
  id,
}) => {
  const autoId = React.useId();
  const inputId = id ?? autoId;

  // Refs for inputs
  const mmRef = React.useRef<HTMLInputElement | null>(null);
  const ddRef = React.useRef<HTMLInputElement | null>(null);
  const yyyyRef = React.useRef<HTMLInputElement | null>(null);

  const today = React.useMemo(() => new Date(), []);
  const maxDate = React.useMemo(() => (maxDateProp ? maxDateProp : today), [maxDateProp, today]);

  // Internal segment state
  const [dd, setDD] = React.useState<string>(value ? format(value, "dd") : "");
  const [mm, setMM] = React.useState<string>(value ? format(value, "MM") : "");
  const [yyyy, setYYYY] = React.useState<string>(value ? format(value, "yyyy") : "");

  const [open, setOpen] = React.useState(false);
  const [activeSeg, setActiveSeg] = React.useState<0 | 1 | 2>(0); // 0=DD,1=MM,2=YYYY
  const [touched, setTouched] = React.useState(false);

  // Keep segments in sync with controlled value
  React.useEffect(() => {
    if (!value) {
      setMM("");
      setDD("");
      setYYYY("");
      return;
    }
    const nextDD = format(value, "dd");
    const nextMM = format(value, "MM");
    const nextYYYY = format(value, "yyyy");
    if (dd !== nextDD) setDD(nextDD);
    if (mm !== nextMM) setMM(nextMM);
    if (yyyy !== nextYYYY) setYYYY(nextYYYY);
  }, [value, dd, mm, yyyy]);

  const hasAssistive = Boolean(description || error);
  const assistiveId = `${inputId}-desc`;

  const text = React.useMemo(() => {
    const parts = [dd, mm, yyyy];
    const filled = parts.every(p => p.length > 0);
    return filled ? `${dd}/${mm}/${yyyy}` : "";
  }, [dd, mm, yyyy]);

  const currentDate = React.useMemo(() => parseMMDDYYYY(text), [text]);
  const isValidDate = React.useMemo(() => {
    if (!currentDate) return false;
    return inRange(currentDate, minDate, maxDate);
  }, [currentDate, minDate, maxDate]);

  // Display helpers: show leading zero visually for 1-digit segments
  // const ddDisplay = dd.length === 1 ? `0${dd}` : dd;
  // const mmDisplay = mm.length === 1 ? `0${mm}` : mm;
  // const yyyyDisplay =
  //     yyyy.length > 0 && yyyy.length < 4 ? yyyy.padStart(4, "0") : yyyy;

  const anyFilled = mm.length > 0 || dd.length > 0 || yyyy.length > 0;
  const isComplete = dd.length === 2 && mm.length === 2 && yyyy.length === 4;
  const showError = Boolean(error || (touched && isComplete && !isValidDate));
  const errorMessage = error || (!isValidDate && isComplete ? "Invalid date" : undefined);

  const focusSeg = (seg: 0 | 1 | 2) => {
    setActiveSeg(seg);
    requestAnimationFrame(() => {
      if (seg === 0) ddRef.current?.select();
      else if (seg === 1) mmRef.current?.select();
      else yyyyRef.current?.select();
    });
  };

  // Order-aware navigation
  const orderSeq: (0 | 1 | 2)[] = React.useMemo(() => {
    if (order === "mdy") return [1, 0, 2];
    if (order === "ymd") return [2, 1, 0];
    return [0, 1, 2]; // dmy
  }, [order]);
  const movePrev = () => {
    const idx = orderSeq.indexOf(activeSeg as 0 | 1 | 2);
    const prevIdx = Math.max(0, idx - 1);
    focusSeg(orderSeq[prevIdx]);
  };
  const moveNext = () => {
    const idx = orderSeq.indexOf(activeSeg as 0 | 1 | 2);
    const nextIdx = Math.min(orderSeq.length - 1, idx + 1);
    focusSeg(orderSeq[nextIdx]);
  };

  const normalizeDigits = (s: string) => s.replace(/[^0-9]/g, "");

  const commitIfValid = (ddStr: string, mmStr: string, yyyyStr: string) => {
    const filled = ddStr.length === 2 && mmStr.length === 2 && yyyyStr.length === 4;
    if (!filled) return;
    const nextText = `${ddStr}/${mmStr}/${yyyyStr}`;
    const d = parseMMDDYYYY(nextText);
    if (d && inRange(d, minDate, maxDate)) {
      if (!value || !isSameDay(value, d)) onChange?.(d);
    }
  };

  const clearAll = () => {
    setMM("");
    setDD("");
    setYYYY("");
    onChange?.(null);
  };

  const handleFocusField = (seg: 0 | 1 | 2) => {
    setTouched(true);
    focusSeg(seg);
  };

  const handleKeyDownField = (e: React.KeyboardEvent<HTMLInputElement>, seg: 0 | 1 | 2) => {
    if (disabled) return;
    const key = e.key;
    // Navigation
    if (key === "ArrowLeft") {
      e.preventDefault();
      setActiveSeg(seg);
      movePrev();
      return;
    }
    if (key === "ArrowRight") {
      e.preventDefault();
      setActiveSeg(seg);
      moveNext();
      return;
    }
    if (key === "/") {
      e.preventDefault();
      moveNext();
      return;
    }
    if (key === "Delete") {
      e.preventDefault();
      clearAll();
      return;
    }
    if (key === "Backspace") {
      const val = seg === 0 ? dd : seg === 1 ? mm : yyyy;
      if (val.length === 0) {
        // Jump back if the current segment is empty
        e.preventDefault();
        movePrev();
        return;
      }
    }
  };

  const onChangeDD: React.ChangeEventHandler<HTMLInputElement> = e => {
    // Allow user to type a single digit; when our UI shows 0x and user types another digit,
    // the input might become 0xD -> take the last two digits to form the intended value.
    let raw = normalizeDigits(e.target.value);
    if (raw.length > 2) raw = raw.slice(-2);
    let digits = raw;
    // Clamp only when 2 digits available
    if (digits.length === 2) {
      let n = Number(digits);
      if (n < 1) n = 1;
      if (n > 31) n = 31;
      digits = n.toString().padStart(2, "0");
    }
    setDD(digits);
    if (digits.length === 2) moveNext();
    commitIfValid(digits, mm, yyyy);
  };
  const onChangeMM: React.ChangeEventHandler<HTMLInputElement> = e => {
    // Similar behavior to day: allow single digit, and handle UI-prepended zero by using last two digits
    let raw = normalizeDigits(e.target.value);
    if (raw.length > 2) raw = raw.slice(-2);
    let digits = raw;
    // Clamp only when 2 digits available
    if (digits.length === 2) {
      let n = Number(digits);
      if (n < 1) n = 1;
      if (n > 12) n = 12;
      digits = n.toString().padStart(2, "0");
    }
    setMM(digits);
    if (digits.length === 2) moveNext();
    commitIfValid(dd, digits, yyyy);
  };
  const onChangeYYYY: React.ChangeEventHandler<HTMLInputElement> = e => {
    // Allow progressive typing; when UI shows leading zeros, use last 4 typed digits
    let raw = normalizeDigits(e.target.value);
    if (raw.length > 4) raw = raw.slice(-4);
    setYYYY(raw);
    // Only commit when 4 digits present; also auto-advance to next segment if any (e.g., order="ymd")
    if (raw.length === 4) {
      commitIfValid(dd, mm, raw);
      moveNext();
    }
  };

  const handleBlurField: React.FocusEventHandler<HTMLInputElement> = () => {
    if (!anyFilled) {
      onChange?.(null);
      return;
    }
    // Do not auto-commit on blur to avoid focus jumps; only commit via input completion
    commitIfValid(dd, mm, yyyy);
  };

  // Popover and calendar
  const popRef = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      const target = e.target as Node;
      if (popRef.current && !popRef.current.contains(target)) {
        // If click occurs outside the popover, close
        setOpen(false);
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <div className={cn(wrapperBase, fullWidth ? "w-full" : (widths[width] ?? "w-auto"))}>
      {label && (
        <label
          htmlFor={inputId}
          className={cn(
            "text-foreground mb-1 font-medium",
            labelSizes[size],
            showError && "text-destructive"
          )}
        >
          {label}
        </label>
      )}
      <div
        className={cn(
          fieldBase,
          variants[variant],
          sizes[size].container,
          roundedOptions[rounded],
          sizes[size].padX,
          "gap-0.5", // tighter spacing between segments
          showError && "rui-field-error border-destructive",
          fullWidth && "w-full",
          className
        )}
        onMouseDown={e => {
          if (disabled) return;
          const target = e.target as HTMLElement;
          const hitInput = target.closest("input");
          const hitButton = target.closest("button");
          if (!hitInput && !hitButton) {
            // Focus the first segment based on order
            e.preventDefault();
            if (order === "mdy") mmRef.current?.focus();
            else if (order === "ymd") yyyyRef.current?.focus();
            else ddRef.current?.focus();
          }
        }}
      >
        {/* Segment inputs rendered based on order prop */}
        {(() => {
          const parts: Array<React.ReactElement> = [];
          const pushSep = () =>
            parts.push(
              <span
                key={`sep-${parts.length}`}
                aria-hidden
                className="text-muted-foreground/60 px-0 select-none"
              >
                /
              </span>
            );
          const pushDD = () =>
            parts.push(
              <input
                key="dd"
                ref={ddRef}
                id={inputId}
                value={dd}
                placeholder={TOKEN_DD}
                onFocus={() => handleFocusField(0)}
                onKeyDown={e => handleKeyDownField(e, 0)}
                onBlur={handleBlurField}
                onChange={onChangeDD}
                inputMode="numeric"
                aria-invalid={showError || undefined}
                aria-describedby={hasAssistive ? assistiveId : undefined}
                disabled={disabled}
                className={cn(
                  "w-9 min-w-0 bg-transparent text-center outline-none",
                  "placeholder:text-muted-foreground placeholder:font-light",
                  sizes[size].input
                )}
              />
            );
          const pushMM = () =>
            parts.push(
              <input
                key="mm"
                ref={mmRef}
                value={mm}
                placeholder={TOKEN_MM}
                onFocus={() => handleFocusField(1)}
                onKeyDown={e => handleKeyDownField(e, 1)}
                onBlur={handleBlurField}
                onChange={onChangeMM}
                inputMode="numeric"
                disabled={disabled}
                className={cn(
                  "w-9 min-w-0 bg-transparent text-center outline-none",
                  "placeholder:text-muted-foreground placeholder:font-light",
                  sizes[size].input
                )}
              />
            );
          const pushYYYY = () =>
            parts.push(
              <input
                key="yyyy"
                ref={yyyyRef}
                value={yyyy}
                placeholder={TOKEN_YYYY}
                onFocus={() => handleFocusField(2)}
                onKeyDown={e => handleKeyDownField(e, 2)}
                onBlur={handleBlurField}
                onChange={onChangeYYYY}
                inputMode="numeric"
                disabled={disabled}
                className={cn(
                  "w-16 min-w-0 bg-transparent text-center outline-none",
                  "placeholder:text-muted-foreground placeholder:font-light",
                  sizes[size].input
                )}
              />
            );

          const addOrdered = (first: () => void, second: () => void, third: () => void) => {
            first();
            pushSep();
            second();
            pushSep();
            third();
          };

          if (order === "mdy") addOrdered(pushMM, pushDD, pushYYYY);
          else if (order === "ymd") addOrdered(pushYYYY, pushMM, pushDD);
          else addOrdered(pushDD, pushMM, pushYYYY); // default dmy

          return parts;
        })()}

        {/* Calendar toggle button */}
        {withCalendar && (
          <button
            type="button"
            aria-label="Open calendar"
            onClick={() => setOpen(v => !v)}
            disabled={disabled}
            className={cn(
              "text-muted-foreground hover:bg-accent hover:text-accent-foreground rui-focus-ring ml-auto inline-flex items-center justify-center rounded-md",
              iconBtnSizes[size]
            )}
          >
            <HiOutlineCalendar />
          </button>
        )}

        {/* Popover */}
        {withCalendar && open && (
          <div
            ref={popRef}
            className={tw`animate-in fade-in zoom-in-95 border-border bg-popover text-popover-foreground absolute top-[calc(100%+6px)] left-0 z-50 w-max rounded-md border shadow-md duration-150`}
            role="dialog"
            aria-modal={false}
          >
            <Calendar
              selectedDate={currentDate ?? undefined}
              minDate={minDate}
              maxDate={maxDate}
              onDateSelect={(d: Date) => {
                const ndd = format(d, "dd");
                const nmm = format(d, "MM");
                const nyyyy = format(d, "yyyy");
                setDD(ndd);
                setMM(nmm);
                setYYYY(nyyyy);
                onChange?.(d);
                setOpen(false);
                // Focus back to first segment based on order for quick edits
                requestAnimationFrame(() => {
                  if (order === "mdy") mmRef.current?.focus();
                  else if (order === "ymd") yyyyRef.current?.focus();
                  else ddRef.current?.focus();
                });
              }}
            />
          </div>
        )}
      </div>

      {hasAssistive && (
        <div id={assistiveId} className="mt-1 min-h-[1rem]">
          {showError && errorMessage ? (
            <span className="text-destructive text-sm">{errorMessage}</span>
          ) : description ? (
            <span className="text-muted-foreground text-sm">{description}</span>
          ) : null}
        </div>
      )}
    </div>
  );
};

DatePicker.displayName = "DatePicker";

export default DatePicker;

import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { IoClose } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

export interface DrawerProps {
  /**
   * Whether the drawer is open
   */
  open: boolean;
  /**
   * Callback when drawer should close
   */
  onClose: () => void;
  /**
   * The position of the drawer
   * @default "right"
   */
  position?: "left" | "right" | "top" | "bottom";
  /**
   * The size of the drawer (width for left/right, height for top/bottom)
   * @default "md"
   */
  size?: "sm" | "md" | "lg" | "xl" | "full";
  /**
   * The visual style of the drawer
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * Control the border radius of the drawer
   * @default "none"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Prevent closing when clicking outside the drawer
   * @default false
   */
  preventClose?: boolean;
  /**
   * Hide the close button
   * @default false
   */
  hideCloseButton?: boolean;
  /**
   * Drawer title displayed in the header
   */
  title?: string;
  /**
   * Optional header content (overrides title)
   */
  header?: React.ReactNode;
  /**
   * Optional footer content
   */
  footer?: React.ReactNode;
  /**
   * Main drawer content
   */
  children: React.ReactNode;
  /**
   * Custom class name for the drawer container
   */
  className?: string;
  /**
   * Custom class name for the overlay
   */
  overlayClassName?: string;
  /**
   * ID for the drawer element
   */
  id?: string;
  /**
   * Aria label for accessibility
   */
  ariaLabel?: string;
  /**
   * Aria labelledby for accessibility
   */
  ariaLabelledBy?: string;
  /**
   * Aria describedby for accessibility
   */
  ariaDescribedBy?: string;
}

// Base styles
const overlayBase = tw`fixed inset-0 z-50 bg-black/50 backdrop-blur-sm`;
const drawerBase = tw`absolute flex flex-col bg-background text-foreground shadow-lg outline-none`;
const headerBase = tw`flex items-center justify-between border-b border-border px-6 py-4`;
const bodyBase = tw`flex-1 overflow-y-auto px-6 py-5 text-sm text-foreground/90`;
const footerBase = tw`border-t border-border px-6 py-4`;
const closeButtonBase = tw`rounded-md p-1.5 text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground rui-focus-ring focus:outline-none`;

// Variants
const variants = {
  primary: tw`border-border`,
  secondary: tw`border-border bg-muted`,
};

// Positions
const positions = {
  left: tw`top-0 left-0 h-full`,
  right: tw`top-0 right-0 h-full`,
  top: tw`top-0 left-0 w-full`,
  bottom: tw`bottom-0 left-0 w-full`,
};

// Sizes
const sizes = {
  left: {
    sm: tw`w-80`,
    md: tw`w-96`,
    lg: tw`w-[28rem]`,
    xl: tw`w-[32rem]`,
    full: tw`w-full`,
  },
  right: {
    sm: tw`w-80`,
    md: tw`w-96`,
    lg: tw`w-[28rem]`,
    xl: tw`w-[32rem]`,
    full: tw`w-full`,
  },
  top: {
    sm: tw`h-80`,
    md: tw`h-96`,
    lg: tw`h-[28rem]`,
    xl: tw`h-[32rem]`,
    full: tw`h-full`,
  },
  bottom: {
    sm: tw`h-80`,
    md: tw`h-96`,
    lg: tw`h-[28rem]`,
    xl: tw`h-[32rem]`,
    full: tw`h-full`,
  },
};

// Rounded options
const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
};

// Animation classes
const overlayAnimations = {
  enter: tw`animate-in fade-in-0 duration-200 ease-out`,
  exit: tw`animate-out fade-out-0 duration-150 ease-in`,
};

const drawerAnimations = {
  left: {
    enter: tw`animate-in slide-in-from-left-2 duration-200 ease-out`,
    exit: tw`animate-out slide-out-to-left-2 duration-150 ease-in`,
  },
  right: {
    enter: tw`animate-in slide-in-from-right-2 duration-200 ease-out`,
    exit: tw`animate-out slide-out-to-right-2 duration-150 ease-in`,
  },
  top: {
    enter: tw`animate-in slide-in-from-top-2 duration-200 ease-out`,
    exit: tw`animate-out slide-out-to-top-2 duration-150 ease-in`,
  },
  bottom: {
    enter: tw`animate-in slide-in-from-bottom-2 duration-200 ease-out`,
    exit: tw`animate-out slide-out-to-bottom-2 duration-150 ease-in`,
  },
};

export const Drawer = React.forwardRef<HTMLDivElement, DrawerProps>(
  (
    {
      open,
      onClose,
      position = "right",
      size = "md",
      variant = "primary",
      rounded = "none",
      animation = true,
      preventClose = false,
      hideCloseButton = false,
      title,
      header,
      footer,
      children,
      className = "",
      overlayClassName = "",
      id,
      ariaLabel,
      ariaLabelledBy,
      ariaDescribedBy,
      ...props
    },
    ref
  ) => {
    const drawerRef = useRef<HTMLDivElement>(null);
    const previousFocusRef = useRef<HTMLElement | null>(null);

    const autoId = React.useId();
    const drawerId = id ?? autoId;
    const titleId = `${drawerId}-title`;
    const descId = `${drawerId}-description`;

    // Focus management
    useEffect(() => {
      if (open) {
        // Store the previously focused element
        previousFocusRef.current = document.activeElement as HTMLElement;

        // Focus the drawer container
        setTimeout(() => {
          drawerRef.current?.focus();
        }, 50);
      } else if (previousFocusRef.current) {
        // Return focus to the previously focused element
        previousFocusRef.current.focus();
      }
    }, [open]);

    // Handle escape key
    useEffect(() => {
      const handleKeyDown = (event: KeyboardEvent) => {
        if (event.key === "Escape" && open && !preventClose) {
          onClose();
        }
      };

      if (open) {
        document.addEventListener("keydown", handleKeyDown);
        return () => document.removeEventListener("keydown", handleKeyDown);
      }
    }, [open, onClose, preventClose]);

    // Prevent body scroll when drawer is open
    useEffect(() => {
      if (open) {
        const originalStyle = window.getComputedStyle(document.body).overflow;
        document.body.style.overflow = "hidden";
        return () => {
          document.body.style.overflow = originalStyle;
        };
      }
    }, [open]);

    // Handle overlay click
    const handleOverlayClick = (event: React.MouseEvent) => {
      if (event.target === event.currentTarget && !preventClose) {
        onClose();
      }
    };

    // Focus trap for accessibility
    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (event.key === "Tab") {
        const drawer = drawerRef.current;
        if (!drawer) return;

        const focusableElements = drawer.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        const firstFocusable = focusableElements[0] as HTMLElement;
        const lastFocusable = focusableElements[focusableElements.length - 1] as HTMLElement;

        if (event.shiftKey) {
          if (document.activeElement === firstFocusable) {
            event.preventDefault();
            lastFocusable?.focus();
          }
        } else {
          if (document.activeElement === lastFocusable) {
            event.preventDefault();
            firstFocusable?.focus();
          }
        }
      }
    };

    // Support exit animations by keeping mounted until animation completes
    const [isMounted, setIsMounted] = useState(open);
    const [isAnimatingOut, setIsAnimatingOut] = useState(false);

    useEffect(() => {
      if (open) {
        setIsMounted(true);
        setIsAnimatingOut(false);
      } else if (animation) {
        setIsAnimatingOut(true);
        const t = setTimeout(() => {
          setIsMounted(false);
          setIsAnimatingOut(false);
        }, 160); // match duration-150 + small buffer
        return () => clearTimeout(t);
      } else {
        setIsMounted(false);
      }
    }, [open, animation]);

    if (!isMounted) return null;

    const drawerClasses = cn(
      drawerBase,
      positions[position],
      sizes[position][size],
      variants[variant],
      roundedOptions[rounded],
      animation &&
        (isAnimatingOut ? drawerAnimations[position].exit : drawerAnimations[position].enter),
      className
    );

    const overlayClasses = cn(
      overlayBase,
      animation && (isAnimatingOut ? overlayAnimations.exit : overlayAnimations.enter),
      overlayClassName
    );

    const drawerContent = (
      <div
        className={overlayClasses}
        onClick={handleOverlayClick}
        role="dialog"
        aria-modal="true"
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy || (title ? titleId : undefined)}
        aria-describedby={ariaDescribedBy || descId}
      >
        <div
          ref={ref || drawerRef}
          className={drawerClasses}
          tabIndex={-1}
          onKeyDown={handleKeyDown}
          id={drawerId}
          {...props}
        >
          {/* Header */}
          {(header || title || !hideCloseButton) && (
            <div className={headerBase}>
              <div className="min-w-0 flex-1">
                {header ||
                  (title && (
                    <h2 id={titleId} className="text-foreground truncate text-lg font-semibold">
                      {title}
                    </h2>
                  ))}
              </div>
              {!hideCloseButton && (
                <button
                  type="button"
                  className={closeButtonBase}
                  onClick={onClose}
                  aria-label="Close drawer"
                >
                  <IoClose className="h-5 w-5" />
                </button>
              )}
            </div>
          )}

          {/* Body */}
          <div id={descId} className={bodyBase}>
            {children}
          </div>

          {/* Footer */}
          {footer && <div className={footerBase}>{footer}</div>}
        </div>
      </div>
    );

    return createPortal(drawerContent, document.body);
  }
);

Drawer.displayName = "Drawer";

import React, { createContext, useContext, useEffect, useRef, useState } from "react";
import { cn, tw } from "@/lib/utils";

// DropdownMenu Context
interface DropdownMenuContextType {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  triggerRef: React.RefObject<HTMLElement | null>;
}

const DropdownMenuContext = createContext<DropdownMenuContextType | null>(null);

const useDropdownMenu = () => {
  const context = useContext(DropdownMenuContext);
  if (!context) {
    throw new Error("DropdownMenu components must be used within a DropdownMenu");
  }
  return context;
};

// Base styles
const contentBase = tw`z-50 min-w-[8rem] overflow-hidden rounded-md border border-border bg-popover text-popover-foreground p-1 shadow-md`;
const itemBase = tw`relative flex w-full cursor-pointer items-center rounded-sm px-2 py-1.5 text-sm transition-colors outline-none select-none hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground disabled:pointer-events-none disabled:opacity-50`;
const labelBase = tw`px-2 py-1.5 text-sm font-semibold text-foreground`;
const separatorBase = tw`-mx-1 my-1 h-px bg-border`;

// Animation classes
const contentAnimation = tw`animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 duration-150 ease-out`;

export interface DropdownMenuProps {
  /**
   * Dropdown menu content
   */
  children: React.ReactNode;
  /**
   * Whether the dropdown is open (controlled)
   */
  open?: boolean;
  /**
   * Default open state
   */
  defaultOpen?: boolean;
  /**
   * Callback when open state changes
   */
  onOpenChange?: (open: boolean) => void;
}

export interface DropdownMenuTriggerProps {
  /**
   * Trigger element content
   */
  children: React.ReactNode;
  /**
   * Additional props for the trigger element
   */
  asChild?: boolean;
}

export interface DropdownMenuContentProps {
  /**
   * Content alignment relative to trigger
   * @default "bottom-start"
   */
  align?: "bottom-start" | "bottom-end" | "top-start" | "top-end";
  /**
   * Content to display in the dropdown
   */
  children: React.ReactNode;
  /**
   * Custom class name
   */
  className?: string;
}

export interface DropdownMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Whether the item is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Callback when item is selected
   */
  onSelect?: () => void;
}

export interface DropdownMenuLabelProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Label text
   */
  children: React.ReactNode;
}

export interface DropdownMenuSeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Custom class name
   */
  className?: string;
}

export interface DropdownMenuGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Group content
   */
  children: React.ReactNode;
}

// DropdownMenu main component
export const DropdownMenu: React.FC<DropdownMenuProps> = ({
  children,
  open,
  defaultOpen = false,
  onOpenChange,
}) => {
  const [isOpen, setIsOpen] = useState(open ?? defaultOpen);
  const triggerRef = useRef<HTMLElement>(null);

  const handleOpenChange = React.useCallback(
    (newOpen: boolean) => {
      if (open === undefined) {
        setIsOpen(newOpen);
      }
      onOpenChange?.(newOpen);
    },
    [open, onOpenChange]
  );

  // Update controlled state
  useEffect(() => {
    if (open !== undefined) {
      setIsOpen(open);
    }
  }, [open]);

  // Close on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        triggerRef.current &&
        !triggerRef.current.contains(event.target as Node) &&
        !(event.target as Element).closest("[data-dropdown-menu-content]")
      ) {
        handleOpenChange(false);
      }
    };

    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
    }
  }, [isOpen, handleOpenChange]);

  // Close on escape
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handleOpenChange(false);
      }
    };

    if (isOpen) {
      document.addEventListener("keydown", handleKeyDown);
      return () => document.removeEventListener("keydown", handleKeyDown);
    }
  }, [isOpen, handleOpenChange]);

  const contextValue: DropdownMenuContextType = {
    isOpen,
    setIsOpen: handleOpenChange,
    triggerRef,
  };

  return (
    <div className="relative">
      <DropdownMenuContext.Provider value={contextValue}>{children}</DropdownMenuContext.Provider>
    </div>
  );
};

// DropdownMenuTrigger component
export const DropdownMenuTrigger = React.forwardRef<HTMLElement, DropdownMenuTriggerProps>(
  ({ children, asChild = false, ...props }, forwardedRef) => {
    const { isOpen, setIsOpen, triggerRef } = useDropdownMenu();

    // Use the forwarded ref if provided, otherwise use the context ref
    const ref = React.useRef<HTMLElement>(null);
    const actualRef = forwardedRef || triggerRef;

    React.useImperativeHandle(actualRef, () => ref.current as HTMLElement);

    const handleClick = () => {
      setIsOpen(!isOpen);
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        setIsOpen(!isOpen);
      }
    };

    if (asChild && React.isValidElement(children)) {
      return React.cloneElement(children, {
        ref: (node: HTMLElement) => {
          ref.current = node;
          if (typeof actualRef === "function") {
            actualRef(node);
          } else if (actualRef) {
            actualRef.current = node;
          }
        },
        onClick: handleClick,
        onKeyDown: handleKeyDown,
        "aria-expanded": isOpen,
        "aria-haspopup": "menu",
        ...props,
      } as React.HTMLAttributes<HTMLElement>);
    }

    return (
      <button
        ref={node => {
          ref.current = node;
          if (typeof actualRef === "function") {
            actualRef(node);
          } else if (actualRef) {
            actualRef.current = node;
          }
        }}
        type="button"
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        aria-expanded={isOpen}
        aria-haspopup="menu"
        {...props}
      >
        {children}
      </button>
    );
  }
);

DropdownMenuTrigger.displayName = "DropdownMenuTrigger";
export const DropdownMenuContent = React.forwardRef<HTMLDivElement, DropdownMenuContentProps>(
  ({ align = "bottom-start", className, children, ...props }, ref) => {
    const { isOpen, triggerRef } = useDropdownMenu();
    const contentRef = useRef<HTMLDivElement>(null);
    const [actualAlign, setActualAlign] = useState(align);

    useEffect(() => {
      if (isOpen && contentRef.current && triggerRef.current) {
        // Use requestAnimationFrame to ensure content is fully rendered before calculating position
        requestAnimationFrame(() => {
          if (contentRef.current && triggerRef.current) {
            const contentRect = contentRef.current.getBoundingClientRect();
            const triggerRect = triggerRef.current.getBoundingClientRect();
            const viewportWidth = window.innerWidth;
            const viewportHeight = window.innerHeight;

            // Calculate available space for each alignment
            const alignments = [
              {
                align: "bottom-start" as const,
                space: {
                  top: viewportHeight - triggerRect.bottom,
                  left: triggerRect.left,
                  right: viewportWidth - triggerRect.left,
                },
              },
              {
                align: "bottom-end" as const,
                space: {
                  top: viewportHeight - triggerRect.bottom,
                  left: viewportWidth - triggerRect.right,
                  right: triggerRect.right,
                },
              },
              {
                align: "top-start" as const,
                space: {
                  top: triggerRect.top,
                  left: triggerRect.left,
                  right: viewportWidth - triggerRect.left,
                },
              },
              {
                align: "top-end" as const,
                space: {
                  top: triggerRect.top,
                  left: viewportWidth - triggerRect.right,
                  right: triggerRect.right,
                },
              },
            ];

            // Find the best alignment that fits
            let bestAlign = align;
            let maxVisibleArea = 0;

            for (const { align: testAlign, space } of alignments) {
              const requiredWidth = contentRect.width;
              const requiredHeight = contentRect.height;

              const fitsHorizontally = space.left >= requiredWidth || space.right >= requiredWidth;
              const fitsVertically = space.top >= requiredHeight;

              if (fitsHorizontally && fitsVertically) {
                // Calculate visible area for this alignment
                const visibleWidth = Math.min(requiredWidth, space.left + space.right);
                const visibleHeight = Math.min(requiredHeight, space.top);
                const visibleArea = visibleWidth * visibleHeight;

                if (visibleArea > maxVisibleArea) {
                  maxVisibleArea = visibleArea;
                  bestAlign = testAlign;
                }
              }
            }

            setActualAlign(bestAlign);
          }
        });
      }
    }, [isOpen, align, children, triggerRef]);

    const getPositionStyles = () => {
      const offset = 4; // 4px gap from trigger

      switch (actualAlign) {
        case "bottom-start":
          return {
            top: "100%",
            left: 0,
            marginTop: `${offset}px`,
            transform: "translateY(0)",
          };
        case "bottom-end":
          return {
            top: "100%",
            right: 0,
            marginTop: `${offset}px`,
            transform: "translateY(0)",
          };
        case "top-start":
          return {
            bottom: "100%",
            left: 0,
            marginBottom: `${offset}px`,
            transform: "translateY(0)",
          };
        case "top-end":
          return {
            bottom: "100%",
            right: 0,
            marginBottom: `${offset}px`,
            transform: "translateY(0)",
          };
        default:
          return {};
      }
    };

    if (!isOpen) return null;

    return (
      <div
        ref={node => {
          contentRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        className={cn(contentBase, contentAnimation, "absolute", className)}
        data-dropdown-menu-content
        role="menu"
        style={getPositionStyles()}
        {...props}
      >
        {children}
      </div>
    );
  }
);

DropdownMenuContent.displayName = "DropdownMenuContent";

// DropdownMenuItem component
export const DropdownMenuItem = React.forwardRef<HTMLButtonElement, DropdownMenuItemProps>(
  ({ className, disabled = false, onSelect, children, ...props }, ref) => {
    const { setIsOpen } = useDropdownMenu();

    const handleClick = () => {
      if (!disabled) {
        onSelect?.();
        setIsOpen(false);
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        handleClick();
      }
    };

    return (
      <button
        ref={ref}
        type="button"
        className={cn(itemBase, className)}
        disabled={disabled}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        role="menuitem"
        {...props}
      >
        {children}
      </button>
    );
  }
);

DropdownMenuItem.displayName = "DropdownMenuItem";

// DropdownMenuLabel component
export const DropdownMenuLabel: React.FC<DropdownMenuLabelProps> = ({ className, ...props }) => {
  return <div className={cn(labelBase, className)} role="group" {...props} />;
};

// DropdownMenuSeparator component
export const DropdownMenuSeparator: React.FC<DropdownMenuSeparatorProps> = ({
  className,
  ...props
}) => {
  return <div className={cn(separatorBase, className)} role="separator" {...props} />;
};

// DropdownMenuGroup component
export const DropdownMenuGroup: React.FC<DropdownMenuGroupProps> = ({ className, ...props }) => {
  return <div className={cn(className)} role="group" {...props} />;
};

import React from "react";
import { cn, tw } from "@/lib/utils";

export interface EditableProps {
  /**
   * The current value of the editable text
   */
  value?: string;
  /**
   * Default value when component is uncontrolled
   */
  defaultValue?: string;
  /**
   * Placeholder text shown when value is empty
   */
  placeholder?: string;
  /**
   * Callback fired when the value changes
   */
  onChange?: (value: string) => void;
  /**
   * Callback fired when editing starts
   */
  onEditStart?: () => void;
  /**
   * Callback fired when editing ends (save or cancel)
   */
  onEditEnd?: (value: string, saved: boolean) => void;
  /**
   * Callback fired when changes are saved
   */
  onSave?: (value: string) => void;
  /**
   * Callback fired when editing is cancelled
   */
  onCancel?: () => void;
  /**
   * The size of the editable component
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Control the border radius
   * @default "sm"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Make component take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Whether the component is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Whether the component is in read-only mode
   * @default false
   */
  readOnly?: boolean;
  /**
   * Whether to show save/cancel buttons when editing
   * @default false
   */
  showButtons?: boolean;
  /**
   * Custom save button text
   * @default "Save"
   */
  saveText?: string;
  /**
   * Custom cancel button text
   * @default "Cancel"
   */
  cancelText?: string;
  /**
   * Whether to save on Enter key press
   * @default true
   */
  saveOnEnter?: boolean;
  /**
   * Whether to cancel on Escape key press
   * @default true
   */
  cancelOnEscape?: boolean;
  /**
   * Trigger mode for starting edit
   * @default "click"
   */
  trigger?: "click" | "doubleClick";
  /**
   * Maximum length of the text
   */
  maxLength?: number;
  /**
   * Minimum length of the text
   */
  minLength?: number;
  /**
   * Custom CSS class
   */
  className?: string;
  /**
   * Content to display when not editing (can be used for custom rendering)
   */
  children?: React.ReactNode;
}

const sizes = {
  xs: { container: tw`min-h-7 text-xs`, gap: "gap-1" },
  sm: { container: tw`min-h-8 text-xs`, gap: "gap-1.5" },
  md: { container: tw`min-h-9 text-sm`, gap: "gap-2" },
  lg: { container: tw`min-h-10 text-sm`, gap: "gap-2.5" },
  xl: { container: tw`min-h-12 text-base`, gap: "gap-3" },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const buttonBase = tw`inline-flex items-center justify-center rounded px-2 py-1 text-xs font-medium transition-colors duration-150 rui-focus-ring focus:outline-none disabled:pointer-events-none disabled:opacity-50`;

export const Editable = React.forwardRef<HTMLDivElement, EditableProps>(
  (
    {
      value: controlledValue,
      defaultValue = "",
      placeholder = "Click to edit...",
      onChange,
      onEditStart,
      onEditEnd,
      onSave,
      onCancel,
      size = "md",
      rounded = "sm",
      fullWidth = false,
      disabled = false,
      readOnly = false,
      showButtons = false,
      saveText = "Save",
      cancelText = "Cancel",
      saveOnEnter = true,
      cancelOnEscape = true,
      trigger = "click",
      maxLength,
      minLength,
      className = "",
      children,
      ...props
    },
    ref
  ) => {
    const [isEditing, setIsEditing] = React.useState(false);
    const [internalValue, setInternalValue] = React.useState(defaultValue);
    const [editValue, setEditValue] = React.useState("");

    const inputRef = React.useRef<HTMLInputElement>(null);

    // Determine if component is controlled
    const isControlled = controlledValue !== undefined;
    const value = isControlled ? controlledValue : internalValue;
    const isDisabled = disabled || readOnly;

    // Handle starting edit mode
    const handleStartEdit = React.useCallback(() => {
      if (isDisabled) return;
      setIsEditing(true);
      setEditValue(value);
      onEditStart?.();
    }, [isDisabled, value, onEditStart]);

    // Focus and select input text after entering edit mode
    React.useEffect(() => {
      if (isEditing) {
        requestAnimationFrame(() => {
          inputRef.current?.focus();
          inputRef.current?.select();
        });
      }
    }, [isEditing]);

    const handleSave = React.useCallback(() => {
      if (!isEditing) return;
      const newValue = editValue.trim();

      if (minLength !== undefined && newValue.length < minLength) return;
      if (maxLength !== undefined && newValue.length > maxLength) return;

      if (value !== newValue) {
        if (!isControlled) {
          setInternalValue(newValue);
        }
        onChange?.(newValue);
        onSave?.(newValue);
      }

      onEditEnd?.(newValue, true);
      setIsEditing(false);
    }, [
      isEditing,
      editValue,
      value,
      minLength,
      maxLength,
      isControlled,
      onChange,
      onSave,
      onEditEnd,
    ]);

    const handleCancel = React.useCallback(() => {
      setEditValue(value);
      onCancel?.();
      onEditEnd?.(value, false);
      setIsEditing(false);
    }, [value, onCancel, onEditEnd]);

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter" && saveOnEnter) {
        e.preventDefault();
        handleSave();
      } else if (e.key === "Escape" && cancelOnEscape) {
        e.preventDefault();
        handleCancel();
      }
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setEditValue(e.target.value);
    };

    const handleSaveMouseDown = (e: React.MouseEvent) => {
      e.preventDefault(); // Prevent input from blurring before save
      handleSave();
    };

    const handleCancelMouseDown = (e: React.MouseEvent) => {
      e.preventDefault(); // Prevent input from blurring before cancel
      handleCancel();
    };

    const isEmpty = !value;
    const displayValue = value || placeholder;

    return (
      <div
        ref={ref}
        className={cn(
          "font-inherit relative inline-flex items-center align-baseline",
          sizes[size].container,
          roundedOptions[rounded],
          fullWidth && "w-full",
          isDisabled ? "cursor-not-allowed opacity-50" : "cursor-pointer",
          className
        )}
        onClick={!isEditing && trigger === "click" ? handleStartEdit : undefined}
        onDoubleClick={!isEditing && trigger === "doubleClick" ? handleStartEdit : undefined}
        {...props}
      >
        {isEditing ? (
          <div className={cn("flex w-full items-center", sizes[size].gap)}>
            {/* Grid container for input sizer and input field */}
            <div className="relative grid grow items-center">
              {/* Sizer: Renders text invisibly to define width */}
              <span className="invisible col-start-1 row-start-1 p-0 whitespace-pre" aria-hidden>
                {editValue || placeholder || "\u00A0"}
              </span>

              {/* Input: Overlays the sizer */}
              <input
                ref={inputRef}
                type="text"
                value={editValue}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
                onBlur={handleSave}
                maxLength={maxLength}
                minLength={minLength}
                className={cn(
                  "text-foreground col-start-1 row-start-1 w-full border-none bg-transparent p-0 ring-0 outline-none",
                  isEmpty && "text-muted-foreground"
                )}
                disabled={isDisabled}
                aria-label="Edit text"
              />
            </div>
            {showButtons && (
              <div className="flex shrink-0 items-center gap-1">
                <button
                  type="button"
                  onMouseDown={handleSaveMouseDown}
                  className={cn(
                    buttonBase,
                    "bg-success text-success-foreground hover:bg-success/90"
                  )}
                  disabled={isDisabled}
                  aria-label={saveText}
                >
                  {saveText}
                </button>
                <button
                  type="button"
                  onMouseDown={handleCancelMouseDown}
                  className={cn(
                    buttonBase,
                    "bg-secondary text-secondary-foreground hover:bg-secondary/80"
                  )}
                  disabled={isDisabled}
                  aria-label={cancelText}
                >
                  {cancelText}
                </button>
              </div>
            )}
          </div>
        ) : (
          <div
            tabIndex={isDisabled ? -1 : 0}
            onKeyDown={e => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                handleStartEdit();
              }
            }}
            role="button"
            aria-label={`Edit: ${displayValue}`}
            className="truncate"
          >
            {children || (
              <span className={cn("select-none", isEmpty && "text-muted-foreground italic")}>
                {displayValue}
              </span>
            )}
          </div>
        )}
      </div>
    );
  }
);

Editable.displayName = "Editable";

import React from "react";
