  /**
   * Custom class name
   */
  className?: string;
}

const wrapperBase = tw`relative inline-flex w-full flex-col`;
const uploadAreaBase = tw`relative flex flex-col items-center justify-center border-2 border-dashed bg-background text-foreground transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50`;

const variants = {
  primary: tw`border-border hover:border-primary`,
  secondary: tw`border-border bg-muted hover:border-input`,
  dashed: tw`border-input hover:border-primary`,
};

const sizes = {
  sm: {
    container: tw`min-h-[120px] p-4`,
    text: tw`text-sm`,
    button: tw`px-3 py-1.5 text-xs`,
    icon: 30,
  },
  md: {
    container: tw`min-h-[160px] p-6`,
    text: tw`text-base`,
    button: tw`px-4 py-2 text-sm`,
    icon: 40,
  },
  lg: {
    container: tw`min-h-[200px] p-8`,
    text: tw`text-lg`,
    button: tw`px-4 py-2 text-sm`,
    icon: 50,
  },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const buttonBase = tw`inline-flex cursor-pointer items-center justify-center rounded-md border border-border bg-background px-4 py-2 text-sm font-medium text-foreground shadow-sm hover:bg-muted disabled:pointer-events-none disabled:opacity-50`;

// Default file upload icon
const DefaultFileUploadIcon = ({ size = 24 }: { size?: number }) => <FileUploadIcon size={size} />;

export const FileUpload = React.forwardRef<HTMLDivElement, FileUploadProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "md",
      fullWidth = false,
      multiple = false,
      accept,
      maxSize,
      maxFiles,
      disabled = false,
      dragAndDrop = true,
      placeholder = "Click to upload or drag and drop",
      buttonText = "Choose File",
      description,
      showFileList = true,
      icon = <DefaultFileUploadIcon size={sizes[size].icon} />,
      onFilesSelected,
      onFileRemoved,
      onError,
      value = [],
      className = "",
      ...props
    },
    ref
  ) => {
    // Determine if component is controlled
    const isControlled = React.useRef(value !== undefined);
    const prevValueRef = React.useRef<File[]>(isControlled.current ? value || [] : []);

    const [files, setFiles] = React.useState<File[]>(() => {
      // Initialize with value if controlled, empty array if uncontrolled
      return isControlled.current ? value || [] : [];
    });
    const [isDragOver, setIsDragOver] = React.useState(false);
    const [errors, setErrors] = React.useState<string[]>([]);

    const fileInputRef = React.useRef<HTMLInputElement>(null);
    const uploadAreaRef = React.useRef<HTMLDivElement>(null);

    React.useImperativeHandle(ref, () => uploadAreaRef.current as HTMLDivElement);

    // Update internal state when value prop changes (controlled component)
    React.useEffect(() => {
      if (isControlled.current) {
        // Check if the value has actually changed to prevent infinite loops
        const hasChanged =
          !prevValueRef.current ||
          value.length !== prevValueRef.current.length ||
          value.some((file, index) => {
            const prevFile = prevValueRef.current?.[index];
            return (
              !prevFile ||
              file.name !== prevFile.name ||
              file.size !== prevFile.size ||
              file.lastModified !== prevFile.lastModified
            );
          });

        if (hasChanged) {
          setFiles(value);
          prevValueRef.current = [...value];
        }
      }
    }, [value]);

    const validateFile = (file: File): string | null => {
      if (maxSize && file.size > maxSize) {
        return `File "${file.name}" is too large. Maximum size is ${formatFileSize(maxSize)}.`;
      }
      return null;
    };

    const validateFiles = (fileList: File[]): { validFiles: File[]; errors: string[] } => {
      const validFiles: File[] = [];
      const validationErrors: string[] = [];

      for (const file of fileList) {
        const error = validateFile(file);
        if (error) {
          validationErrors.push(error);
        } else {
          validFiles.push(file);
        }
      }

      if (maxFiles && validFiles.length > maxFiles) {
        validationErrors.push(`Maximum ${maxFiles} files allowed.`);
        validFiles.splice(maxFiles);
      }

      return { validFiles, errors: validationErrors };
    };

    const handleFiles = (fileList: FileList | null) => {
      if (!fileList) return;

      const newFiles = Array.from(fileList);
      const { validFiles, errors: validationErrors } = validateFiles(newFiles);

      if (validationErrors.length > 0) {
        setErrors(validationErrors);
        onError?.(validationErrors.join(" "));
        return;
      }

      setErrors([]);

      let updatedFiles: File[];
      if (multiple) {
        updatedFiles = [...files, ...validFiles];
        if (maxFiles && updatedFiles.length > maxFiles) {
          updatedFiles = updatedFiles.slice(0, maxFiles);
        }
      } else {
        updatedFiles = validFiles.slice(0, 1);
      }

      setFiles(updatedFiles);
      onFilesSelected?.(updatedFiles);
    };

    const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      handleFiles(e.target.files);
      // Reset input value to allow selecting the same file again
      e.target.value = "";
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      setIsDragOver(false);
      if (disabled || !dragAndDrop) return;
      handleFiles(e.dataTransfer.files);
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      if (disabled || !dragAndDrop) return;
      setIsDragOver(true);
    };

    const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      if (disabled || !dragAndDrop) return;
      setIsDragOver(false);
    };

    const handleClick = () => {
      if (disabled) return;
      fileInputRef.current?.click();
    };

    const handleRemoveFile = (index: number) => {
      const updatedFiles = files.filter((_, i) => i !== index);
      setFiles(updatedFiles);
      onFileRemoved?.(files[index], index);
      onFilesSelected?.(updatedFiles);
    };

    const formatFileSize = (bytes: number): string => {
      if (bytes === 0) return "0 Bytes";
      const k = 1024;
      const sizes = ["Bytes", "KB", "MB", "GB"];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
    };

    const getFileIcon = (file: File): React.ReactNode => {
      const type = file.type;
      if (type.startsWith("image/")) return <FileImage size={16} />;
      if (type.startsWith("video/")) return <FileVideo size={16} />;
      if (type.startsWith("audio/")) return <FileAudio size={16} />;
      if (type.includes("pdf")) return <FileText size={16} />;
      if (type.includes("zip") || type.includes("rar")) return <FileArchive size={16} />;
      return <File size={16} />;
    };

    return (
      <div className={cn(wrapperBase, fullWidth && "w-full", className)} {...props}>
        <div
          ref={uploadAreaRef}
          className={cn(
            uploadAreaBase,
            variants[variant],
            sizes[size].container,
            roundedOptions[rounded],
            isDragOver && dragAndDrop && "border-primary bg-primary/10",
            disabled && "pointer-events-none",
            fullWidth && "w-full"
          )}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={handleClick}
          role="button"
          tabIndex={disabled ? -1 : 0}
          aria-disabled={disabled}
          aria-label={placeholder}
        >
          <input
            ref={fileInputRef}
            type="file"
            className="sr-only"
            multiple={multiple}
            accept={accept}
            onChange={handleFileInputChange}
            disabled={disabled}
            aria-hidden="true"
          />

          <div className="flex flex-col items-center justify-center text-center">
            <div className="text-muted-foreground mb-4">{icon}</div>
            <p className={cn("text-foreground mb-2 font-medium", sizes[size].text)}>
              {placeholder}
            </p>
            <button
              type="button"
              className={cn(buttonBase, sizes[size].button)}
              onClick={e => {
                e.stopPropagation();
                handleClick();
              }}
              disabled={disabled}
            >
              {buttonText}
            </button>
            {description && <p className="text-muted-foreground mt-2 text-sm">{description}</p>}
            {accept && <p className="text-muted-foreground/70 mt-2 text-xs">Accepted: {accept}</p>}
            {maxSize && (
              <p className="text-muted-foreground/70 mt-1 text-xs">
                Max size: {formatFileSize(maxSize)}
              </p>
            )}
          </div>
        </div>

        {errors.length > 0 && (
          <div className="mt-2">
            {errors.map((error, index) => (
              <p key={index} className="text-destructive text-sm">
                {error}
              </p>
            ))}
          </div>
        )}

        {showFileList && files.length > 0 && (
          <div className="mt-4 space-y-2">
            <h4 className="text-foreground text-sm font-medium">Selected Files ({files.length})</h4>
            <div className="space-y-2">
              {files.map((file, index) => (
                <div
                  key={`${file.name}-${index}`}
                  className="border-border bg-card flex items-center justify-between gap-3 rounded-md border p-3"
                >
                  <div className="flex items-center space-x-3">
                    <span className="text-lg">{getFileIcon(file)}</span>
                    <div>
                      <p className="text-foreground text-sm font-medium">{file.name}</p>
                      <p className="text-muted-foreground text-xs">{formatFileSize(file.size)}</p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => handleRemoveFile(index)}
                    className="border-border text-muted-foreground hover:bg-muted hover:text-foreground aspect-square h-6 w-6 cursor-pointer rounded-full border text-xs transition"
                    aria-label={`Remove ${file.name}`}
                  >
                    ✕
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  }
);

FileUpload.displayName = "FileUpload";

import React from "react";
import { Loader } from "@/components/ui/";
import { cn, tw } from "@/lib/utils";

export interface FloatingActionButtonAction {
  /**
   * Unique identifier for the action
   */
  id: string;
  /**
   * Icon to display for the action
   */
  icon: React.ReactNode;
  /**
   * Tooltip text for the action
   */
  tooltip?: string;
  /**
   * Click handler for the action
   */
  onClick: () => void;
  /**
   * Whether the action is disabled
   */
  disabled?: boolean;
  /**
   * Variant for the action button
   */
  variant?: "primary" | "secondary" | "tertiary" | "destructive";
}

export interface FloatingActionButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "size"> {
  /**
   * The visual style of the floating action button
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "tertiary" | "destructive";
  /**
   * The size of the floating action button
   * @default "md"
   */
  size?: "sm" | "md" | "lg" | "xl";
  /**
   * The position of the floating action button
   * @default "bottom-right"
   */
  position?: "bottom-right" | "bottom-left" | "top-right" | "top-left";
  /**
   * Icon to display in the button - required for FABs
   */
  icon: React.ReactNode;
  /**
   * List of additional actions to display when expanded
   */
  actions?: FloatingActionButtonAction[];
  /**
   * Show a loading spinner and disable the button
   * @default false
   */
  loading?: boolean;
  /**
   * Animation effect on user interaction
   * @default "scale"
   */
  animation?: "none" | "scale" | "glow" | "lift" | "ripple" | "press";
  /**
   * Control the border radius of the button
   * @default "full"
   */
  rounded?: "full" | "xl" | "lg";
  /**
   * Optional tooltip text for accessibility
   */
  tooltip?: string;
  /**
   * Whether to show the tooltip
   * @default false
   */
  showTooltip?: boolean;
  /**
   * Whether the actions are initially expanded
   * @default false
   */
  expanded?: boolean;
  /**
   * Callback when expanded state changes
   */
  onExpandedChange?: (expanded: boolean) => void;
}

const base = tw`fixed z-50 inline-flex transform-gpu cursor-pointer items-center justify-center gap-2 font-medium whitespace-nowrap transition-all duration-200 select-none rui-focus-ring focus:outline-none disabled:pointer-events-none disabled:opacity-50`;

const variants = {
  primary: tw`bg-primary text-primary-foreground shadow-lg hover:bg-primary/90 hover:shadow-xl`,
  secondary: tw`bg-secondary text-secondary-foreground shadow-lg outline outline-border hover:bg-secondary/80 hover:shadow-xl`,
  tertiary: tw`border border-border bg-background text-foreground shadow-lg hover:shadow-xl`,
  destructive: tw`bg-destructive text-destructive-foreground shadow-lg hover:bg-destructive/90 hover:shadow-xl`,
};

const sizes = {
  sm: tw`h-10 w-10 min-w-[2.5rem] gap-1 px-2 py-2 text-sm`,
  md: tw`h-12 w-12 min-w-[3rem] gap-1.5 px-3 py-3 text-base`,
  lg: tw`h-14 w-14 min-w-[3.5rem] gap-2 px-4 py-4 text-lg`,
  xl: tw`h-16 w-16 min-w-[4rem] gap-2.5 px-5 py-5 text-xl`,
};

const positions = {
  "bottom-right": tw`right-6 bottom-6`,
  "bottom-left": tw`bottom-6 left-6`,
  "top-right": tw`top-6 right-6`,
  "top-left": tw`top-6 left-6`,
};

const roundedOptions = {
  full: tw`rounded-full`,
  xl: tw`rounded-xl`,
  lg: tw`rounded-lg`,
};

const animations = {
  none: tw``,
  scale: tw`transition-transform duration-150 ease-out hover:scale-110 active:scale-95`,
  glow: tw`transition-shadow duration-200 ease-out hover:shadow-xl hover:shadow-primary/25`,
  lift: tw`transition-[transform,box-shadow] duration-150 ease-out hover:-translate-y-[2px] hover:shadow-2xl active:-translate-y-[1px]`,
  ripple: tw`overflow-hidden`,
  press: tw`transition-transform duration-75 ease-out active:scale-95`,
};

const tooltipBase = tw`pointer-events-none absolute rounded-md bg-foreground px-2 py-1 text-xs font-medium whitespace-nowrap text-background opacity-0 shadow-lg transition-opacity duration-200 group-hover:opacity-100`;

const actionButtonBase = tw`inline-flex transform-gpu cursor-pointer items-center justify-center gap-2 font-medium whitespace-nowrap transition-all duration-300 select-none rui-focus-ring focus:outline-none disabled:pointer-events-none disabled:opacity-50`;

export const FloatingActionButton = React.forwardRef<HTMLButtonElement, FloatingActionButtonProps>(
  (
    {
      variant = "primary",
      size = "md",
      position = "bottom-right",
      icon,
      actions = [],
      loading = false,
      animation = "scale",
      rounded = "full",
      tooltip,
      showTooltip = false,
      expanded: controlledExpanded,
      onExpandedChange,
      className = "",
      disabled,
      onClick,
      ...props
    },
    ref
  ) => {
    const [internalExpanded, setInternalExpanded] = React.useState(false);
    const isExpanded = controlledExpanded !== undefined ? controlledExpanded : internalExpanded;
    const isDisabled = disabled || loading;
    const hasActions = actions.length > 0;
    const btnRef = React.useRef<HTMLButtonElement | null>(null);
    React.useImperativeHandle(ref, () => btnRef.current as HTMLButtonElement);

    const handleToggle = React.useCallback(
      (e: React.MouseEvent<HTMLButtonElement>) => {
        if (hasActions && !isDisabled) {
          const newExpanded = !isExpanded;
          setInternalExpanded(newExpanded);
          onExpandedChange?.(newExpanded);
        } else {
          onClick?.(e);
        }
      },
      [hasActions, isDisabled, isExpanded, onExpandedChange, onClick]
    );

    type Ripple = { id: number; x: number; y: number; size: number };
    const [ripples, setRipples] = React.useState<Ripple[]>([]);

    const createRipple = React.useCallback(
      (e: { clientX?: number; clientY?: number; type?: string }) => {
        if (animation !== "ripple" || isDisabled) return;
        const el = btnRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height) * 1.8;
        let x = rect.width / 2;
        let y = rect.height / 2;
        if (typeof e.clientX === "number" && typeof e.clientY === "number") {
          x = e.clientX - rect.left;
          y = e.clientY - rect.top;
        }
        const id = Date.now() + Math.random();
        setRipples(prev => [...prev.slice(-3), { id, x, y, size }]);
        window.setTimeout(() => {
          setRipples(prev => prev.filter(r => r.id !== id));
        }, 500);
      },
      [animation, isDisabled]
    );

    const rippleVars = React.useMemo(() => {
      let opacity = 0.3;
      if (variant === "primary" || variant === "destructive") opacity = 0.35;
      else if (variant === "secondary") opacity = 0.25;
      else if (variant === "tertiary") opacity = 0.2;
      return {
        "--rui-ripple-opacity": String(opacity),
      } as React.CSSProperties & {
        "--rui-ripple-opacity": string;
      };
    }, [variant]);

    const { onPointerDown, onKeyDown, style, ...restProps } =
      props as React.ButtonHTMLAttributes<HTMLButtonElement>;
    const handlePointerDown = React.useCallback(
      (e: React.PointerEvent<HTMLButtonElement>) => {
        onPointerDown?.(e);
        createRipple(e);
      },
      [onPointerDown, createRipple]
    );
    const handleKeyDown = React.useCallback(
      (e: React.KeyboardEvent<HTMLButtonElement>) => {
        onKeyDown?.(e);
        if (e.key === "Enter" || e.key === " ") {
          createRipple({});
        }
      },
      [onKeyDown, createRipple]
    );

    const getActionStyles = React.useCallback(
      (index: number): React.CSSProperties => {
        const mainButtonSize = size === "sm" ? 40 : size === "md" ? 48 : size === "lg" ? 56 : 64;
        const spacing = 16;
        const edgeMargin = 24;

        const offset = edgeMargin + mainButtonSize + spacing + index * (mainButtonSize + spacing);

        const styles: React.CSSProperties = {};
        if (position.includes("bottom")) {
          styles.bottom = `${offset}px`;
        } else {
          styles.top = `${offset}px`;
        }
        if (position.includes("right")) {
          styles.right = `${edgeMargin}px`;
        } else {
          styles.left = `${edgeMargin}px`;
        }
        return styles;
      },
      [size, position]
    );

    const tooltipClasses = React.useMemo(() => {
      const verticalAlign = tw`top-1/2 -translate-y-1/2`;
      if (position.includes("right")) {
        return cn(verticalAlign, tw`right-full mr-4`);
      }
      return cn(verticalAlign, tw`left-full ml-4`);
    }, [position]);

    return (
      <>
        {/* Action Buttons */}
        {hasActions &&
          actions.map((action, index) => (
            <button
              key={action.id}
              className={cn(
                "group fixed z-40", // Position the button directly
                actionButtonBase,
                variants[action.variant || "secondary"],
                sizes[size],
                roundedOptions[rounded],
                animations[animation],
                isExpanded ? "scale-100 opacity-100" : "pointer-events-none scale-75 opacity-0",
                "transition-all duration-300"
              )}
              style={getActionStyles(index)}
              disabled={action.disabled}
              aria-label={action.tooltip || `Action ${index + 1}`}
              onClick={action.onClick}
            >
              <span className="flex shrink-0 items-center">{action.icon}</span>
              {showTooltip && action.tooltip && (
                <div className={cn(tooltipBase, tooltipClasses)} role="tooltip">
                  {action.tooltip}
                </div>
              )}
            </button>
          ))}

        {/* Main FAB */}
        <button
          ref={btnRef}
          className={cn(
            "group", // Add group here for the tooltip
            base,
            variants[variant],
            sizes[size],
            positions[position],
            roundedOptions[rounded],
            animations[animation],
            className
          )}
          disabled={isDisabled}
          aria-disabled={isDisabled}
          aria-busy={loading}
          aria-label={tooltip || (hasActions ? "Toggle actions" : "Floating action button")}
          aria-expanded={hasActions ? isExpanded : undefined}
          onClick={handleToggle}
          onPointerDown={handlePointerDown}
          onKeyDown={handleKeyDown}
          style={{ ...style, ...rippleVars }}
          {...restProps}
        >
          {animation === "ripple" && !loading && ripples.length > 0 && (
            <span aria-hidden className="pointer-events-none absolute inset-0">
              {ripples.map(r => (
                <span
                  key={r.id}
                  className="rui-ripple"
                  style={{
                    left: r.x,
                    top: r.y,
                    width: r.size,
                    height: r.size,
                  }}
                />
              ))}
            </span>
          )}
          {loading && (
            <Loader
              type="spinner"
              variant="primary"
              color="currentColor"
              size={size === "sm" ? "xs" : size === "md" ? "sm" : size === "lg" ? "md" : "md"}
              speed="normal"
              strokeWidth="thick"
            />
          )}
          {!loading && (
            <span
              className={cn(
                "flex shrink-0 items-center transition-transform duration-300",
                hasActions && isExpanded && "rotate-45"
              )}
            >
              {icon}
            </span>
          )}
          {showTooltip && tooltip && (
            <div className={cn(tooltipBase, tooltipClasses)} role="tooltip">
              {tooltip}
            </div>
          )}
        </button>
      </>
    );
  }
);
FloatingActionButton.displayName = "FloatingActionButton";

