export interface FormProps extends Omit<React.FormHTMLAttributes<HTMLFormElement>, "onError"> {
  /**
   * The visual style of the form
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the form elements
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Layout direction for form fields
   * @default "vertical"
   */
  direction?: "vertical" | "horizontal";
  /**
   * Spacing between form fields
   * @default "md"
   */
  spacing?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Make form take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Show form in a card-like container
   * @default false
   */
  card?: boolean;
  /**
   * Optional title for the form
   */
  title?: string;
  /**
   * Optional description for the form
   */
  description?: string;
  /**
   * Show error state for the entire form
   * @default false
   */
  error?: boolean;
  /**
   * Error message for the entire form
   */
  errorMessage?: string;
  /**
   * Show loading state for the form
   * @default false
   */
  loading?: boolean;
  /**
   * Loading message
   * @default "Submitting..."
   */
  loadingMessage?: string;
  /**
   * Disable all form elements
   * @default false
   */
  disabled?: boolean;
  /**
   * Callback fired when form is submitted
   */
  onSubmit?: (event: React.FormEvent<HTMLFormElement>) => void;
  /**
   * Callback fired when form validation fails
   */
  onError?: (errors: Record<string, string>) => void;
}

const formBase = tw`relative flex transition-all duration-200`;

const formVariants = {
  primary: tw`text-foreground`,
  secondary: tw`text-foreground/80`,
};

const formSpacings = {
  xs: tw`gap-2`,
  sm: tw`gap-3`,
  md: tw`gap-4`,
  lg: tw`gap-6`,
  xl: tw`gap-8`,
};

const formDirections = {
  vertical: tw`flex-col`,
  horizontal: tw`flex-row flex-wrap`,
};

const cardStyles = tw`rounded-lg border border-border bg-card p-6 shadow-sm`;

export const Form = React.forwardRef<HTMLFormElement, FormProps>(
  (
    {
      variant = "primary",
      size = "md",
      direction = "vertical",
      spacing = "md",
      fullWidth = false,
      card = false,
      title,
      description,
      error = false,
      errorMessage,
      loading = false,
      loadingMessage = "Submitting...",
      disabled = false,
      className = "",
      children,
      onSubmit,
      onError,
      ...props
    },
    ref
  ) => {
    const formRef = React.useRef<HTMLFormElement | null>(null);
    React.useImperativeHandle(ref, () => formRef.current as HTMLFormElement);

    const handleSubmit = React.useCallback(
      (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();

        if (loading || disabled) return;

        // Basic form validation
        const errors: Record<string, string> = {};

        // Check for required fields
        const requiredFields = event.currentTarget.querySelectorAll("[required]");
        requiredFields.forEach(field => {
          const input = field as HTMLInputElement;
          if (!input.value.trim()) {
            const fieldName = input.name || input.id || "Field";
            errors[input.name || input.id || "field"] = `${fieldName} is required`;
          }
        });

        if (Object.keys(errors).length > 0) {
          onError?.(errors);
          return;
        }

        onSubmit?.(event);
      },
      [loading, disabled, onSubmit, onError]
    );

    const formContent = (
      <>
        {(title || description) && (
          <div className="mb-6">
            {title && (
              <h2
                className={cn(
                  "text-foreground mb-2 font-semibold",
                  size === "xs" && "text-lg",
                  size === "sm" && "text-xl",
                  size === "md" && "text-2xl",
                  size === "lg" && "text-3xl",
                  size === "xl" && "text-4xl"
                )}
              >
                {title}
              </h2>
            )}
            {description && (
              <p
                className={cn(
                  "text-muted-foreground",
                  size === "xs" && "text-sm",
                  size === "sm" && "text-sm",
                  size === "md" && "text-base",
                  size === "lg" && "text-lg",
                  size === "xl" && "text-xl"
                )}
              >
                {description}
              </p>
            )}
          </div>
        )}

        <div
          className={cn(
            formBase,
            formVariants[variant],
            formDirections[direction],
            formSpacings[spacing],
            fullWidth && "w-full",
            disabled && "pointer-events-none opacity-50"
          )}
        >
          {children}
        </div>

        {error && errorMessage && (
          <div className="border-destructive/30 bg-destructive/10 mt-4 rounded-md border p-3">
            <p className="text-destructive text-sm">{errorMessage}</p>
          </div>
        )}

        {loading && (
          <div className="border-info/30 bg-info/10 mt-4 rounded-md border p-3">
            <p className="text-info text-sm">{loadingMessage}</p>
          </div>
        )}
      </>
    );

    return (
      <form
        ref={formRef}
        className={cn(card ? cardStyles : "", fullWidth && "w-full", className)}
        onSubmit={handleSubmit}
        noValidate
        {...props}
      >
        {formContent}
      </form>
    );
  }
);

Form.displayName = "Form";

import React from "react";
import { Skeleton } from "@/components/ui/";
import { cn, tw } from "@/lib/utils";

export interface ImageProps
  extends Omit<React.ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "width" | "height"> {
  /**
   * The source URL of the image
   */
  src: string;
  /**
   * Alternative text for the image (required for accessibility)
   */
  alt: string;
  /**
   * The width of the image
   */
  width?: number | string;
  /**
   * The height of the image
   */
  height?: number | string;
  /**
   * How the image should be resized to fit its container
   * @default "cover"
   */
  fit?: "contain" | "cover" | "fill" | "none" | "scale-down";
  /**
   * Aspect ratio preset or custom ratio (width/height)
   * @default "auto"
   */
  aspectRatio?: "square" | "video" | "wide" | "portrait" | number | "auto";
  /**
   * Control the border radius of the image
   * @default "none"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Additional CSS classes
   */
  className?: string;
  /**
   * Show skeleton loader while image is loading
   * @default false
   */
  showSkeleton?: boolean;
  /**
   * Fallback content to show when image fails to load
   */
  fallback?: React.ReactNode;
  /**
   * Skeleton animation type
   * @default "shimmer"
   */
  skeletonAnimation?: "shimmer" | "wave" | "fade" | "pulse" | "none";
  /**
   * Skeleton variant
   * @default "rectangle"
   */
  skeletonVariant?: "rectangle" | "circle";
  /**
   * Whether the image should fill its container
   * @default false
   */
  fill?: boolean;
}

const base = tw`relative inline-block overflow-hidden`;

const fitOptions = {
  contain: tw`object-contain`,
  cover: tw`object-cover`,
  fill: tw`object-fill`,
  none: tw`object-none`,
  "scale-down": tw`object-scale-down`,
};

const aspectRatioOptions = {
  square: tw`aspect-square`,
  video: tw`aspect-video`,
  wide: tw`aspect-[16/9]`,
  portrait: tw`aspect-[3/4]`,
  auto: tw``,
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

export const Image = React.forwardRef<HTMLImageElement, ImageProps>(
  (
    {
      src,
      alt,
      width,
      height,
      fit = "cover",
      aspectRatio = "auto",
      rounded = "none",
      className = "",
      style,
      fill = false,
      showSkeleton = false,
      fallback,
      skeletonAnimation = "shimmer",
      skeletonVariant = "rectangle",
      onLoad,
      onError,
      ...props
    },
    ref
  ) => {
    const aspectClass = fill
      ? tw`` // Don't apply aspect ratio when using fill
      : typeof aspectRatio === "number"
        ? `aspect-[${aspectRatio}]`
        : aspectRatioOptions[aspectRatio] || tw``;

    const [hasError, setHasError] = React.useState(false);
    const [isLoaded, setIsLoaded] = React.useState(fill); // Start loaded for fill mode

    const handleLoad = React.useCallback(
      (e: React.SyntheticEvent<HTMLImageElement>) => {
        setIsLoaded(true);
        onLoad?.(e);
      },
      [onLoad]
    );

    const handleError = React.useCallback(
      (e: React.SyntheticEvent<HTMLImageElement>) => {
        setHasError(true);
        onError?.(e);
      },
      [onError]
    );

    // Show fallback if image failed to load
    if (hasError && fallback) {
      return (
        <div className={cn(base, aspectClass, roundedOptions[rounded], className)} style={style}>
          {fallback}
        </div>
      );
    }

    return (
      <div
        className={cn(
          base,
          fill ? "h-full w-full" : "",
          aspectClass,
          roundedOptions[rounded],
          className
        )}
        style={style}
      >
        {/* Always render the image to trigger loading events */}
        <img
          ref={ref}
          src={src}
          alt={alt}
          width={width}
          height={height}
          className={cn(
            fitOptions[fit],
            fill ? "h-full w-full" : "",
            isLoaded ? "opacity-100" : "opacity-0",
            "transition-opacity duration-300 ease-in-out"
          )}
          onLoad={handleLoad}
          onError={handleError}
          {...props}
        />

        {/* Show skeleton overlay while loading */}
        {showSkeleton && !isLoaded && (
          <Skeleton
            variant={skeletonVariant}
            size="xs" // Use smallest size to minimize default styling
            width={fill ? "100%" : typeof width === "number" ? width : 300}
            height={fill ? "100%" : typeof height === "number" ? height : 200}
            animation={skeletonAnimation}
            className={cn(
              roundedOptions[rounded],
              "absolute inset-0 z-10 flex items-center justify-center",
              fill ? "h-full w-full" : ""
            )}
            style={
              fill
                ? {}
                : {
                    width: typeof width === "number" ? width : 300,
                    height: typeof height === "number" ? height : 200,
                  }
            }
          />
        )}
      </div>
    );
  }
);
Image.displayName = "Image";

import React, { useCallback, useEffect, useRef, useState } from "react";
