  /**
   * Number of OTP digits/characters
   * @default 6
   */
  length?: number;
  /**
   * The current value of the OTP input
   */
  value?: string;
  /**
   * Default value (uncontrolled)
   */
  defaultValue?: string;
  /**
   * Callback when OTP value changes
   */
