}

// Design primitives matching TextInput component
const wrapperBase = tw`relative inline-flex w-full flex-col`;
const containerBase = tw`inline-flex items-center justify-center`;
const slotBase = tw`relative inline-flex items-center justify-center border bg-background text-foreground text-center font-mono transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50`;

const variants = {
  primary: tw`border-input bg-background focus-within:border-primary`,
  secondary: tw`border-input bg-muted focus-within:border-primary`,
};

const sizes = {
  xs: {
    slot: tw`h-7 w-7 text-xs`,
    input: tw`text-xs`,
    gap: "gap-1",
  },
  sm: {
    slot: tw`h-8 w-8 text-xs`,
    input: tw`text-xs`,
    gap: "gap-1.5",
  },
  md: {
    slot: tw`h-9 w-9 text-sm`,
    input: tw`text-sm`,
    gap: "gap-2",
  },
  lg: {
    slot: tw`h-10 w-10 text-sm`,
    input: tw`text-sm`,
    gap: "gap-2.5",
  },
  xl: {
    slot: tw`h-12 w-12 text-base`,
    input: tw`text-base`,
    gap: "gap-3",
  },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const gapOptions = {
  xs: tw`gap-1`,
  sm: tw`gap-2`,
  md: tw`gap-3`,
  lg: tw`gap-4`,
  xl: tw`gap-5`,
};

const labelSizes = {
  xs: tw`text-xs`,
  sm: tw`text-sm`,
  md: tw`text-sm`,
  lg: tw`text-base`,
  xl: tw`text-base`,
};

export const InputOTP = React.forwardRef<HTMLDivElement, InputOTPProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "sm",
      length = 6,
      value,
      defaultValue,
      onChange,
      onComplete,
      disabled = false,
      error = false,
      errorMessage,
      label,
      description,
      type = "number",
      mask = false,
      autoFocus = false,
      placeholder = "",
      gap = "sm",
      allowPaste = true,
      fullWidth = false,
      className = "",
      id,
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = useState(defaultValue || "");
    const [activeIndex, setActiveIndex] = useState(0);
    const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
    const containerRef = useRef<HTMLDivElement | null>(null);

    React.useImperativeHandle(ref, () => containerRef.current as HTMLDivElement);

    const autoId = React.useId();
    const inputId = id ?? autoId;

    const currentValue = value !== undefined ? value : internalValue;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${inputId}-desc`;

    // Initialize input refs array
    useEffect(() => {
      inputRefs.current = Array(length).fill(null);
    }, [length]);

    // Auto focus first input
    useEffect(() => {
      if (autoFocus && inputRefs.current[0] && !disabled) {
        inputRefs.current[0]?.focus();
      }
    }, [autoFocus, disabled]);

    // Update internal value when controlled value changes
    useEffect(() => {
      if (value !== undefined) {
        setInternalValue(value);
      }
    }, [value]);

    const updateValue = useCallback(
      (newValue: string) => {
        const sanitizedValue =
          type === "number"
            ? newValue.replace(/[^0-9]/g, "")
            : newValue.replace(/[^a-zA-Z0-9]/g, "");

        const truncatedValue = sanitizedValue.slice(0, length);

        if (value === undefined) {
          setInternalValue(truncatedValue);
        }

        onChange?.(truncatedValue);

        if (truncatedValue.length === length) {
          onComplete?.(truncatedValue);
        }
      },
      [value, onChange, onComplete, length, type]
    );

    const focusSlot = useCallback(
      (index: number) => {
        const targetIndex = Math.max(0, Math.min(index, length - 1));
        setActiveIndex(targetIndex);
        inputRefs.current[targetIndex]?.focus();
      },
      [length]
    );

    const handleInputChange = useCallback(
      (index: number, inputValue: string) => {
        const newValue = currentValue.split("");

        if (inputValue === "") {
          // Handle backspace/delete
          newValue[index] = "";
        } else {
          // Handle new character input
          const char =
            type === "number"
              ? inputValue.replace(/[^0-9]/g, "").slice(-1)
              : inputValue.replace(/[^a-zA-Z0-9]/g, "").slice(-1);

          if (char) {
            newValue[index] = char;
            // Move to next slot if character was entered and not at the end
            if (index < length - 1) {
              setTimeout(() => focusSlot(index + 1), 0);
            }
          }
        }

        // Fill empty slots between start and current position
        for (let i = 0; i < newValue.length; i++) {
          if (newValue[i] === undefined) {
            newValue[i] = "";
          }
        }

        updateValue(newValue.join(""));
      },
      [currentValue, focusSlot, length, type, updateValue]
    );

    const handleKeyDown = useCallback(
      (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
        if (disabled) return;

        switch (e.key) {
          case "Backspace":
            e.preventDefault();
            if (currentValue[index]) {
              // Clear current slot
              handleInputChange(index, "");
            } else if (index > 0) {
              // Move to previous slot and clear it
              focusSlot(index - 1);
              setTimeout(() => handleInputChange(index - 1, ""), 0);
            }
            break;

          case "Delete":
            e.preventDefault();
            handleInputChange(index, "");
            break;

          case "ArrowLeft":
            e.preventDefault();
            focusSlot(index - 1);
            break;

          case "ArrowRight":
            e.preventDefault();
            focusSlot(index + 1);
            break;

          case "Home":
            e.preventDefault();
            focusSlot(0);
            break;

          case "End":
            e.preventDefault();
            focusSlot(length - 1);
            break;

          default:
            // Allow only valid characters based on type
            if (type === "number" && !/[0-9]/.test(e.key)) {
              e.preventDefault();
            } else if (type === "text" && !/[a-zA-Z0-9]/.test(e.key)) {
              e.preventDefault();
            }
            break;
        }
      },
      [currentValue, disabled, focusSlot, handleInputChange, length, type]
    );

    const handlePaste = useCallback(
      (e: React.ClipboardEvent) => {
        if (!allowPaste || disabled) {
          e.preventDefault();
          return;
        }

        e.preventDefault();
        const pasteData = e.clipboardData.getData("text");
        const sanitizedData =
          type === "number"
            ? pasteData.replace(/[^0-9]/g, "")
            : pasteData.replace(/[^a-zA-Z0-9]/g, "");

        updateValue(sanitizedData);

        // Focus the appropriate slot after paste
        const nextIndex = Math.min(sanitizedData.length, length - 1);
        setTimeout(() => focusSlot(nextIndex), 0);
      },
      [allowPaste, disabled, focusSlot, length, type, updateValue]
    );

    const handleFocus = useCallback((index: number) => {
      setActiveIndex(index);
    }, []);

    const handleClick = useCallback(
      (index: number) => {
        focusSlot(index);
      },
      [focusSlot]
    );

    return (
      <div ref={containerRef} className={cn(wrapperBase, fullWidth && "w-full")} {...props}>
        {label && (
          <label
            htmlFor={`${inputId}-0`}
            className={cn(
              "text-foreground mb-1 font-medium",
              labelSizes[size],
              error && "text-destructive"
            )}
          >
            {label}
          </label>
        )}

        <div
          className={cn(
            containerBase,
            gapOptions[gap],
            fullWidth && "w-full justify-between",
            className
          )}
          role="group"
          aria-label={label || "OTP input"}
          aria-describedby={hasAssistive ? assistiveId : undefined}
        >
          {Array.from({ length }, (_, index) => {
            const isActive = activeIndex === index;
            const hasValue = Boolean(currentValue[index]);
            const displayValue = mask && hasValue ? "•" : currentValue[index] || "";

            return (
              <div
                key={index}
                className={cn(
                  slotBase,
                  variants[variant],
                  sizes[size].slot,
                  roundedOptions[rounded],
                  error && "border-destructive focus-within:border-destructive",
                  isActive && !disabled && !error && "border-primary ring-primary/40 ring-1",
                  fullWidth && "flex-1"
                )}
                onClick={() => handleClick(index)}
              >
                <input
                  ref={el => {
                    inputRefs.current[index] = el;
                  }}
                  id={`${inputId}-${index}`}
                  type={mask ? "password" : "text"}
                  inputMode={type === "number" ? "numeric" : "text"}
                  pattern={type === "number" ? "[0-9]*" : "[a-zA-Z0-9]*"}
                  maxLength={1}
                  value={displayValue}
                  placeholder={placeholder}
                  disabled={disabled}
                  aria-label={`Digit ${index + 1} of ${length}`}
                  aria-invalid={error || undefined}
                  className={cn(
                    "placeholder:text-muted-foreground h-full w-full bg-transparent text-center outline-none",
                    sizes[size].input,
                    disabled && "cursor-not-allowed"
                  )}
                  onChange={e => handleInputChange(index, e.target.value)}
                  onKeyDown={e => handleKeyDown(index, e)}
                  onFocus={() => handleFocus(index)}
                  onPaste={index === 0 ? handlePaste : undefined}
                />
              </div>
            );
          })}
        </div>

        {hasAssistive && (
          <div id={assistiveId} className="mt-1 min-h-[1rem]">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

InputOTP.displayName = "InputOTP";

import React from "react";
import { cn, tw } from "@/lib/utils";

export interface KeyboardKeyProps extends React.HTMLAttributes<HTMLElement> {
  /**
   * The visual style of the keyboard key
   * @default "default"
   */
  variant?: "default" | "flat" | "outlined" | "minimal";
  /**
   * The size of the keyboard key
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * The key being displayed
   */
  children: React.ReactNode;
  /**
   * Additional styling to make the key appear pressed/active
   * @default false
   */
  pressed?: boolean;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * Whether the key is disabled/inactive
   * @default false
   */
  disabled?: boolean;
  /**
   * Make the key render as a clickable element
   * @default false
   */
  clickable?: boolean;
  /**
   * Click handler for clickable keys
   */
  onClick?: () => void;
  /**
   * The HTML element to render as
   * @default "kbd"
   */
  as?: "kbd" | "span" | "button" | "div";
}

// Base styles for all keyboard keys
const keyBase = tw`inline-flex items-center justify-center font-mono font-medium whitespace-nowrap transition-all duration-150 select-none`;

// Variant styles
const variantStyles = {
  default: tw`border border-border bg-muted text-foreground shadow-sm hover:bg-accent`,
  flat: tw`border border-border bg-background text-foreground/80`,
  outlined: tw`border-2 border-border bg-background text-foreground hover:border-input`,
  minimal: tw`border border-border/60 bg-muted/50 text-muted-foreground`,
};

const activeStyles = {
  default: tw`translate-y-[1px] transform border-input bg-muted shadow-inner`,
  flat: tw`border-border bg-muted shadow-inner`,
  outlined: tw`translate-y-[1px] transform border-input bg-muted shadow-inner`,
  minimal: tw`border-border/80 bg-muted shadow-inner`,
};

const disabledStyles = {
  default: tw`cursor-not-allowed border-border/50 bg-muted/50 text-muted-foreground/50`,
  flat: tw`cursor-not-allowed border-border/30 bg-background text-muted-foreground/40`,
  outlined: tw`cursor-not-allowed border-border/40 bg-background text-muted-foreground/40`,
  minimal: tw`cursor-not-allowed border-border/30 bg-background text-muted-foreground/30`,
};

// Size configurations
const sizes = {
  xs: tw`h-5 min-w-[1.25rem] rounded px-1 text-xs`,
  sm: tw`h-6 min-w-[1.5rem] rounded-sm px-1.5 text-xs`,
  md: tw`h-7 min-w-[1.75rem] rounded-md px-2 text-sm`,
  lg: tw`h-8 min-w-[2rem] rounded-md px-2.5 text-base`,
  xl: tw`h-10 min-w-[2.5rem] rounded-lg px-3 text-lg`,
};

// Clickable styles
const clickableStyles = tw`cursor-pointer rui-focus-ring focus:outline-none`;

export const KeyboardKey = React.forwardRef<HTMLElement, KeyboardKeyProps>(
  (
    {
      variant = "default",
      size = "md",
      children,
      pressed = false,
      className = "",
      disabled = false,
      clickable = false,
      onClick,
      as = "kbd",
      ...props
    },
    ref
  ) => {
    const handleClick = React.useCallback(() => {
      if (clickable && !disabled && onClick) {
        onClick();
      }
    }, [clickable, disabled, onClick]);

    const handleKeyDown = React.useCallback(
      (event: React.KeyboardEvent) => {
        if (clickable && !disabled && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
          onClick?.();
        }
      },
      [clickable, disabled, onClick]
    );

    // Determine the component to render
    let Component = as;
    if (clickable && as === "kbd") {
      Component = "button";
    }

    // Build class names
    const keyClasses = cn(
      keyBase,
      sizes[size],
      disabled ? disabledStyles[variant] : pressed ? activeStyles[variant] : variantStyles[variant],
      clickable && !disabled && clickableStyles,
      className
    );

    const elementProps = {
      ref,
      className: keyClasses,
      ...(clickable && {
        onClick: handleClick,
        onKeyDown: handleKeyDown,
        tabIndex: disabled ? -1 : 0,
        "aria-disabled": disabled,
        ...(Component === "button" && { type: "button" as const }),
      }),
      ...props,
    };

    return React.createElement(Component, elementProps, children);
  }
);

KeyboardKey.displayName = "KeyboardKey";

import { cn, tw } from "@/lib/utils";
import React from "react";

export interface LinkProps extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "href"> {
  /**
   * The visual style of the link
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "tertiary" | "destructive" | "none";
  /**
   * The size of the link
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * URL to navigate to
   */
  href: string;
  /**
   * Optional start icon - accepts any React element
   */
  startIcon?: React.ReactNode;
  /**
   * Optional end icon - accepts any React element
   */
  endIcon?: React.ReactNode;
  /**
   * Control the text decoration
   * @default "default"
   */
  underline?: "none" | "hover" | "always" | "default";
  /**
   * Control the border radius
   * @default "md"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Animation effect on user interaction
   * @default "none"
   */
  animation?: "none" | "scale" | "glow" | "lift" | "press";
  /**
   * Link content (text, elements, etc.)
   */
  children: React.ReactNode;
  /**
   * Whether the link opens in a new tab
   * @default false
   */
  external?: boolean;
  /**
   * Control focus ring visibility
   * @default true
   */
  focusRing?: boolean;
}

const base = tw`inline-flex items-center gap-2 font-medium transition-all duration-200 select-none disabled:pointer-events-none disabled:opacity-50`;

const variants = {
  primary: tw`text-primary hover:text-primary/80 active:text-primary/60`,
  secondary: tw`text-muted-foreground hover:text-foreground active:text-foreground/80`,
  tertiary: tw`text-muted-foreground/70 hover:text-muted-foreground active:text-foreground/70`,
  destructive: tw`text-destructive hover:text-destructive/80 active:text-destructive/60`,
  none: tw``,
};

const sizes = {
  xs: tw`gap-1 text-xs`,
  sm: tw`gap-1.5 text-sm`,
  md: tw`gap-2 text-base`,
  lg: tw`gap-2.5 text-lg`,
  xl: tw`gap-3 text-xl`,
};

const underlineOptions = {
  none: tw`no-underline`,
  hover: tw`no-underline hover:underline`,
  always: tw`underline`,
  default: tw``, // Uses browser default
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const animations = {
  none: tw``,
  scale: tw`transition-transform duration-150 ease-out hover:scale-105 active:scale-95`,
  glow: tw`transition-shadow duration-200 ease-out hover:shadow-lg hover:shadow-current/25`,
  lift: tw`transition-[transform,box-shadow] duration-150 ease-out hover:-translate-y-[1px] hover:shadow-md active:-translate-y-[0.5px]`,
  press: tw`transition-transform duration-75 ease-out active:scale-95`,
};

const focusRingStyles = tw`rui-focus-ring focus:outline-none`;

export const Link = React.forwardRef<HTMLAnchorElement, LinkProps>(
  (
    {
      variant = "primary",
      size = "md",
      href,
      startIcon,
      endIcon,
      underline = "default",
      rounded = "md",
      animation = "none",
      children,
      external = false,
      focusRing = true,
      className = "",
      target,
      rel,
      ...props
    },
    ref
  ) => {
    // Determine if link is external based on href or explicit external prop
    const isExternal =
      external || href.startsWith("http") || href.startsWith("mailto:") || href.startsWith("tel:");

    // Auto-set target and rel for external links
    const linkTarget = target || (isExternal ? "_blank" : undefined);
    const linkRel =
      rel || (isExternal && linkTarget === "_blank" ? "noopener noreferrer" : undefined);

    const linkClasses = cn(
      base,
      variants[variant],
      sizes[size],
      underlineOptions[underline],
      roundedOptions[rounded],
      animations[animation],
      focusRing && focusRingStyles,
      className
    );

    const linkContent = (
      <>
        {startIcon && <span className="flex shrink-0 items-center">{startIcon}</span>}
        <span className="truncate">{children}</span>
        {endIcon && <span className="flex shrink-0 items-center">{endIcon}</span>}
      </>
    );

    return (
      <a href={href} ref={ref} className={linkClasses} target={linkTarget} rel={linkRel} {...props}>
        {linkContent}
      </a>
    );
  }
);

Link.displayName = "Link";

import { cn, tw } from "@/lib/utils";
import React from "react";

export interface LoaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The visual style of the loader
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * Custom color for the loader (overrides variant)
   */
  color?: string;
  /**
   * The size of the loader
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * The type of loader animation
   * @default "spinner"
   */
  type?: "spinner" | "dots" | "pulse" | "wave" | "bars" | "ring";
  /**
   * Optional text label displayed below the loader
   */
  label?: string;
  /**
   * Make loader take full width and height of its container
   * @default false
   */
  fullSize?: boolean;
  /**
   * Animation speed of the loader
   * @default "normal"
   */
  speed?: "slow" | "normal" | "fast";
  /**
   * Controls the stroke width for spinner and ring loaders
   * @default "normal"
   */
  strokeWidth?: "thin" | "normal" | "thick";
}

const base = tw`inline-flex items-center justify-center`;

const variants = {
  primary: tw`text-primary`,
  secondary: tw`text-muted-foreground`,
};

const sizes = {
  xs: tw`h-4 w-4`,
  sm: tw`h-6 w-6`,
  md: tw`h-8 w-8`,
  lg: tw`h-12 w-12`,
  xl: tw`h-16 w-16`,
};

const speeds = {
  slow: tw`animate-[spin_2s_linear_infinite]`,
  normal: tw`animate-spin`,
  fast: tw`animate-[spin_0.5s_linear_infinite]`,
};

const spinnerSizes = {
  xs: { size: 16 },
  sm: { size: 24 },
  md: { size: 32 },
  lg: { size: 48 },
  xl: { size: 64 },
};

const strokeWidths = {
  thin: {
    xs: 1.5,
    sm: 1.5,
    md: 2,
    lg: 2.5,
    xl: 3,
  },
  normal: {
    xs: 2,
    sm: 2,
    md: 2.5,
    lg: 3,
    xl: 3.5,
  },
  thick: {
    xs: 2.5,
    sm: 3,
    md: 3.5,
    lg: 4,
    xl: 5,
  },
};

const renderSpinner = (
  size: keyof typeof sizes,
  variant: keyof typeof variants,
  speed: keyof typeof speeds,
  strokeWidth: keyof typeof strokeWidths
) => {
  const { size: svgSize } = spinnerSizes[size];
  const strokeWidthValue = strokeWidths[strokeWidth][size];
  const radius = svgSize / 2 - strokeWidthValue;
  const center = svgSize / 2;

  return (
    <svg
      className={cn(sizes[size], speeds[speed])}
      viewBox={`0 0 ${svgSize} ${svgSize}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <circle
        cx={center}
        cy={center}
        r={radius}
        stroke="currentColor"
        strokeWidth={strokeWidthValue}
        opacity="0.25"
      />
      <path
        d={`M ${center} ${strokeWidthValue} A ${radius} ${radius} 0 0 1 ${
          center + radius
        } ${center}`}
        stroke="currentColor"
        strokeWidth={strokeWidthValue}
        strokeLinecap="round"
      />
    </svg>
  );
};

const renderDots = (
  size: keyof typeof sizes,
  variant: keyof typeof variants,
  speed: keyof typeof speeds
) => {
  const dotSize = {
    xs: "w-1 h-1",
    sm: "w-1.5 h-1.5",
    md: "w-2 h-2",
    lg: "w-3 h-3",
    xl: "w-4 h-4",
  };

  const dotSpacing = {
    xs: "space-x-1",
    sm: "space-x-1",
    md: "space-x-1",
    lg: "space-x-1.5",
    xl: "space-x-2",
  };

  return (
    <div className={cn("flex", dotSpacing[size])}>
      {[0, 1, 2].map(i => (
        <div
          key={i}
          className={cn(
            dotSize[size],
            "rounded-full bg-current",
            speed === "fast" && "animate-[bounce_0.6s_infinite]",
            speed === "normal" && "animate-[bounce_1.4s_infinite]",
            speed === "slow" && "animate-[bounce_2s_infinite]"
          )}
          style={{
            animationDelay: `${i * (speed === "fast" ? 0.1 : speed === "slow" ? 0.3 : 0.2)}s`,
          }}
        />
      ))}
    </div>
  );
};

const renderPulse = (
  size: keyof typeof sizes,
  variant: keyof typeof variants,
  speed: keyof typeof speeds
) => {
  return (
    <div
      className={cn(
        sizes[size],
        "rounded-full bg-current",
        speed === "fast" && "animate-[pulse_0.8s_ease-in-out_infinite]",
        speed === "normal" && "animate-pulse",
        speed === "slow" && "animate-[pulse_3s_ease-in-out_infinite]"
      )}
    />
  );
};

const renderWave = (
  size: keyof typeof sizes,
  variant: keyof typeof variants,
  speed: keyof typeof speeds
) => {
  const barWidth = {
    xs: "w-0.5",
    sm: "w-0.5",
    md: "w-1",
    lg: "w-1.5",
    xl: "w-2",
  };

  const barSpacing = {
    xs: "space-x-0.5",
    sm: "space-x-0.5",
    md: "space-x-0.5",
    lg: "space-x-1",
    xl: "space-x-1",
  };

  return (
    <div className={cn("flex items-end", barSpacing[size], sizes[size])}>
      {[0, 1, 2, 3, 4].map(i => (
        <div
          key={i}
          className={cn(
            barWidth[size],
            "bg-current",
            speed === "fast" && "animate-[wave_0.6s_ease-in-out_infinite]",
            speed === "normal" && "animate-[wave_1.2s_ease-in-out_infinite]",
            speed === "slow" && "animate-[wave_2s_ease-in-out_infinite]"
          )}
          style={{
            height: "100%",
            animationDelay: `${i * (speed === "fast" ? 0.05 : speed === "slow" ? 0.2 : 0.1)}s`,
            transformOrigin: "bottom",
          }}
        />
      ))}
    </div>
  );
};

const renderBars = (
  size: keyof typeof sizes,
  variant: keyof typeof variants,
  speed: keyof typeof speeds
) => {
  const barHeight = {
    xs: "h-1",
    sm: "h-1.5",
    md: "h-2",
    lg: "h-3",
    xl: "h-4",
  };

  const barWidth = {
    xs: "w-0.5",
    sm: "w-1",
    md: "w-1",
    lg: "w-1.5",
    xl: "w-2",
  };

  const barSpacing = {
    xs: "space-x-0.5",
    sm: "space-x-0.5",
    md: "space-x-0.5",
    lg: "space-x-1",
    xl: "space-x-1",
  };

  return (
    <div className={cn("flex items-center", barSpacing[size])}>
      {[0, 1, 2].map(i => (
        <div
          key={i}
          className={cn(
            barWidth[size],
            "bg-current",
            barHeight[size],
            speed === "fast" && "animate-[bounce_0.6s_infinite]",
            speed === "normal" && "animate-[bounce_1.4s_infinite]",
            speed === "slow" && "animate-[bounce_2s_infinite]"
          )}
          style={{
            animationDelay: `${i * (speed === "fast" ? 0.1 : speed === "slow" ? 0.3 : 0.2)}s`,
          }}
        />
      ))}
    </div>
  );
};

const renderRing = (
  size: keyof typeof sizes,
  variant: keyof typeof variants,
  speed: keyof typeof speeds,
  strokeWidth: keyof typeof strokeWidths
) => {
  const borderWidthClasses = {
    thin: {
      xs: "border-[1.5px]",
      sm: "border-[1.5px]",
      md: "border-2",
      lg: "border-[2.5px]",
      xl: "border-[3px]",
    },
    normal: {
      xs: "border-2",
      sm: "border-2",
      md: "border-[2.5px]",
      lg: "border-[3px]",
      xl: "border-[3.5px]",
    },
    thick: {
      xs: "border-[2.5px]",
      sm: "border-[3px]",
      md: "border-[3.5px]",
      lg: "border-4",
      xl: "border-[5px]",
    },
  };

  return (
    <div
      className={cn(
        sizes[size],
        "rounded-full border-current border-t-transparent",
        borderWidthClasses[strokeWidth][size],
        speeds[speed]
      )}
    />
  );
};

export const Loader = React.forwardRef<HTMLDivElement, LoaderProps>(
  (
    {
      variant = "primary",
      color,
      size = "md",
      type = "spinner",
      className = "",
      label,
      fullSize = false,
      speed = "normal",
      strokeWidth = "normal",
      ...props
    },
    ref
  ) => {
    const renderLoader = () => {
      switch (type) {
        case "spinner":
          return renderSpinner(size, variant, speed, strokeWidth);
        case "dots":
          return renderDots(size, variant, speed);
        case "pulse":
          return renderPulse(size, variant, speed);
        case "wave":
          return renderWave(size, variant, speed);
        case "bars":
          return renderBars(size, variant, speed);
        case "ring":
          return renderRing(size, variant, speed, strokeWidth);
        default:
          return renderSpinner(size, variant, speed, strokeWidth);
      }
    };

    return (
      <div
        ref={ref}
        className={cn(
          base,
          !color && variants[variant],
          fullSize && "h-full w-full",
          label && "flex-col gap-2",
          className
        )}
        style={color ? { color } : undefined}
        role="status"
        aria-label={label || "Loading"}
        {...props}
      >
        {renderLoader()}
        {label && <span className="text-sm font-medium text-current">{label}</span>}
      </div>
    );
  }
);

Loader.displayName = "Loader";

import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { IoClose } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

export interface ModalProps {
  /**
   * Whether the modal is open
   */
  open: boolean;
  /**
   * Callback when modal should close
   */
  onClose: () => void;
  /**
   * The visual style of the modal
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the modal
   * @default "md"
   */
  size?: "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Control the border radius of the modal
   * @default "lg"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Prevent closing when clicking outside the modal
   * @default false
   */
  preventClose?: boolean;
  /**
   * Hide the close button
   * @default false
   */
  hideCloseButton?: boolean;
  /**
   * Modal title displayed in the header
   */
  title?: string;
  /**
   * Optional header content (overrides title)
   */
  header?: React.ReactNode;
  /**
   * Optional footer content
   */
  footer?: React.ReactNode;
  /**
   * Main modal content
   */
  children: React.ReactNode;
  /**
   * Custom class name for the modal container
   */
  className?: string;
  /**
   * Custom class name for the overlay
   */
  overlayClassName?: string;
  /**
   * ID for the modal element
   */
  id?: string;
  /**
   * Aria label for accessibility
   */
  ariaLabel?: string;
  /**
   * Aria labelledby for accessibility
   */
  ariaLabelledBy?: string;
  /**
   * Aria describedby for accessibility
   */
  ariaDescribedBy?: string;
}

// Base styles
const overlayBase = tw`fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm`;
const modalBase = tw`relative max-h-[85vh] w-full overflow-hidden bg-background text-foreground shadow-lg border border-border outline-none`;
const headerBase = tw`flex items-center justify-between border-b border-border px-6 py-4`;
const bodyBase = tw`flex-1 overflow-y-auto px-6 py-5 text-sm text-foreground/90`;
const footerBase = tw`border-t border-border px-6 py-4`;
const closeButtonBase = tw`rounded-md p-1.5 text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground rui-focus-ring focus:outline-none`;

// Variants
const variants = {
  primary: tw`border border-border`,
  secondary: tw`border border-border bg-muted`,
};

// Sizes
const sizes = {
  sm: tw`max-w-sm`,
  md: tw`max-w-md`,
  lg: tw`max-w-lg`,
  xl: tw`max-w-xl`,
  full: tw`mx-4 max-w-none sm:mx-8 md:mx-16`,
};

// Rounded options
const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
};

// Animation classes
const overlayAnimations = {
  enter: tw`animate-in fade-in-0 duration-200 ease-out`,
  exit: tw`animate-out fade-out-0 duration-150 ease-in`,
};

const modalAnimations = {
  enter: tw`animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 duration-200 ease-out`,
  exit: tw`animate-out fade-out-0 zoom-out-95 slide-out-to-top-2 duration-150 ease-in`,
};

export const Modal = React.forwardRef<HTMLDivElement, ModalProps>(
  (
    {
      open,
      onClose,
      variant = "primary",
      size = "md",
      rounded = "lg",
      animation = true,
      preventClose = false,
      hideCloseButton = false,
      title,
      header,
      footer,
      children,
      className = "",
      overlayClassName = "",
      id,
      ariaLabel,
      ariaLabelledBy,
      ariaDescribedBy,
      ...props
    },
    ref
  ) => {
    const modalRef = useRef<HTMLDivElement>(null);
    const previousFocusRef = useRef<HTMLElement | null>(null);

    const autoId = React.useId();
    const modalId = id ?? autoId;
    const titleId = `${modalId}-title`;
    const descId = `${modalId}-description`;

    // Focus management
    useEffect(() => {
      if (open) {
        // Store the previously focused element
        previousFocusRef.current = document.activeElement as HTMLElement;

        // Focus the modal container
        setTimeout(() => {
          modalRef.current?.focus();
        }, 50);
      } else if (previousFocusRef.current) {
        // Return focus to the previously focused element
        previousFocusRef.current.focus();
      }
    }, [open]);

    // Handle escape key
    useEffect(() => {
      const handleKeyDown = (event: KeyboardEvent) => {
        if (event.key === "Escape" && open && !preventClose) {
          onClose();
        }
      };

      if (open) {
        document.addEventListener("keydown", handleKeyDown);
        return () => document.removeEventListener("keydown", handleKeyDown);
      }
    }, [open, onClose, preventClose]);

    // Prevent body scroll when modal is open
    useEffect(() => {
      if (open) {
        const originalStyle = window.getComputedStyle(document.body).overflow;
        document.body.style.overflow = "hidden";
        return () => {
          document.body.style.overflow = originalStyle;
        };
      }
    }, [open]);

    // Handle overlay click
    const handleOverlayClick = (event: React.MouseEvent) => {
      if (event.target === event.currentTarget && !preventClose) {
        onClose();
      }
    };

    // Focus trap for accessibility
    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (event.key === "Tab") {
        const modal = modalRef.current;
        if (!modal) return;

        const focusableElements = modal.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        const firstFocusable = focusableElements[0] as HTMLElement;
        const lastFocusable = focusableElements[focusableElements.length - 1] as HTMLElement;

        if (event.shiftKey) {
          if (document.activeElement === firstFocusable) {
            event.preventDefault();
            lastFocusable?.focus();
          }
        } else {
          if (document.activeElement === lastFocusable) {
            event.preventDefault();
            firstFocusable?.focus();
          }
        }
      }
    };

    // Support exit animations by keeping mounted until animation completes
    const [isMounted, setIsMounted] = useState(open);
    const [isAnimatingOut, setIsAnimatingOut] = useState(false);

    useEffect(() => {
      if (open) {
        setIsMounted(true);
        setIsAnimatingOut(false);
      } else if (animation) {
        setIsAnimatingOut(true);
        const t = setTimeout(() => {
          setIsMounted(false);
          setIsAnimatingOut(false);
        }, 160); // match duration-150 + small buffer
        return () => clearTimeout(t);
      } else {
        setIsMounted(false);
      }
    }, [open, animation]);

    if (!isMounted) return null;

    const modalClasses = cn(
      modalBase,
      variants[variant],
      sizes[size],
      roundedOptions[rounded],
      animation && (isAnimatingOut ? modalAnimations.exit : modalAnimations.enter),
      className
    );

    const overlayClasses = cn(
      overlayBase,
      animation && (isAnimatingOut ? overlayAnimations.exit : overlayAnimations.enter),
      overlayClassName
    );

    const modalContent = (
      <div
        className={overlayClasses}
        onClick={handleOverlayClick}
        role="dialog"
        aria-modal="true"
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy || (title ? titleId : undefined)}
        aria-describedby={ariaDescribedBy || descId}
      >
        <div
          ref={ref || modalRef}
          className={modalClasses}
          tabIndex={-1}
          onKeyDown={handleKeyDown}
          id={modalId}
          {...props}
        >
          {/* Header */}
          {(header || title || !hideCloseButton) && (
            <div className={headerBase}>
              <div className="min-w-0 flex-1">
                {header ||
                  (title && (
                    <h2 id={titleId} className="text-foreground truncate text-lg font-semibold">
                      {title}
                    </h2>
                  ))}
              </div>
              {!hideCloseButton && (
                <button
                  type="button"
                  className={closeButtonBase}
                  onClick={onClose}
                  aria-label="Close modal"
                >
                  <IoClose className="h-5 w-5" />
                </button>
              )}
            </div>
          )}

          {/* Body */}
          <div id={descId} className={bodyBase}>
            {children}
          </div>

          {/* Footer */}
          {footer && <div className={footerBase}>{footer}</div>}
        </div>
      </div>
    );

    return createPortal(modalContent, document.body);
  }
);

Modal.displayName = "Modal";

import React, { useEffect, useRef, useState } from "react";
import { HiOutlineCheck, HiOutlineChevronDown } from "react-icons/hi";
import { IoClose } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

export interface MultiSelectOption {
  value: string;
  label: string;
  disabled?: boolean;
  icon?: React.ReactNode;
}

export interface MultiSelectProps {
  /**
   * The visual style of the multi-select
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the multi-select
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Control the border radius of the multi-select
   * @default "sm"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Make multi-select take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Preset width of the multi-select wrapper
   * @default "md"
   */
  width?: "sm" | "md" | "lg" | "xl";
  /**
   * Optional left icon - accepts any React element
   */
  startIcon?: React.ReactNode;
  /**
   * Optional label text displayed above the multi-select
   */
  label?: string;
  /**
   * Optional helper/description text displayed below the multi-select
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the multi-select
   */
  errorMessage?: string;
  /**
   * Array of options for the multi-select
   */
  options: MultiSelectOption[];
  /**
   * Placeholder text when no options are selected
   */
  placeholder?: string;
  /**
   * Selected values
   */
  value?: string[];
  /**
   * Default selected values
   */
  defaultValue?: string[];
  /**
   * Callback when values change
   */
  onValueChange?: (values: string[]) => void;
  /**
   * Whether the multi-select is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Maximum number of selections allowed
   */
  maxSelections?: number;
  /**
   * Show selected count in trigger
   * @default true
   */
  showSelectedCount?: boolean;
  /**
   * Custom selected count text formatter
   */
  selectedCountText?: (count: number, total: number) => string;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the multi-select element
   */
  id?: string;
  /**
   * Name attribute for the multi-select
   */
  name?: string;
}

// Match Input's design primitives for consistency
const wrapperBase = tw`relative inline-flex w-full flex-col`;
const fieldBase = tw`relative inline-flex items-center border bg-background text-foreground transition-colors duration-200 rui-field-focus`;

const variants = {
  primary: tw`border-input`,
  secondary: tw`border-input bg-muted`,
};

const sizes = {
  sm: {
    container: tw`min-h-8`,
    text: tw`text-xs`,
    padX: "px-2",
    padY: "py-1.5",
    gap: "gap-1.5",
  },
  md: {
    container: tw`min-h-9`,
    text: tw`text-sm`,
    padX: "px-3.5",
    padY: "py-2",
    gap: "gap-2",
  },
  lg: {
    container: tw`min-h-10`,
    text: tw`text-base`,
    padX: "px-4",
    padY: "py-2.5",
    gap: "gap-2.5",
  },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const labelSizes = {
  sm: tw`text-xs`,
  md: tw`text-sm`,
  lg: tw`text-base`,
};

const widths = {
  sm: tw`w-64`,
  md: tw`w-80`,
  lg: tw`w-96`,
  xl: tw`w-[30rem]`,
} as const;

const errorStyles = tw`border-destructive rui-field-error`;

const dropdownBase = tw`absolute top-full left-0 z-50 mt-2 max-h-60 w-full overflow-auto border border-border bg-popover text-popover-foreground shadow-md rounded-md`;

const optionBase = tw`flex w-full cursor-pointer items-center justify-between gap-2 px-3 py-2 text-left text-sm hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:outline-none disabled:cursor-not-allowed disabled:opacity-50`;

const optionAnimated = tw`transition-colors duration-150`;

const optionSelected = tw`text-primary`;
const optionDisabled = tw`cursor-not-allowed opacity-50`;

const chevronAnimated = tw`transition-transform duration-200`;

const labelBase = tw`mb-1 font-medium text-foreground`;

// Assistive text matches Input's layout
const assistiveContainer = tw`mt-1 min-h-[1rem] px-1`;
const descriptionText = tw`text-sm text-muted-foreground`;
const errorText = tw`text-sm text-destructive`;

// Selected item styles
const selectedItemBase = tw`inline-flex items-center gap-1 rounded-md bg-accent px-2 py-1 text-xs font-medium text-accent-foreground`;
const selectedItemRemove = tw`ml-1 flex h-3 w-3 cursor-pointer items-center justify-center rounded-full hover:bg-accent-foreground/20 focus:bg-accent-foreground/20 focus:outline-none`;

// Chevron down icon component
const ChevronDownIcon = ({ isOpen, animated }: { isOpen: boolean; animated: boolean }) => (
  <HiOutlineChevronDown
    className={cn(
      "text-muted-foreground h-4 w-4",
      animated && chevronAnimated,
      isOpen && "rotate-180"
    )}
  />
);

export const MultiSelect = React.forwardRef<HTMLButtonElement, MultiSelectProps>(
  (
    {
      variant = "primary",
      size = "md",
      className = "",
      fullWidth = false,
      width = "md",
      rounded = "sm",
      animation = true,
      error = false,
      disabled = false,
      startIcon,
      label,
      description,
      errorMessage,
      options,
      placeholder = "Select options...",
      value,
      defaultValue = [],
      onValueChange,
      maxSelections,
      showSelectedCount = true,
      selectedCountText,
      id,
      name,
      ...props
    },
    ref
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [selectedValues, setSelectedValues] = useState<string[]>(value || defaultValue || []);
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const [searchBuffer, setSearchBuffer] = useState("");
    const searchTimeout = useRef<NodeJS.Timeout | null>(null);
    const lastSearchedIndex = useRef<number>(-1);
    const triggerRef = useRef<HTMLButtonElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // Forward ref to the trigger button
    React.useImperativeHandle(ref, () => triggerRef.current as HTMLButtonElement);

    const autoId = React.useId();
    const selectId = id ?? autoId;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${selectId}-desc`;
    const listboxId = `${selectId}-listbox`;

    // Update selected values when controlled value changes
    useEffect(() => {
      if (value !== undefined) {
        setSelectedValues(value);
      }
    }, [value]);

    // Close dropdown when clicking outside
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          dropdownRef.current &&
          !dropdownRef.current.contains(event.target as Node) &&
          triggerRef.current &&
          !triggerRef.current.contains(event.target as Node)
        ) {
          setIsOpen(false);
          setFocusedIndex(-1);
        }
      };

      if (isOpen) {
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
      }
    }, [isOpen]);

    // Handle keyboard navigation and hidden search
    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (disabled) return;

      // Hidden search (type-to-select, cycles through matches)
      if (event.key.length === 1 && event.key.match(/^[^\s]$/)) {
        const char = event.key.toLowerCase();
        let newBuffer = searchBuffer + char;
        if (searchTimeout.current) clearTimeout(searchTimeout.current);
        searchTimeout.current = setTimeout(() => setSearchBuffer(""), 500);

        // Find all matching options
        const matches = options
          .map((opt, idx) => ({ idx, opt }))
          .filter(({ opt }) => !opt.disabled && opt.label.toLowerCase().startsWith(newBuffer));

        // If no matches, try just the last char
        if (matches.length === 0 && newBuffer.length > 1) {
          newBuffer = char;
          setSearchBuffer(newBuffer);
          const fallbackMatches = options
            .map((opt, idx) => ({ idx, opt }))
            .filter(({ opt }) => !opt.disabled && opt.label.toLowerCase().startsWith(newBuffer));
          if (fallbackMatches.length > 0) {
            lastSearchedIndex.current = fallbackMatches[0].idx;
            setFocusedIndex(fallbackMatches[0].idx);
            scrollToOption(fallbackMatches[0].idx);
          }
          return;
        }

        setSearchBuffer(newBuffer);
        if (matches.length > 0) {
          // Cycle through matches if same buffer is typed repeatedly
          let nextIdx = matches[0].idx;
          if (
            matches.length > 1 &&
            lastSearchedIndex.current !== -1 &&
            matches.some(({ idx }) => idx === lastSearchedIndex.current)
          ) {
            const currentIdx = matches.findIndex(({ idx }) => idx === lastSearchedIndex.current);
            nextIdx = matches[(currentIdx + 1) % matches.length].idx;
          }
          lastSearchedIndex.current = nextIdx;
          setFocusedIndex(nextIdx);
          scrollToOption(nextIdx);
        }
        return;
      }

      switch (event.key) {
        case "Enter":
        case " ":
          event.preventDefault();
          if (!isOpen) {
            setIsOpen(true);
            setFocusedIndex(0);
            setSearchBuffer("");
            lastSearchedIndex.current = -1;
          } else if (focusedIndex >= 0) {
            handleOptionToggle(options[focusedIndex].value);
          }
          break;
        case "Escape":
          setIsOpen(false);
          setFocusedIndex(-1);
          setSearchBuffer("");
          lastSearchedIndex.current = -1;
          triggerRef.current?.focus();
          break;
        case "ArrowDown": {
          event.preventDefault();
          if (!isOpen) {
            setIsOpen(true);
            setFocusedIndex(0);
            setSearchBuffer("");
            lastSearchedIndex.current = -1;
          } else {
            const nextIndex = Math.min(focusedIndex + 1, options.length - 1);
            setFocusedIndex(nextIndex);
            scrollToOption(nextIndex);
          }
          break;
        }
        case "ArrowUp": {
          event.preventDefault();
          if (isOpen) {
            const prevIndex = Math.max(focusedIndex - 1, 0);
            setFocusedIndex(prevIndex);
            scrollToOption(prevIndex);
          }
          break;
        }
        case "Tab":
          setIsOpen(false);
          setFocusedIndex(-1);
          setSearchBuffer("");
          lastSearchedIndex.current = -1;
          break;
      }
    };

    // Scroll to option helper
    const scrollToOption = (idx: number) => {
      if (!isOpen) return;
      const dropdown = dropdownRef.current;
      if (dropdown) {
        const optionEl = dropdown.querySelectorAll('button[role="option"]')[idx] as HTMLElement;
        optionEl?.scrollIntoView({ block: "nearest" });
      }
    };

    const handleOptionToggle = (optionValue: string) => {
      const option = options.find(opt => opt.value === optionValue);
      if (option?.disabled) return;

      const isSelected = selectedValues.includes(optionValue);
      let newValues: string[];

      if (isSelected) {
        // Remove the value
        newValues = selectedValues.filter(v => v !== optionValue);
      } else {
        // Add the value, respecting maxSelections
        if (maxSelections && selectedValues.length >= maxSelections) {
          return; // Don't add if at max
        }
        newValues = [...selectedValues, optionValue];
      }

      if (value === undefined) {
        setSelectedValues(newValues);
      }
      onValueChange?.(newValues);
    };

    const handleRemoveSelected = (valueToRemove: string, event: React.MouseEvent) => {
      event.stopPropagation();
      const newValues = selectedValues.filter(v => v !== valueToRemove);
      if (value === undefined) {
        setSelectedValues(newValues);
      }
      onValueChange?.(newValues);
    };

    const selectedOptions = options.filter(opt => selectedValues.includes(opt.value));

    // Default selected count text
    const defaultSelectedCountText = (count: number, total: number) =>
      count === total ? `${count} selected` : `${count} of ${total} selected`;

    const displayText =
      selectedOptions.length > 0
        ? showSelectedCount
          ? (selectedCountText || defaultSelectedCountText)(selectedOptions.length, options.length)
          : selectedOptions.map(opt => opt.label).join(", ")
        : placeholder;

    // Container matches Input field wrapper
    const containerClasses = cn(
      fieldBase,
      variants[variant],
      sizes[size].container,
      roundedOptions[rounded],
      sizes[size].padX,
      sizes[size].gap,
      error && errorStyles,
      fullWidth && "w-full",
      disabled && "cursor-not-allowed opacity-50",
      className
    );

    // Cap dropdown rounding at xl even if control is rounded-full
    const dropdownRadius = rounded === "full" ? tw`rounded-xl` : roundedOptions[rounded];

    return (
      <div className={cn(wrapperBase, fullWidth ? "w-full" : (widths[width] ?? "w-auto"))}>
        {/* Hidden inputs for form submission */}
        {selectedValues.map(val => (
          <input key={val} type="hidden" name={name} value={val} />
        ))}

        {label && (
          <label
            htmlFor={selectId}
            className={cn(labelBase, labelSizes[size], error && "text-destructive")}
          >
            {label}
          </label>
        )}

        <div
          className={containerClasses}
          onClick={() => {
            if (!disabled) {
              setIsOpen(!isOpen);
            }
          }}
        >
          {/* Show selected options' icons if any selected, else startIcon if provided */}
          {((selectedOptions.length > 0 && selectedOptions[0]?.icon) || startIcon) && (
            <span className="text-muted-foreground flex shrink-0 items-center">
              {selectedOptions[0]?.icon ? selectedOptions[0].icon : startIcon}
            </span>
          )}

          <div className="scrollbar-hide flex min-w-0 flex-1 items-center gap-1 overflow-auto">
            {selectedOptions.length > 0 && !showSelectedCount ? (
              selectedOptions.map(option => (
                <span key={option.value} className={cn(selectedItemBase)}>
                  {option.icon && <span className="mr-1 flex items-center">{option.icon}</span>}
                  <span className="truncate">{option.label}</span>
                  <button
                    type="button"
                    className={cn(selectedItemRemove)}
                    onClick={e => handleRemoveSelected(option.value, e)}
                    disabled={disabled}
                    aria-label={`Remove ${option.label}`}
                  >
                    <IoClose className="h-3 w-3" />
                  </button>
                </span>
              ))
            ) : (
              <span
                className={cn(
                  "text-foreground truncate select-none",
                  selectedOptions.length === 0 && "text-muted-foreground"
                )}
              >
                {displayText}
              </span>
            )}
          </div>

          <button
            ref={triggerRef}
            type="button"
            className={cn(
              "hover:bg-accent focus:bg-accent flex shrink-0 cursor-pointer items-center justify-center rounded p-1 focus:outline-none",
              disabled && "cursor-not-allowed opacity-50"
            )}
            onClick={e => {
              e.stopPropagation();
              if (!disabled) {
                setIsOpen(!isOpen);
              }
            }}
            onKeyDown={handleKeyDown}
            disabled={disabled}
            aria-expanded={isOpen}
            aria-haspopup="listbox"
            aria-controls={listboxId}
            aria-describedby={hasAssistive ? assistiveId : undefined}
            id={selectId}
            {...props}
          >
            <ChevronDownIcon isOpen={isOpen} animated={animation} />
          </button>

          {/* Dropdown is rendered inside the main container */}
          {isOpen && (
            <div
              ref={dropdownRef}
              id={listboxId}
              className={cn(
                dropdownBase,
                dropdownRadius,
                animation &&
                  "animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 duration-150 ease-out"
              )}
              role="listbox"
              aria-multiselectable="true"
              onClick={e => e.stopPropagation()}
            >
              {options.map((option, index) => {
                const isSelected = selectedValues.includes(option.value);
                const isAtMax = maxSelections ? selectedValues.length >= maxSelections : false;
                const isDisabled = option.disabled || (!isSelected && isAtMax);

                return (
                  <button
                    key={option.value}
                    type="button"
                    className={cn(
                      optionBase,
                      animation && optionAnimated,
                      isSelected && optionSelected,
                      isDisabled && optionDisabled,
                      index === focusedIndex && "bg-accent",
                      sizes[size].text,
                      sizes[size].padY
                    )}
                    onClick={() => handleOptionToggle(option.value)}
                    disabled={isDisabled}
                    role="option"
                    aria-selected={isSelected}
                  >
                    {/* Checkbox indicator */}
                    <div className="flex h-5 w-5 shrink-0 items-center justify-center">
                      {isSelected ? (
                        <HiOutlineCheck className="text-primary h-5 w-5" />
                      ) : (
                        <div className="border-border h-4 w-4 rounded border-2" />
                      )}
                    </div>

                    {/* Option icon, if provided */}
                    {option.icon && (
                      <span className="text-muted-foreground mr-2 flex items-center">
                        {option.icon}
                      </span>
                    )}

                    <span className="flex-1 truncate select-none">{option.label}</span>

                    {/* Max selections indicator */}
                    {isAtMax && !isSelected && (
                      <span className="text-muted-foreground text-xs">Max reached</span>
                    )}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {hasAssistive && (
          <div id={assistiveId} className={assistiveContainer}>
            {error && errorMessage ? (
              <span className={errorText}>{errorMessage}</span>
            ) : description ? (
              <span className={descriptionText}>{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

MultiSelect.displayName = "MultiSelect";

import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { IoChevronDown, IoChevronForward } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

// Main Menu Context
interface NavigationMenuContextType {
  orientation: "horizontal" | "vertical";
  size: "sm" | "md" | "lg";
  variant: "default" | "underline" | "pills";
  activeItem: string | null;
  setActiveItem: (value: string | null) => void;
  openMenus: Set<string>;
  toggleMenu: (value: string) => void;
}

const NavigationMenuContext = createContext<NavigationMenuContextType | null>(null);

const useNavigationMenu = () => {
  const context = useContext(NavigationMenuContext);
  if (!context) {
    throw new Error("NavigationMenu components must be used within a NavigationMenu");
  }
  return context;
};

// Item-specific Context
interface NavigationMenuItemContextType {
  value: string;
}

const NavigationMenuItemContext = createContext<NavigationMenuItemContextType | null>(null);

const useNavigationMenuItem = () => {
  const context = useContext(NavigationMenuItemContext);
  if (!context) {
    throw new Error(
      "NavigationMenuTrigger or NavigationMenuContent must be used within a NavigationMenuItem"
    );
  }
  return context;
};

// Base styles
const menuBase = tw`flex bg-background`;
const itemBase = tw`rui-focus-ring relative inline-flex w-full items-center justify-start px-3 py-2 text-left text-sm font-medium whitespace-nowrap transition-all focus:outline-none disabled:pointer-events-none disabled:opacity-50`;
const submenuBase = tw`absolute z-50 min-w-[12rem] overflow-hidden rounded-md border border-border bg-popover text-popover-foreground p-1 shadow-md`;

// Animation classes
const submenuAnimationIn = tw`animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 duration-150 ease-out`;
const submenuAnimationOut = tw`animate-out fade-out-0 zoom-out-95 slide-out-to-top-2 duration-100 ease-in`;

export interface NavigationMenuProps extends React.HTMLAttributes<HTMLElement> {
  /**
   * The orientation of the navigation menu
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * The size of the navigation items
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * The visual style of the navigation menu
   * @default "default"
   */
  variant?: "default" | "underline" | "pills";
  /**
   * Navigation menu content
   */
  children: React.ReactNode;
}

export interface NavigationMenuListProps extends React.HTMLAttributes<HTMLUListElement> {
  /**
   * Navigation menu list content (NavigationMenuItem components)
   */
  children: React.ReactNode;
}

export interface NavigationMenuItemProps extends React.HTMLAttributes<HTMLLIElement> {
  /**
   * Unique value for the navigation item
   */
  value: string;
  /**
   * Whether the item is active/currently selected
   * @default false
   */
  active?: boolean;
  /**
   * Navigation item content
   */
  children: React.ReactNode;
}

export interface NavigationMenuTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Trigger content
   */
  children: React.ReactNode;
}

export interface NavigationMenuContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Content to display in the submenu
   */
  children: React.ReactNode;
}

export interface NavigationMenuLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /**
   * Link content
   */
  children: React.ReactNode;
  /**
   * Whether the link is active
   * @default false
   */
  active?: boolean;
}

export interface NavigationMenuGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Group title
   */
  title?: string;
  /**
   * Group content
   */
  children: React.ReactNode;
}

// Menu variants
const menuVariants = {
  default: tw``,
  underline: tw`border-b border-border`,
  pills: tw`rounded-lg bg-muted p-1`,
};

const menuOrientations = {
  horizontal: tw`flex-row`,
  vertical: tw`flex-col`,
};

// Item variants with hover effects
const itemVariants = {
  default: {
    inactive: tw`cursor-pointer text-muted-foreground hover:bg-accent hover:text-accent-foreground`,
    active: tw`bg-accent text-accent-foreground`,
  },
  underline: {
    inactive: tw`cursor-pointer border-b-2 border-transparent text-muted-foreground hover:bg-accent hover:text-accent-foreground`,
    active: tw`border-b-2 border-primary text-primary`,
  },
  pills: {
    inactive: tw`cursor-pointer bg-transparent text-muted-foreground hover:bg-background hover:text-accent-foreground`,
    active: tw`bg-background text-primary shadow-sm`,
  },
};

const itemSizes = {
  sm: tw`px-2 py-1 text-xs`,
  md: tw`px-3 py-1.5 text-sm`,
  lg: tw`px-4 py-2 text-base`,
};

// Increased spacing for submenus
const submenuPositions = {
  horizontal: {
    top: tw`top-full left-0 mt-2`,
    bottom: tw`bottom-full left-0 mb-2`,
  },
  vertical: {
    right: tw`top-0 left-full ml-2`,
    left: tw`top-0 right-full mr-2`,
  },
};

export const NavigationMenu: React.FC<NavigationMenuProps> = ({
  children,
  className,
  orientation = "horizontal",
  size = "md",
  variant = "default",
  ...props
}) => {
  const [activeItem, setActiveItem] = useState<string | null>(null);
  const [openMenus, setOpenMenus] = useState<Set<string>>(new Set());

  const toggleMenu = useCallback(
    (value: string) => {
      setOpenMenus(prev => {
        const newSet = new Set(prev);
        if (newSet.has(value)) {
          newSet.delete(value);
        } else {
          if (orientation === "horizontal") newSet.clear();
          newSet.add(value);
        }
        return newSet;
      });
    },
    [orientation]
  );

  // Close menus on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (!(event.target as Element).closest("[data-navigation-menu]")) {
        setOpenMenus(new Set());
      }
    };

    if (openMenus.size > 0) {
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
    }
  }, [openMenus]);

  // Close menus on escape
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpenMenus(new Set());
      }
    };

    if (openMenus.size > 0) {
      document.addEventListener("keydown", handleKeyDown);
      return () => document.removeEventListener("keydown", handleKeyDown);
    }
  }, [openMenus]);

  const contextValue: NavigationMenuContextType = {
    orientation,
    size,
    variant,
    activeItem,
    setActiveItem,
    openMenus,
    toggleMenu,
  };

  return (
    <nav
      className={cn(menuBase, menuVariants[variant], menuOrientations[orientation], className)}
      data-navigation-menu
      {...props}
    >
      <NavigationMenuContext.Provider value={contextValue}>
        {children}
      </NavigationMenuContext.Provider>
    </nav>
  );
};

export const NavigationMenuList: React.FC<NavigationMenuListProps> = ({
  children,
  className,
  ...props
}) => {
  const { orientation } = useNavigationMenu();

  return (
    <ul
      className={cn("flex", orientation === "horizontal" ? "flex-row" : "flex-col", className)}
      role="menubar"
      {...props}
    >
      {children}
    </ul>
  );
};

export const NavigationMenuItem: React.FC<NavigationMenuItemProps> = ({
  children,
  className,
  value,
  active = false,
  ...props
}) => {
  const { activeItem, setActiveItem } = useNavigationMenu();

  useEffect(() => {
    if (active && activeItem !== value) {
      setActiveItem(value);
    }
  }, [active, value, activeItem, setActiveItem]);

  return (
    <NavigationMenuItemContext.Provider value={{ value }}>
      <li className={cn("relative", className)} role="none" {...props}>
        {children}
      </li>
    </NavigationMenuItemContext.Provider>
  );
};

export const NavigationMenuTrigger = React.forwardRef<
  HTMLButtonElement,
  NavigationMenuTriggerProps
>(({ children, className, onClick, ...props }, ref) => {
  const { orientation, size, variant, activeItem, openMenus, toggleMenu } = useNavigationMenu();
  const { value } = useNavigationMenuItem();

  const isActive = activeItem === value;
  const isOpen = openMenus.has(value);

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    toggleMenu(value);
    onClick?.(e);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      toggleMenu(value);
    }
  };

  const ChevronIcon = orientation === "horizontal" ? IoChevronDown : IoChevronForward;

  return (
    <button
      ref={ref}
      className={cn(
        itemBase,
        itemSizes[size],
        isActive ? itemVariants[variant].active : itemVariants[variant].inactive,
        (variant === "default" || variant === "pills") && "rounded-md",
        className
      )}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      aria-expanded={isOpen}
      aria-haspopup="true"
      role="menuitem"
      {...props}
    >
      {children}
      <ChevronIcon
        className={cn(
          "ml-1 h-3 w-3 transition-transform duration-200",
          isOpen && (orientation === "horizontal" ? "rotate-180" : "rotate-90")
        )}
      />
    </button>
  );
});

NavigationMenuTrigger.displayName = "NavigationMenuTrigger";

export const NavigationMenuContent = React.forwardRef<HTMLDivElement, NavigationMenuContentProps>(
  ({ children, className, ...props }, ref) => {
    const { orientation, openMenus } = useNavigationMenu();
    const { value } = useNavigationMenuItem();
    const contentRef = useRef<HTMLDivElement>(null);
    React.useImperativeHandle(ref, () => contentRef.current as HTMLDivElement);

    const isOpen = openMenus.has(value);
    const [shouldRender, setShouldRender] = useState(isOpen);
    const [isClosing, setIsClosing] = useState(false);
    const [positionClass, setPositionClass] = useState("");

    useEffect(() => {
      if (isOpen) {
        setShouldRender(true);
        setIsClosing(false);
      } else if (shouldRender) {
        setIsClosing(true);
        const timer = setTimeout(() => {
          setShouldRender(false);
          setIsClosing(false);
        }, 100);
        return () => clearTimeout(timer);
      }
    }, [isOpen, shouldRender]);

    useEffect(() => {
      if (isOpen && contentRef.current) {
        const anchorElement = contentRef.current.closest("li");
        if (!anchorElement) return;

        const anchorRect = anchorElement.getBoundingClientRect();
        const contentRect = contentRef.current.getBoundingClientRect();

        if (orientation === "vertical") {
          const spaceRight = window.innerWidth - anchorRect.right;
          if (spaceRight < contentRect.width && anchorRect.left >= contentRect.width) {
            setPositionClass(submenuPositions.vertical.left);
          } else {
            setPositionClass(submenuPositions.vertical.right);
          }
        } else {
          setPositionClass(submenuPositions.horizontal.top);
        }
      }
    }, [isOpen, orientation]);

    if (!shouldRender) return null;

    return (
      <div
        ref={contentRef}
        className={cn(
          submenuBase,
          isClosing ? submenuAnimationOut : submenuAnimationIn,
          positionClass,
          className
        )}
        role="menu"
        {...props}
      >
        {children}
      </div>
    );
  }
);

NavigationMenuContent.displayName = "NavigationMenuContent";

export const NavigationMenuLink = React.forwardRef<HTMLAnchorElement, NavigationMenuLinkProps>(
  ({ children, className, active = false, ...props }, ref) => {
    const { size, variant, activeItem } = useNavigationMenu();
    const isActive = active || activeItem === props.href;

    return (
      <a
        ref={ref}
        className={cn(
          itemBase,
          itemSizes[size],
          isActive ? itemVariants[variant].active : itemVariants[variant].inactive,
          (variant === "default" || variant === "pills") && "rounded-md",
          className
        )}
        role="menuitem"
        {...props}
      >
        {children}
      </a>
    );
  }
);

NavigationMenuLink.displayName = "NavigationMenuLink";

export const NavigationMenuGroup: React.FC<NavigationMenuGroupProps> = ({
  children,
  className,
  title,
  ...props
}) => {
  const { size } = useNavigationMenu();

  return (
    <div className={className} role="group" {...props}>
      {title && (
        <div
          className={cn(
            itemSizes[size],
            "border-border text-muted-foreground my-0.5 border-b font-semibold tracking-wider"
          )}
        >
          {title}
        </div>
      )}
      {children}
    </div>
  );
};

import React from "react";
import {
  HiChevronLeft as ChevronLeft,
  HiChevronRight as ChevronRight,
  HiChevronDoubleLeft as ChevronsLeft,
  HiChevronDoubleRight as ChevronsRight,
} from "react-icons/hi";
import { Button } from "@/components/ui/";
import { cn, tw } from "@/lib/utils";

export interface PaginationProps {
  /**
   * The current active page (1-indexed)
   */
  currentPage: number;
  /**
   * Total number of pages
   */
  totalPages: number;
  /**
   * Callback function called when page changes
   */
  onPageChange: (page: number) => void;
  /**
   * Maximum number of page buttons to show
   * @default 5
   */
  maxVisiblePages?: number;
  /**
   * Size of the pagination buttons
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Whether to show first/last navigation buttons
   * @default false
   */
  showFirstLast?: boolean;
  /**
   * Whether to show previous/next navigation buttons
   * @default true
   */
  showPrevNext?: boolean;
  /**
   * Whether the pagination is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Additional CSS classes
   */
  className?: string;
}

const base = tw`flex items-center gap-1`;

const sizes = {
  sm: tw`gap-1.5`,
  md: tw`gap-1.5`,
  lg: tw`gap-2`,
};

export const Pagination = React.forwardRef<HTMLDivElement, PaginationProps>(
  (
    {
      currentPage,
      totalPages,
      onPageChange,
      maxVisiblePages = 5,
      size = "md",
      showFirstLast = false,
      showPrevNext = true,
      disabled = false,
      className,
      ...props
    },
    ref
  ) => {
    // Ensure currentPage is within bounds
    const safeCurrentPage = Math.max(1, Math.min(currentPage, totalPages));

    // Calculate visible page range
    const getVisiblePages = () => {
      const half = Math.floor(maxVisiblePages / 2);
      let start = Math.max(1, safeCurrentPage - half);
      const end = Math.min(totalPages, start + maxVisiblePages - 1);

      // Adjust start if we're near the end
      if (end - start + 1 < maxVisiblePages) {
        start = Math.max(1, end - maxVisiblePages + 1);
      }

      return Array.from({ length: end - start + 1 }, (_, i) => start + i);
    };

    const visiblePages = getVisiblePages();
    const showStartEllipsis = visiblePages[0] > 2;
    const showEndEllipsis = visiblePages[visiblePages.length - 1] < totalPages - 1;

    const handlePageChange = (page: number) => {
      if (page >= 1 && page <= totalPages && page !== safeCurrentPage && !disabled) {
        onPageChange(page);
      }
    };

    const renderPageButton = (page: number, isActive = false) => (
      <Button
        key={page}
        variant={isActive ? "primary" : "secondary"}
        size={size === "sm" ? "xs" : size === "md" ? "sm" : "md"}
        onClick={() => handlePageChange(page)}
        disabled={disabled}
        className={tw`min-w-[2.5rem] px-3 ${isActive ? "outline-ring outline" : ""}`}
        aria-label={`Go to page ${page}`}
        aria-current={isActive ? "page" : undefined}
      >
        {page}
      </Button>
    );

    const renderEllipsis = (key: string) => (
      <span
        key={key}
        className={tw`text-muted-foreground flex h-8 w-8 items-center justify-center text-sm`}
        aria-hidden="true"
      >
        ...
      </span>
    );

    if (totalPages <= 1) {
      return null;
    }

    return (
      <nav
        ref={ref}
        className={cn(base, sizes[size], className)}
        aria-label="Pagination Navigation"
        {...props}
      >
        {/* First button */}
        {showFirstLast && (
          <Button
            variant="secondary"
            size={size === "sm" ? "xs" : size === "md" ? "sm" : "md"}
            onClick={() => handlePageChange(1)}
            disabled={disabled || safeCurrentPage === 1}
            aria-label="Go to first page"
          >
            <ChevronsLeft size={size === "sm" ? 14 : size === "md" ? 16 : 18} />
          </Button>
        )}

        {/* Previous button */}
        {showPrevNext && (
          <Button
            variant="secondary"
            size={size === "sm" ? "xs" : size === "md" ? "sm" : "md"}
            onClick={() => handlePageChange(safeCurrentPage - 1)}
            disabled={disabled || safeCurrentPage === 1}
            aria-label="Go to previous page"
          >
            <ChevronLeft size={size === "sm" ? 14 : size === "md" ? 16 : 18} />
          </Button>
        )}

        {/* First page if not in visible range */}
        {visiblePages[0] > 1 && renderPageButton(1)}

        {/* Start ellipsis */}
        {showStartEllipsis && renderEllipsis("start-ellipsis")}

        {/* Visible page numbers */}
        {visiblePages.map(page => renderPageButton(page, page === safeCurrentPage))}

        {/* End ellipsis */}
        {showEndEllipsis && renderEllipsis("end-ellipsis")}

        {/* Last page if not in visible range */}
        {visiblePages[visiblePages.length - 1] < totalPages && renderPageButton(totalPages)}

        {/* Next button */}
        {showPrevNext && (
          <Button
            variant="secondary"
            size={size === "sm" ? "xs" : size === "md" ? "sm" : "md"}
            onClick={() => handlePageChange(safeCurrentPage + 1)}
            disabled={disabled || safeCurrentPage === totalPages}
            aria-label="Go to next page"
          >
            <ChevronRight size={size === "sm" ? 14 : size === "md" ? 16 : 18} />
          </Button>
        )}

        {/* Last button */}
        {showFirstLast && (
          <Button
            variant="secondary"
            size={size === "sm" ? "xs" : size === "md" ? "sm" : "md"}
            onClick={() => handlePageChange(totalPages)}
            disabled={disabled || safeCurrentPage === totalPages}
            aria-label="Go to last page"
          >
            <ChevronsRight size={size === "sm" ? 14 : size === "md" ? 16 : 18} />
          </Button>
        )}
      </nav>
    );
  }
);

Pagination.displayName = "Pagination";

import React, { createContext, useContext, useEffect, useRef, useState } from "react";
import { cn, tw } from "@/lib/utils";

// Popover Context
interface PopoverContextType {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  triggerRef: React.RefObject<HTMLElement | null>;
  trigger: "click" | "hover" | "focus";
}

const PopoverContext = createContext<PopoverContextType | null>(null);

const usePopover = () => {
  const context = useContext(PopoverContext);
  if (!context) {
    throw new Error("Popover components must be used within a Popover");
  }
  return context;
};

// Base styles
const contentBase = tw`z-50 min-w-[8rem] overflow-hidden rounded-lg border border-border bg-popover text-popover-foreground p-4 shadow-md`;

// Animation classes
const contentAnimationIn = tw`animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 duration-200 ease-out`;
const contentAnimationOut = tw`animate-out fade-out-0 zoom-out-95 slide-out-to-top-2 duration-150 ease-in`;

export interface PopoverProps {
  /**
   * Popover content
   */
  children: React.ReactNode;
  /**
   * Whether the popover is open (controlled)
   */
  open?: boolean;
  /**
   * Default open state
   */
  defaultOpen?: boolean;
  /**
   * Callback when open state changes
   */
  onOpenChange?: (open: boolean) => void;
  /**
   * How the popover is triggered
   * @default "click"
   */
  trigger?: "click" | "hover" | "focus";
}

export interface PopoverTriggerProps {
  /**
   * Trigger element content
   */
  children: React.ReactNode;
  /**
   * Additional props for the trigger element
   */
  asChild?: boolean;
}

export interface PopoverContentProps {
  /**
   * Content alignment relative to trigger
   * @default "bottom-start"
   */
  align?:
    | "bottom-start"
    | "bottom-center"
    | "bottom-end"
    | "top-start"
    | "top-center"
    | "top-end"
    | "left"
    | "right";
  /**
   * Content to display in the popover
   */
  children: React.ReactNode;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * Whether clicking inside the popover should close it
   * @default false
   */
  closeOnClick?: boolean;
  /**
   * Offset from trigger element in pixels
   * @default 8
   */
  offset?: number;
  /**
   * Whether to automatically adjust position based on available viewport space
   * @default true
   */
  autoPosition?: boolean;
}

// Popover main component
export const Popover: React.FC<PopoverProps> = ({
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  trigger = "click",
}) => {
  const [isOpen, setIsOpen] = useState(open ?? defaultOpen);
  const triggerRef = useRef<HTMLElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const handleOpenChange = React.useCallback(
    (newOpen: boolean) => {
      if (open === undefined) {
        setIsOpen(newOpen);
      }
      onOpenChange?.(newOpen);
    },
    [open, onOpenChange]
  );

  // Update controlled state
  useEffect(() => {
    if (open !== undefined) {
      setIsOpen(open);
    }
  }, [open]);

  // Close on outside click (for click trigger)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        trigger === "click" &&
        triggerRef.current &&
        !triggerRef.current.contains(event.target as Node) &&
        !(event.target as Element).closest("[data-popover-content]")
      ) {
        handleOpenChange(false);
      }
    };

    if (isOpen && trigger === "click") {
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
    }
  }, [isOpen, handleOpenChange, trigger]);

  // Close on escape
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handleOpenChange(false);
      }
    };

    if (isOpen) {
      document.addEventListener("keydown", handleKeyDown);
      return () => document.removeEventListener("keydown", handleKeyDown);
    }
  }, [isOpen, handleOpenChange]);

  // Cleanup timeout on unmount
  useEffect(() => {
    const currentTimeout = timeoutRef.current;
    return () => {
      if (currentTimeout) {
        clearTimeout(currentTimeout);
      }
    };
  }, []);

  const contextValue: PopoverContextType = {
    isOpen,
    setIsOpen: handleOpenChange,
    triggerRef,
    trigger,
  };

  return (
    <div className="relative">
      <PopoverContext.Provider value={contextValue}>{children}</PopoverContext.Provider>
    </div>
  );
};

// PopoverTrigger component
export const PopoverTrigger = React.forwardRef<HTMLElement, PopoverTriggerProps>(
  ({ children, asChild = false, ...props }, forwardedRef) => {
    const { isOpen, setIsOpen, triggerRef, trigger } = usePopover();

    // Use the forwarded ref if provided, otherwise use the context ref
    const ref = React.useRef<HTMLElement>(null);
    const actualRef = forwardedRef || triggerRef;

    React.useImperativeHandle(actualRef, () => ref.current as HTMLElement);

    const handleClick = () => {
      if (trigger === "click") {
        setIsOpen(!isOpen);
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (trigger === "click" && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        setIsOpen(!isOpen);
      }
    };

    const handleMouseEnter = () => {
      if (trigger === "hover") {
        setIsOpen(true);
      }
    };

    const handleMouseLeave = () => {
      if (trigger === "hover") {
        setIsOpen(false);
      }
    };

    const handleFocus = () => {
      if (trigger === "focus") {
        setIsOpen(true);
      }
    };

    const handleBlur = (event: React.FocusEvent) => {
      if (trigger === "focus") {
        // Add a small delay to allow focus to move to popover content
        setTimeout(() => {
          const relatedTarget = event.relatedTarget as Element;
          const activeElement = document.activeElement as Element;

          // Don't close if focus is on popover content or moving to it
          if (
            !relatedTarget?.closest("[data-popover-content]") &&
            !activeElement?.closest("[data-popover-content]")
          ) {
            setIsOpen(false);
          }
        }, 10);
      }
    };

    if (asChild && React.isValidElement(children)) {
      const childProps = children.props as React.HTMLAttributes<HTMLElement>;
      const existingStyle = childProps.style || {};
      return React.cloneElement(children, {
        ref: (node: HTMLElement) => {
          ref.current = node;
          if (typeof actualRef === "function") {
            actualRef(node);
          } else if (actualRef) {
            actualRef.current = node;
          }
        },
        onClick: handleClick,
        onKeyDown: handleKeyDown,
        ...(trigger === "hover" && {
          onMouseEnter: handleMouseEnter,
          onMouseLeave: handleMouseLeave,
        }),
        ...(trigger === "focus" && {
          onFocus: handleFocus,
          onBlur: handleBlur,
        }),
        "aria-expanded": isOpen,
        "aria-haspopup": "dialog",
        style: { position: "relative", ...existingStyle },
        ...props,
      } as React.HTMLAttributes<HTMLElement>);
    }

    return (
      <button
        ref={node => {
          ref.current = node;
          if (typeof actualRef === "function") {
            actualRef(node);
          } else if (actualRef) {
            actualRef.current = node;
          }
        }}
        type="button"
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        {...(trigger === "hover" && {
          onMouseEnter: handleMouseEnter,
          onMouseLeave: handleMouseLeave,
        })}
        {...(trigger === "focus" && {
          onFocus: handleFocus,
          onBlur: handleBlur,
        })}
        aria-expanded={isOpen}
        aria-haspopup="dialog"
        style={{ position: "relative" }}
        {...props}
      >
        {children}
      </button>
    );
  }
);

PopoverTrigger.displayName = "PopoverTrigger";

export const PopoverContent = React.forwardRef<HTMLDivElement, PopoverContentProps>(
  (
    {
      align = "bottom-start",
      className,
      children,
      closeOnClick = false,
      offset = 8,
      autoPosition = true,
      ...props
    },
    ref
  ) => {
    const { isOpen, triggerRef, setIsOpen, trigger } = usePopover();
    const contentRef = useRef<HTMLDivElement>(null);
    const [actualAlign, setActualAlign] = useState(align);
    const [isClosing, setIsClosing] = useState(false);
    const [shouldRender, setShouldRender] = useState(isOpen);

    // Handle opening and closing animations
    useEffect(() => {
      if (isOpen) {
        setShouldRender(true);
        setIsClosing(false);
      } else if (shouldRender) {
        setIsClosing(true);
        // Remove the element after animation completes
        const timeout = setTimeout(() => {
          setShouldRender(false);
          setIsClosing(false);
        }, 150); // Match the animation duration
        return () => clearTimeout(timeout);
      }
    }, [isOpen, shouldRender]);

    useEffect(() => {
      if (isOpen && contentRef.current && triggerRef.current && autoPosition) {
        // Use requestAnimationFrame to ensure content is fully rendered before calculating position
        requestAnimationFrame(() => {
          if (contentRef.current && triggerRef.current) {
            const contentRect = contentRef.current.getBoundingClientRect();
            const triggerRect = triggerRef.current.getBoundingClientRect();
            const viewportWidth = window.innerWidth;
            const viewportHeight = window.innerHeight;

            // Calculate available space for each alignment
            const alignments = [
              {
                align: "bottom-start" as const,
                space: {
                  vertical: viewportHeight - triggerRect.bottom,
                  horizontal: viewportWidth - triggerRect.left,
                },
              },
              {
                align: "bottom-center" as const,
                space: {
                  vertical: viewportHeight - triggerRect.bottom,
                  horizontal:
                    Math.min(
                      triggerRect.left + triggerRect.width / 2,
                      viewportWidth - (triggerRect.left + triggerRect.width / 2)
                    ) * 2,
                },
              },
              {
                align: "bottom-end" as const,
                space: {
                  vertical: viewportHeight - triggerRect.bottom,
                  horizontal: triggerRect.right,
                },
              },
              {
                align: "top-start" as const,
                space: {
                  vertical: triggerRect.top,
                  horizontal: viewportWidth - triggerRect.left,
                },
              },
              {
                align: "top-center" as const,
                space: {
                  vertical: triggerRect.top,
                  horizontal:
                    Math.min(
                      triggerRect.left + triggerRect.width / 2,
                      viewportWidth - (triggerRect.left + triggerRect.width / 2)
                    ) * 2,
                },
              },
              {
                align: "top-end" as const,
                space: {
                  vertical: triggerRect.top,
                  horizontal: triggerRect.right,
                },
              },
              {
                align: "left" as const,
                space: {
                  vertical: Math.max(triggerRect.top, viewportHeight - triggerRect.bottom),
                  horizontal: triggerRect.left,
                },
              },
              {
                align: "right" as const,
                space: {
                  vertical: Math.max(triggerRect.top, viewportHeight - triggerRect.bottom),
                  horizontal: viewportWidth - triggerRect.right,
                },
              },
            ];

            // Find the best alignment that fits
            let bestAlign = align;
            let maxVisibleArea = 0;

            for (const { align: testAlign, space } of alignments) {
              const requiredWidth = contentRect.width;
              const requiredHeight = contentRect.height;

              const fitsHorizontally = space.horizontal >= requiredWidth;
              const fitsVertically = space.vertical >= requiredHeight;

              if (fitsHorizontally && fitsVertically) {
                const visibleArea = space.horizontal * space.vertical;
                if (visibleArea > maxVisibleArea) {
                  maxVisibleArea = visibleArea;
                  bestAlign = testAlign;
                }
              }
            }

            setActualAlign(bestAlign);
          }
        });
      } else if (!autoPosition) {
        setActualAlign(align);
      }
    }, [isOpen, align, children, triggerRef, autoPosition]);

    const getPositionStyles = (): React.CSSProperties => {
      if (!triggerRef.current) return {};

      const triggerRect = triggerRef.current.getBoundingClientRect();
      const containerRect = triggerRef.current.parentElement?.getBoundingClientRect();

      if (!containerRect) return {};

      // Calculate trigger position relative to container
      const triggerLeft = triggerRect.left - containerRect.left;
      const triggerTop = triggerRect.top - containerRect.top;
      const triggerWidth = triggerRect.width;
      const triggerHeight = triggerRect.height;

      switch (actualAlign) {
        case "bottom-start":
          return {
            position: "absolute",
            left: `${triggerLeft}px`,
            top: `${triggerTop + triggerHeight + offset}px`,
          };
        case "bottom-center":
          return {
            position: "absolute",
            left: `${triggerLeft + triggerWidth / 2}px`,
            top: `${triggerTop + triggerHeight + offset}px`,
            transform: "translateX(-50%)",
          };
        case "bottom-end":
          return {
            position: "absolute",
            left: `${triggerLeft + triggerWidth}px`,
            top: `${triggerTop + triggerHeight + offset}px`,
            transform: "translateX(-100%)",
          };
        case "top-start":
          return {
            position: "absolute",
            left: `${triggerLeft}px`,
            top: `${triggerTop - offset}px`,
            transform: "translateY(-100%)",
          };
        case "top-center":
          return {
            position: "absolute",
            left: `${triggerLeft + triggerWidth / 2}px`,
            top: `${triggerTop - offset}px`,
            transform: "translateX(-50%) translateY(-100%)",
          };
        case "top-end":
          return {
            position: "absolute",
            left: `${triggerLeft + triggerWidth}px`,
            top: `${triggerTop - offset}px`,
            transform: "translateX(-100%) translateY(-100%)",
          };
        case "left":
          return {
            position: "absolute",
            left: `${triggerLeft - offset}px`,
            top: `${triggerTop + triggerHeight / 2}px`,
            transform: "translateX(-100%) translateY(-50%)",
          };
        case "right":
          return {
            position: "absolute",
            left: `${triggerLeft + triggerWidth + offset}px`,
            top: `${triggerTop + triggerHeight / 2}px`,
            transform: "translateY(-50%)",
          };
        default:
          return {};
      }
    };

    const handleContentClick = () => {
      if (closeOnClick) {
        setIsOpen(false);
      }
    };

    const handleContentFocus = () => {
      // Keep popover open when content receives focus for focus trigger
    };

    const handleContentBlur = () => {
      if (trigger === "focus") {
        // Check if focus is moving back to trigger or staying within popover
        setTimeout(() => {
          const activeElement = document.activeElement as Element;
          const triggerElement = triggerRef.current;

          if (
            !activeElement?.closest("[data-popover-content]") &&
            activeElement !== triggerElement
          ) {
            setIsOpen(false);
          }
        }, 10);
      }
    };
    if (!shouldRender) {
      return null;
    }

    if (!shouldRender) return null;

    const animationClass = isClosing ? contentAnimationOut : contentAnimationIn;

    return (
      <div
        ref={node => {
          contentRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        className={cn(contentBase, animationClass, className)}
        data-popover-content
        role="dialog"
        style={getPositionStyles()}
        onClick={handleContentClick}
        onFocus={handleContentFocus}
        onBlur={handleContentBlur}
        tabIndex={trigger === "focus" ? 0 : -1}
        {...props}
      >
        {children}
      </div>
    );
  }
);

PopoverContent.displayName = "PopoverContent";

import React from "react";
import { cn, tw } from "@/lib/utils";

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The current progress value (0-100)
   * @default 0
   */
  value?: number;
  /**
   * The maximum value for progress calculation
   * @default 100
   */
  max?: number;
  /**
   * The visual style of the progress bar
   * @default "bar"
   */
  variant?: "bar" | "circular";
  /**
   * The size of the progress bar
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * The visual style variant
   * @default "filled"
   */
  appearance?: "filled" | "outline" | "soft";
  /**
   * Control the border radius of the progress bar
   * @default "full"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Whether to show the progress percentage text
   * @default false
   */
  showValue?: boolean;
  /**
   * Custom label text to display instead of percentage
   */
  label?: string;
  /**
   * Whether the progress bar is animated
   * @default false
   */
  animated?: boolean;
  /**
   * Whether the progress bar is striped
   * @default false
   */
  striped?: boolean;
  /**
   * Whether to show indeterminate state (animated loading)
   * @default false
   */
  indeterminate?: boolean;
  /**
   * Custom class name for the progress bar track
   */
  trackClassName?: string;
  /**
   * Custom class name for the progress bar fill
   */
  fillClassName?: string;
}

// Base styles
const progressBase = tw`relative w-full overflow-hidden`;

// Track styles
const trackBase = tw`w-full bg-muted`;

// Variants - filled style
const variantsFilled = {
  bar: tw`bg-primary`,
  circular: tw`text-primary`,
};

// Variants - outline style
const variantsOutline = {
  bar: tw`border border-primary bg-primary/10`,
  circular: tw`text-primary`,
};

// Variants - soft style
const variantsSoft = {
  bar: tw`bg-primary/15`,
  circular: tw`text-primary/60`,
};

// Sizes
const sizes = {
  sm: {
    track: tw`h-1`,
    fill: tw`h-1`,
    text: tw`text-xs`,
    circular: tw`h-12 w-12`,
  },
  md: {
    track: tw`h-2`,
    fill: tw`h-2`,
    text: tw`text-sm`,
    circular: tw`h-16 w-16`,
  },
  lg: {
    track: tw`h-3`,
    fill: tw`h-3`,
    text: tw`text-base`,
    circular: tw`h-20 w-20`,
  },
};

// Rounded options
const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

// Animation styles
const animatedFill = tw`transition-all duration-300 ease-out`;
const stripedFill = tw`relative overflow-hidden`;
const stripedFillOverlay = tw`absolute inset-0 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-white/40 to-transparent bg-[length:20px_20px]`;
const indeterminateFill = tw`animate-[indeterminate_1.5s_ease-in-out_infinite]`;
const circularIndeterminate = tw`animate-spin`;

export const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(
  (
    {
      value = 0,
      max = 100,
      variant = "bar",
      size = "md",
      appearance = "filled",
      rounded = "full",
      showValue = false,
      label,
      animated = false,
      striped = false,
      indeterminate = false,
      className = "",
      trackClassName = "",
      fillClassName = "",
      ...props
    },
    ref
  ) => {
    // Calculate percentage
    const percentage = Math.min(Math.max((value / max) * 100, 0), 100);

    // Get variant styles based on appearance prop
    const getVariantStyles = () => {
      if (variant === "circular") {
        // For circular, we use text color variants
        switch (appearance) {
          case "outline":
            return variantsOutline.circular;
          case "soft":
            return variantsSoft.circular;
          default:
            return variantsFilled.circular;
        }
      } else {
        // For bar variant, use background color variants
        switch (appearance) {
          case "outline":
            return variantsOutline.bar;
          case "soft":
            return variantsSoft.bar;
          default:
            return variantsFilled.bar;
        }
      }
    };

    // Get fill styles
    const getFillStyles = () => {
      const baseStyles = [getVariantStyles()];

      if (animated) {
        baseStyles.push(animatedFill);
      }

      if (striped) {
        baseStyles.push(stripedFill);
      }

      if (indeterminate) {
        baseStyles.push(indeterminateFill);
      }

      return cn(baseStyles);
    };

    // Get progress width
    const progressWidth = indeterminate ? "100%" : `${percentage}%`;

    return (
      <div
        ref={ref}
        className={cn(progressBase, className)}
        role="progressbar"
        aria-valuenow={indeterminate ? undefined : percentage}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={label || "Progress"}
        {...props}
      >
        {variant === "bar" ? (
          <div className="flex flex-col gap-2">
            {/* Top row: Label and Value */}
            {(label || showValue) && (
              <div className="flex items-center justify-between">
                {/* Label on the left */}
                <div>
                  {label && (
                    <div className="text-foreground flex-shrink-0 text-sm font-medium">{label}</div>
                  )}
                </div>

                {/* Value on the right */}
                <div>
                  {showValue && (
                    <div
                      className={cn(
                        sizes[size].text,
                        "text-muted-foreground flex-shrink-0 font-medium"
                      )}
                    >
                      {Math.round(percentage)}%
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Bottom row: Progress bar */}
            <div className="relative">
              <div
                className={cn(
                  trackBase,
                  sizes[size].track,
                  roundedOptions[rounded],
                  trackClassName
                )}
              >
                {/* Fill */}
                <div
                  className={cn(sizes[size].fill, getFillStyles(), fillClassName)}
                  style={{
                    width: progressWidth,
                    borderRadius: rounded === "full" ? "inherit" : undefined,
                  }}
                >
                  {/* Striped overlay */}
                  {striped && <div className={cn(stripedFillOverlay)} />}
                </div>
              </div>
            </div>
          </div>
        ) : (
          // Circular variant
          <div className={cn("relative flex items-center justify-center", sizes[size].circular)}>
            <svg
              className={cn(
                "h-full w-full -rotate-90 transform",
                indeterminate && circularIndeterminate
              )}
              viewBox="0 0 100 100"
            >
              <circle
                cx="50"
                cy="50"
                r="45"
                fill="none"
                stroke="currentColor"
                strokeWidth="8"
                className="text-muted"
              />
              {indeterminate ? (
                // Indeterminate state: show a partial arc that rotates
                <circle
                  cx="50"
                  cy="50"
                  r="45"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="8"
                  strokeDasharray="70 200"
                  strokeLinecap="round"
                  className={cn(getVariantStyles())}
                />
              ) : (
                // Determinate state: show progress based on percentage
                <circle
                  cx="50"
                  cy="50"
                  r="45"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="8"
                  strokeDasharray={`${percentage * 2.827} 282.7`}
                  strokeLinecap="round"
                  className={cn("transition-all duration-300", getVariantStyles())}
                />
              )}
            </svg>
            <div className="absolute inset-0 flex items-center justify-center">
              <span className={cn(sizes[size].text, "text-foreground font-medium")}>
                {showValue && !indeterminate ? `${Math.round(percentage)}%` : ""}
              </span>
            </div>
          </div>
        )}
      </div>
    );
  }
);

Progress.displayName = "Progress";

import React, { useEffect, useState } from "react";
import { cn, tw } from "@/lib/utils";

export interface RadioOption {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
  icon?: React.ReactNode;
}

export interface RadioGroupProps {
  /**
   * The visual style of the radio group
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the radio buttons
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Control the border radius of the radio buttons
   * @default "full"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Layout direction of radio options
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal";
  /**
   * Array of radio options
   */
  options: RadioOption[];
  /**
   * Selected value
   */
  value?: string;
  /**
   * Default selected value (uncontrolled)
   */
  defaultValue?: string;
  /**
   * Callback when value changes
   */
  onValueChange?: (value: string) => void;
  /**
   * Whether the entire radio group is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Optional label for the radio group
   */
  label?: string;
  /**
   * Optional helper/description text displayed below the radio group
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the radio group
   */
  errorMessage?: string;
  /**
   * Whether the radio group is required
   * @default false
   */
  required?: boolean;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * Name attribute for all radio buttons (auto-generated if not provided)
   */
  name?: string;
}

const wrapperBase = tw`relative flex flex-col`;
const groupBase = tw`flex`;

// Radio button visual box — no Tailwind ring utilities; peer-focus-visible box-shadow
const radioBase = tw`relative inline-flex items-center justify-center border transition-all duration-150 outline-none`;

const variants = {
  primary: {
    unchecked: tw`border-input bg-background hover:border-primary`,
    checked: tw`border-primary bg-primary`,
  },
  secondary: {
    unchecked: tw`border-input bg-background hover:border-secondary-foreground`,
    checked: tw`border-secondary-foreground bg-secondary-foreground`,
  },
};

const sizes = {
  sm: {
    radio: tw`h-3 w-3`,
    dot: tw`h-1 w-1`,
    gap: tw`gap-2`,
    text: tw`text-xs`,
    spacing: tw`space-y-2`,
  },
  md: {
    radio: tw`h-4 w-4`,
    dot: tw`h-1.5 w-1.5`,
    gap: tw`gap-3`,
    text: tw`text-sm`,
    spacing: tw`space-y-3`,
  },
  lg: {
    radio: tw`h-5 w-5`,
    dot: tw`h-2 w-2`,
    gap: tw`gap-4`,
    text: tw`text-base`,
    spacing: tw`space-y-4`,
  },
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const animateDotIn = tw`animate-in fade-in-0 zoom-in-95 duration-150 ease-out`;

// Keyboard-only focus ring for radio buttons (via peer-focus-visible)
const focusRingClass =
  "peer-focus-visible:shadow-[0_0_0_var(--ring-offset)_hsl(var(--background)),0_0_0_calc(var(--ring-offset)+var(--ring-width))_var(--ring-color)]";

export const RadioGroup = React.forwardRef<HTMLDivElement, RadioGroupProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "full",
      animation = true,
      orientation = "vertical",
      options,
      value,
      defaultValue,
      onValueChange,
      disabled = false,
      label,
      description,
      error = false,
      errorMessage,
      required = false,
      className = "",
      name,
      ...props
    },
    ref
  ) => {
    const [selectedValue, setSelectedValue] = useState(value ?? defaultValue ?? "");

    const autoId = React.useId();
    const groupName = name ?? `radio-group-${autoId}`;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${autoId}-desc`;

    useEffect(() => {
      if (value !== undefined) setSelectedValue(value);
    }, [value]);

    const handleOptionChange = (optionValue: string) => {
      if (disabled) return;
      const option = options.find(opt => opt.value === optionValue);
      if (option?.disabled) return;
      if (value === undefined) setSelectedValue(optionValue);
      onValueChange?.(optionValue);
    };

    const groupClasses = cn(
      groupBase,
      orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
      orientation === "vertical" ? sizes[size].spacing : sizes[size].gap
    );

    const renderOptions = () =>
      options.map(option => {
        const isSelected = selectedValue === option.value;
        const isDisabled = disabled || option.disabled;
        const radioId = `${groupName}-${option.value}`;

        return (
          <div key={option.value} className="relative flex items-start">
            <div className="flex items-center">
              <input
                type="radio"
                id={radioId}
                name={groupName}
                value={option.value}
                checked={isSelected}
                onChange={() => handleOptionChange(option.value)}
                disabled={isDisabled}
                className="peer sr-only"
              />
              <label
                htmlFor={radioId}
                className={cn(
                  "flex cursor-pointer items-center",
                  sizes[size].gap,
                  isDisabled && "cursor-not-allowed"
                )}
              >
                <div
                  className={cn(
                    radioBase,
                    sizes[size].radio,
                    roundedOptions[rounded],
                    isSelected ? variants[variant].checked : variants[variant].unchecked,
                    isDisabled && "cursor-not-allowed opacity-50",
                    error && !isSelected && "border-destructive",
                    focusRingClass
                  )}
                >
                  {isSelected && (
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div
                        className={cn(
                          "bg-primary-foreground rounded-full",
                          sizes[size].dot,
                          animation && animateDotIn
                        )}
                      />
                    </div>
                  )}
                </div>

                <div className="flex flex-col">
                  <div className="flex items-center gap-2">
                    {option.icon && (
                      <span
                        className={cn(
                          "text-muted-foreground flex items-center",
                          isDisabled && "opacity-50"
                        )}
                      >
                        {option.icon}
                      </span>
                    )}
                    <span
                      className={cn(
                        "text-foreground leading-tight font-medium",
                        sizes[size].text,
                        isDisabled && "text-muted-foreground",
                        error && "text-destructive"
                      )}
                    >
                      {option.label}
                    </span>
                  </div>

                  {option.description && (
                    <span
                      className={cn(
                        "text-muted-foreground mt-1 leading-snug",
                        sizes[size].text,
                        isDisabled && "opacity-70"
                      )}
                    >
                      {option.description}
                    </span>
                  )}
                </div>
              </label>
            </div>
          </div>
        );
      });

    return (
      <div ref={ref} className={cn(wrapperBase, className)} {...props}>
        {label && (
          <fieldset className="w-full">
            <legend
              className={cn(
                "text-foreground mb-3 font-medium",
                sizes[size].text,
                error && "text-destructive"
              )}
            >
              {label}
              {required && <span className="text-destructive ml-1">*</span>}
            </legend>

            <div
              className={groupClasses}
              role="radiogroup"
              aria-describedby={hasAssistive ? assistiveId : undefined}
              aria-required={required}
              aria-invalid={error}
            >
              {renderOptions()}
            </div>
          </fieldset>
        )}

        {!label && (
          <div
            className={groupClasses}
            role="radiogroup"
            aria-describedby={hasAssistive ? assistiveId : undefined}
            aria-required={required}
            aria-invalid={error}
          >
            {renderOptions()}
          </div>
        )}

        {hasAssistive && (
          <div id={assistiveId} className="mt-1 min-h-[1rem] px-1">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

RadioGroup.displayName = "RadioGroup";

import React, { useEffect, useRef, useState } from "react";
import { cn, tw } from "@/lib/utils";

export interface RangeInputProps {
  /**
   * The current range values
   */
  value?: [number, number];
  /**
   * Default range values for uncontrolled component
   * @default [0, 100]
   */
  defaultValue?: [number, number];
  /**
   * Minimum value
   * @default 0
   */
  min?: number;
  /**
   * Maximum value
   * @default 100
   */
  max?: number;
  /**
   * Step increment
   * @default 1
   */
  step?: number;
  /**
   * Whether the range input is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * The visual style of the range input
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the range input
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Show value labels
   * @default false
   */
  showValue?: boolean;
  /**
   * Custom value formatter
   */
  valueFormatter?: (value: number) => string;
  /**
   * Optional label text displayed above the range input
   */
  label?: string;
  /**
   * Optional helper/description text displayed below the range input
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the range input
   */
  errorMessage?: string;
  /**
   * Callback when range values change
   */
  onChange?: (value: [number, number]) => void;
  /**
   * Callback when range value change ends
   */
  onChangeEnd?: (value: [number, number]) => void;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the range input element
   */
  id?: string;
}

const wrapperBase = tw`inline-flex w-full flex-col`;

// Sizes map matching Slider exactly (wrapper height is equal to thumb height)
const sizes = {
  sm: { wrapper: tw`h-4 min-w-[120px]`, track: tw`h-1`, thumb: tw`h-3 w-3`, text: tw`text-xs` },
  md: { wrapper: tw`h-5 min-w-[160px]`, track: tw`h-2`, thumb: tw`h-4 w-4`, text: tw`text-sm` },
  lg: { wrapper: tw`h-6 min-w-[200px]`, track: tw`h-3`, thumb: tw`h-5 w-5`, text: tw`text-base` },
} as const;

const trackFillVariants = {
  primary: tw`bg-primary`,
  secondary: tw`bg-secondary-foreground`,
};

const thumbBase = tw`
  absolute top-1/2 -translate-y-1/2
  block cursor-pointer rounded-full
  border border-border bg-background
  shadow-sm transition-[transform,shadow,border-color,background-color] duration-150 ease-in-out
  hover:scale-110 hover:shadow-md
  disabled:cursor-not-allowed disabled:opacity-50 disabled:shadow-none
`;

export const RangeInput = React.forwardRef<HTMLDivElement, RangeInputProps>(
  (
    {
      value,
      defaultValue = [0, 100],
      min = 0,
      max = 100,
      step = 1,
      disabled = false,
      variant = "primary",
      size = "md",
      showValue = false,
      valueFormatter,
      label,
      description,
      error = false,
      errorMessage,
      onChange,
      onChangeEnd,
      className = "",
      id,
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = useState<[number, number]>(defaultValue);
    const trackRef = useRef<HTMLDivElement>(null);
    const activeThumbRef = useRef<0 | 1 | null>(null);
    const [draggingThumb, setDraggingThumb] = useState<0 | 1 | null>(null);

    const autoId = React.useId();
    const rangeId = id ?? autoId;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${rangeId}-desc`;

    const isControlled = value !== undefined;

    useEffect(() => {
      if (!isControlled) {
        setInternalValue(defaultValue);
      }
    }, [defaultValue, isControlled]);

    useEffect(() => {
      if (isControlled && value) {
        setInternalValue(value);
      }
    }, [value, isControlled]);

    const currentValue = isControlled && value ? value : internalValue;
    const clampedValue: [number, number] = [
      Math.min(Math.max(currentValue[0], min), max),
      Math.min(Math.max(currentValue[1], min), max),
    ];

    const valueRef = useRef<[number, number]>(clampedValue);
    valueRef.current = clampedValue;

    const minPercent = ((clampedValue[0] - min) / (max - min)) * 100;
    const maxPercent = ((clampedValue[1] - min) / (max - min)) * 100;
    const formatValue = (val: number) => (valueFormatter ? valueFormatter(val) : val.toString());

    const getValueFromPosition = (clientX: number) => {
      if (!trackRef.current) return 0;
      const rect = trackRef.current.getBoundingClientRect();
      const pct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const val = pct * (max - min) + min;
      return Math.round(val / step) * step;
    };

    const updateValue = (newVal: [number, number]) => {
      const sorted: [number, number] = newVal[0] <= newVal[1] ? newVal : [newVal[1], newVal[0]];
      const clamped: [number, number] = [
        Math.min(max, Math.max(min, sorted[0])),
        Math.min(max, Math.max(min, sorted[1])),
      ];
      if (!isControlled) {
        setInternalValue(clamped);
      }
      onChange?.(clamped);
    };

    const handlePointerDown = (e: React.PointerEvent, thumbIndex: 0 | 1) => {
      if (disabled) return;
      e.stopPropagation();
      e.preventDefault();
      setDraggingThumb(thumbIndex);
      activeThumbRef.current = thumbIndex;

      const onMove = (ev: PointerEvent) => {
        const newVal = getValueFromPosition(ev.clientX);
        const currentVals = valueRef.current;
        if (thumbIndex === 0) {
          updateValue([newVal, currentVals[1]]);
        } else {
          updateValue([currentVals[0], newVal]);
        }
      };

      const onUp = (ev: PointerEvent) => {
        setDraggingThumb(null);
        const finalVal = getValueFromPosition(ev.clientX);
        const currentVals = valueRef.current;
        const nextVal: [number, number] =
          thumbIndex === 0 ? [finalVal, currentVals[1]] : [currentVals[0], finalVal];
        const sorted: [number, number] =
          nextVal[0] <= nextVal[1] ? nextVal : [nextVal[1], nextVal[0]];
        onChangeEnd?.(sorted);
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", onUp);
      };

      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
    };

    const handleTrackClick = (e: React.PointerEvent) => {
      if (disabled) return;
      const clickVal = getValueFromPosition(e.clientX);
      const distMin = Math.abs(clampedValue[0] - clickVal);
      const distMax = Math.abs(clampedValue[1] - clickVal);

      const targetThumb: 0 | 1 = distMin < distMax ? 0 : 1;
      if (targetThumb === 0) {
        updateValue([clickVal, clampedValue[1]]);
        onChangeEnd?.([clickVal, clampedValue[1]]);
      } else {
        updateValue([clampedValue[0], clickVal]);
        onChangeEnd?.([clampedValue[0], clickVal]);
      }
    };

    const handleKeyDown = (e: React.KeyboardEvent, thumbIndex: 0 | 1) => {
      if (disabled) return;
      let val = clampedValue[thumbIndex];
      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          e.preventDefault();
          val = Math.min(max, val + step);
          break;
        case "ArrowLeft":
        case "ArrowDown":
          e.preventDefault();
          val = Math.max(min, val - step);
          break;
        case "Home":
          e.preventDefault();
          val = min;
          break;
        case "End":
          e.preventDefault();
          val = max;
          break;
        case "PageUp":
          e.preventDefault();
          val = Math.min(max, val + (max - min) * 0.1);
          break;
        case "PageDown":
          e.preventDefault();
          val = Math.max(min, val - (max - min) * 0.1);
          break;
        default:
          return;
      }

      const nextVal: [number, number] =
        thumbIndex === 0 ? [val, clampedValue[1]] : [clampedValue[0], val];
      updateValue(nextVal);
      onChangeEnd?.(nextVal[0] <= nextVal[1] ? nextVal : [nextVal[1], nextVal[0]]);
    };

    return (
      <div ref={ref} className={cn(wrapperBase, className)}>
        {/* Labels row */}
        {(label || showValue) && (
          <div className="mb-2 flex items-center justify-between">
            {label && (
              <span
                className={cn(
                  "text-foreground font-medium",
                  sizes[size].text,
                  error && "text-destructive",
                  disabled && "text-muted-foreground"
                )}
              >
                {label}
              </span>
            )}
            {showValue && (
              <span
                className={cn(
                  "text-muted-foreground tabular-nums",
                  sizes[size].text,
                  error && "text-destructive",
                  disabled && "opacity-50"
                )}
              >
                {formatValue(clampedValue[0])} - {formatValue(clampedValue[1])}
              </span>
            )}
          </div>
        )}

        {/* Range rail interaction area */}
        <div
          className={cn(
            "relative flex w-full items-center select-none",
            sizes[size].wrapper,
            disabled && "cursor-not-allowed opacity-50"
          )}
          id={rangeId}
          {...props}
        >
          <div
            ref={trackRef}
            className={cn(
              "bg-secondary relative w-full cursor-pointer rounded-full",
              sizes[size].track
            )}
            onPointerDown={handleTrackClick}
          >
            {/* Range fill */}
            <div
              className={cn("absolute inset-y-0 rounded-full", trackFillVariants[variant])}
              style={{
                left: `${minPercent}%`,
                width: `${maxPercent - minPercent}%`,
              }}
            />

            {/* Min Thumb */}
            <div
              className={cn(
                thumbBase,
                sizes[size].thumb,
                error && "border-destructive",
                draggingThumb === 0 &&
                  "scale-110 shadow-[0_0_0_var(--ring-offset)_hsl(var(--background)),0_0_0_calc(var(--ring-offset)+var(--ring-width))_var(--ring-color)]",
                "rui-focus-ring outline-none"
              )}
              style={{ left: `${minPercent}%` }}
              onPointerDown={e => handlePointerDown(e, 0)}
              onKeyDown={e => handleKeyDown(e, 0)}
              tabIndex={disabled ? -1 : 0}
              role="slider"
              aria-valuemin={min}
              aria-valuemax={clampedValue[1]}
              aria-valuenow={clampedValue[0]}
              aria-disabled={disabled}
              aria-describedby={hasAssistive ? assistiveId : undefined}
            />

            {/* Max Thumb */}
            <div
              className={cn(
                thumbBase,
                sizes[size].thumb,
                error && "border-destructive",
                draggingThumb === 1 &&
                  "scale-110 shadow-[0_0_0_var(--ring-offset)_hsl(var(--background)),0_0_0_calc(var(--ring-offset)+var(--ring-width))_var(--ring-color)]",
                "rui-focus-ring outline-none"
              )}
              style={{ left: `${maxPercent}%` }}
              onPointerDown={e => handlePointerDown(e, 1)}
              onKeyDown={e => handleKeyDown(e, 1)}
              tabIndex={disabled ? -1 : 0}
              role="slider"
              aria-valuemin={clampedValue[0]}
              aria-valuemax={max}
              aria-valuenow={clampedValue[1]}
              aria-disabled={disabled}
              aria-describedby={hasAssistive ? assistiveId : undefined}
            />
          </div>
        </div>

        {/* Assistive text */}
        {hasAssistive && (
          <div id={assistiveId} className="mt-2 px-0.5">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

RangeInput.displayName = "RangeInput";

import React from "react";
import { AiFillStar, AiOutlineStar } from "react-icons/ai";
import { cn, tw } from "@/lib/utils";

export interface RatingProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /**
   * The current rating value
   * @default 0
   */
  value?: number;
  /**
   * The maximum rating value
   * @default 5
   */
  max?: number;
  /**
   * The size of the rating stars
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * The visual style of the rating
   * @default "default"
   */
  variant?: "default" | "filled" | "outline";
  /**
   * Whether the rating is readonly (non-interactive)
   * @default false
   */
  readonly?: boolean;
  /**
   * Whether the rating is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Whether to show the rating value as text
   * @default false
   */
  showValue?: boolean;
  /**
   * Custom label for the rating value
   */
  label?: string;
  /**
   * Callback when rating changes
   */
  onChange?: (value: number) => void;
  /**
   * Callback when rating is hovered
   */
  onHover?: (value: number) => void;
  /**
   * Precision for rating values (e.g., 0.5 for half stars)
   * @default 1
   */
  precision?: 0.5 | 1;
  /**
   * Animation effect on user interaction
   * @default "none"
   */
  animation?: "none" | "scale" | "glow";
  /**
   * Custom icon for empty/unfilled state
   * @default AiOutlineStar
   */
  emptyIcon?: React.ComponentType<{
    size?: number | string;
    className?: string;
    onClick?: () => void;
    onMouseEnter?: () => void;
  }>;
  /**
   * Custom icon for filled state
   * @default AiFillStar
   */
  filledIcon?: React.ComponentType<{
    size?: number | string;
    className?: string;
    onClick?: () => void;
    onMouseEnter?: () => void;
  }>;
  /**
   * Custom color for the rating icons
   * @default uses variant colors
   */
  colorClassName?: string;
}

const base = tw`inline-flex items-center gap-1 select-none`;

const sizes = {
  xs: tw`gap-0.5`,
  sm: tw`gap-1`,
  md: tw`gap-1.5`,
  lg: tw`gap-2`,
  xl: tw`gap-2.5`,
};

const starSizes = {
  xs: 20,
  sm: 26,
  md: 36,
  lg: 40,
  xl: 50,
};

const variants = {
  default: tw`text-border`,
  filled: tw`text-yellow-400`,
  outline: tw`text-muted-foreground/60`,
};

const filledVariants = {
  default: tw`text-yellow-500`,
  filled: tw`text-yellow-500`,
  outline: tw`text-yellow-600`,
};

const hoverVariants = {
  default: tw`text-yellow-400`,
  filled: tw`text-yellow-300`,
  outline: tw`text-yellow-500`,
};

const disabledStyles = tw`pointer-events-none opacity-60`;

const animations = {
  none: tw``,
  scale: tw`transition-transform duration-150 ease-out hover:scale-110`,
  glow: tw`transition-shadow duration-200 ease-out hover:drop-shadow-sm`,
};

export const Rating = React.forwardRef<HTMLDivElement, RatingProps>(
  (
    {
      value = 0,
      max = 5,
      size = "md",
      variant = "default",
      readonly = false,
      disabled = false,
      showValue = false,
      label,
      onChange,
      onHover,
      precision = 1,
      animation = "none",
      emptyIcon: EmptyIcon = AiOutlineStar,
      filledIcon: FilledIcon = AiFillStar,
      colorClassName,
      className = "",
      ...props
    },
    ref
  ) => {
    const [hoverValue, setHoverValue] = React.useState<number | null>(null);
    const [isHovering, setIsHovering] = React.useState(false);

    const displayValue = hoverValue !== null ? hoverValue : value;
    const isInteractive = !readonly && !disabled && !!onChange;

    const handleStarClick = (starValue: number) => {
      if (!isInteractive) return;
      onChange?.(starValue);
    };

    const handleStarHover = (starValue: number) => {
      if (!isInteractive) return;
      setHoverValue(starValue);
      setIsHovering(true);
      onHover?.(starValue);
    };

    const handleMouseLeave = () => {
      setHoverValue(null);
      setIsHovering(false);
    };

    const renderStar = (starIndex: number) => {
      const starValue = starIndex + 1;
      const isFilled = displayValue >= starValue;
      const isPartial = displayValue > starIndex && displayValue < starValue;
      const partialWidth = isPartial ? ((displayValue - starIndex) / 1) * 100 : 0;

      // Determine colors based on state and custom color prop
      const getColorClass = (isFilledState: boolean) => {
        if (colorClassName) {
          return colorClassName;
        }
        return isFilledState
          ? cn(filledVariants[variant], isHovering && hoverVariants[variant])
          : variants[variant];
      };

      if (isPartial) {
        // For partial stars, show both outline and filled with clipping
        return (
          <div key={starIndex} className="relative">
            <EmptyIcon
              size={starSizes[size]}
              className={cn(
                "transition-all duration-200",
                isInteractive && "cursor-pointer",
                getColorClass(false),
                animation !== "none" && animations[animation]
              )}
              onClick={() => handleStarClick(starValue)}
              onMouseEnter={() => handleStarHover(starValue)}
            />
            <div className="absolute inset-0 overflow-hidden" style={{ width: `${partialWidth}%` }}>
              <FilledIcon
                size={starSizes[size]}
                className={cn("transition-colors duration-150", getColorClass(true))}
              />
            </div>
          </div>
        );
      } else if (isFilled) {
        // For fully filled stars, just show the filled star
        return (
          <FilledIcon
            key={starIndex}
            size={starSizes[size]}
            className={cn(
              "transition-colors duration-150",
              isInteractive && "cursor-pointer",
              getColorClass(true),
              isInteractive &&
                !isHovering &&
                hoverValue === null &&
                !colorClassName &&
                "hover:text-yellow-400",
              animation !== "none" && animations[animation]
            )}
            onClick={() => handleStarClick(starValue)}
            onMouseEnter={() => handleStarHover(starValue)}
          />
        );
      } else {
        // For empty stars, show the outline star
        return (
          <EmptyIcon
            key={starIndex}
            size={starSizes[size]}
            className={cn(
              "transition-colors duration-150",
              isInteractive && "cursor-pointer",
              getColorClass(false),
              isInteractive &&
                !isHovering &&
                hoverValue === null &&
                !colorClassName &&
                "hover:text-yellow-400",
              animation !== "none" && animations[animation]
            )}
            onClick={() => handleStarClick(starValue)}
            onMouseEnter={() => handleStarHover(starValue)}
          />
        );
      }
    };

    return (
      <div
        ref={ref}
        className={cn(base, sizes[size], disabled && disabledStyles, className)}
        onMouseLeave={handleMouseLeave}
        role="group"
        aria-label={label || "Rating"}
        {...props}
      >
        <div className="flex items-center">
          {Array.from({ length: max }, (_, index) => renderStar(index))}
        </div>

        {showValue && (
          <span
            className={cn("ml-2 text-sm font-medium", variants[variant], disabled && "opacity-60")}
            aria-live="polite"
          >
            {displayValue.toFixed(precision === 0.5 ? 1 : 0)}/{max}
          </span>
        )}
      </div>
    );
  }
);
Rating.displayName = "Rating";

import { cn, tw } from "@/lib/utils";
import React, { useCallback, useRef, useState } from "react";

export interface ResizableProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onResize"> {
  /**
   * The content to be made resizable
   */
  children: React.ReactNode;
  /**
   * The initial width of the resizable container
   * @default 300
   */
  defaultWidth?: number;
  /**
   * The initial height of the resizable container
   * @default 200
   */
  defaultHeight?: number;
  /**
   * Minimum width constraint
   * @default 100
   */
  minWidth?: number;
  /**
   * Maximum width constraint
   * @default 800
   */
  maxWidth?: number;
  /**
   * Minimum height constraint
   * @default 100
   */
  minHeight?: number;
  /**
   * Maximum height constraint
   * @default 600
   */
  maxHeight?: number;
  /**
   * Direction of resize handles
   * @default "both"
   */
  direction?: "horizontal" | "vertical" | "both";
  /**
   * Enable/disable resize functionality
   * @default true
   */
  resizable?: boolean;
  /**
   * Callback when size changes
   */
  onResize?: (size: { width: number; height: number }) => void;
  /**
   * Callback when resize starts
   */
  onResizeStart?: () => void;
  /**
   * Callback when resize ends
   */
  onResizeEnd?: (size: { width: number; height: number }) => void;
  /**
   * Custom class name for the container
   */
  className?: string;
  /**
   * Custom class name for resize handles
   */
  handleClassName?: string;
  /**
   * Show resize handles
   * @default true
   */
  showHandles?: boolean;
  /**
   * Handle size in pixels
   * @default 2
   */
  handleSize?: number;
  /**
   * Handle color theme
   * @default "default"
   */
  handleColor?: "default" | "primary" | "secondary";
  /**
   * Show corner handle for resizing both dimensions
   * @default true
   */
  showCornerHandle?: boolean;
  /**
   * Corner handle size in pixels (when different from handleSize)
   * @default 8
   */
  cornerHandleSize?: number;
}

const baseContainer = tw`relative inline-block`;
const baseHandle = tw`absolute z-10 bg-primary/60 opacity-50 transition-all select-none hover:bg-primary/80 hover:opacity-80 active:bg-primary`;

const handleColors = {
  default: tw``,
  primary: tw`bg-primary hover:bg-primary/90 active:bg-primary/80`,
  secondary: tw`bg-foreground/60 hover:bg-foreground/80 active:bg-foreground`,
};

export const Resizable = React.forwardRef<HTMLDivElement, ResizableProps>(
  (
    {
      children,
      defaultWidth = 300,
      defaultHeight = 200,
      minWidth = 100,
      maxWidth = 800,
      minHeight = 100,
      maxHeight = 600,
      direction = "both",
      resizable = true,
      onResize,
      onResizeStart,
      onResizeEnd,
      className = "",
      handleClassName = "",
      showHandles = true,
      handleColor = "default",
      handleSize = 2,
      showCornerHandle = true,
      cornerHandleSize = 8,
      style,
      ...props
    },
    ref
  ) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [size, setSize] = useState({
      width: defaultWidth,
      height: defaultHeight,
    });
    const [activeDirection, setActiveDirection] = useState<
      "horizontal" | "vertical" | "both" | null
    >(null);

    React.useImperativeHandle(ref, () => containerRef.current as HTMLDivElement);

    const handleMouseDown = useCallback(
      (direction: "horizontal" | "vertical" | "both") => (e: React.MouseEvent) => {
        e.preventDefault();
        setActiveDirection(direction);
        onResizeStart?.();

        const startX = e.clientX;
        const startY = e.clientY;
        const startWidth = size.width;
        const startHeight = size.height;
        let finalSize = { width: startWidth, height: startHeight };

        const handleMouseMove = (e: MouseEvent) => {
          // This is where the stale closure was causing the issue.
          // The `if (!isResizing)` check is removed because this listener
          // is only active during a drag operation.
          let newWidth = startWidth;
          let newHeight = startHeight;

          if (direction === "horizontal" || direction === "both") {
            newWidth = Math.max(minWidth, Math.min(maxWidth, startWidth + (e.clientX - startX)));
          }

          if (direction === "vertical" || direction === "both") {
            newHeight = Math.max(
              minHeight,
              Math.min(maxHeight, startHeight + (e.clientY - startY))
            );
          }

          const newSize = { width: newWidth, height: newHeight };
          finalSize = newSize;

          requestAnimationFrame(() => {
            setSize(newSize);
            onResize?.(newSize);
          });
        };

        const handleMouseUp = () => {
          setActiveDirection(null);
          onResizeEnd?.(finalSize);
          document.removeEventListener("mousemove", handleMouseMove);
          document.removeEventListener("mouseup", handleMouseUp);
          document.body.style.userSelect = "";
        };

        document.body.style.userSelect = "none";
        document.addEventListener("mousemove", handleMouseMove);
        document.addEventListener("mouseup", handleMouseUp);
      },
      [
        size.width,
        size.height,
        minWidth,
        maxWidth,
        minHeight,
        maxHeight,
        onResize,
        onResizeStart,
        onResizeEnd,
      ]
    );

    const handleKeyDown = useCallback(
      (direction: "horizontal" | "vertical" | "both") => (e: React.KeyboardEvent) => {
        if (!resizable) return;

        const step = 10;
        let newWidth = size.width;
        let newHeight = size.height;

        switch (e.key) {
          case "ArrowRight":
            if (direction === "horizontal" || direction === "both") {
              newWidth = Math.min(maxWidth, size.width + step);
            }
            break;
          case "ArrowLeft":
            if (direction === "horizontal" || direction === "both") {
              newWidth = Math.max(minWidth, size.width - step);
            }
            break;
          case "ArrowDown":
            if (direction === "vertical" || direction === "both") {
              newHeight = Math.min(maxHeight, size.height + step);
            }
            break;
          case "ArrowUp":
            if (direction === "vertical" || direction === "both") {
              newHeight = Math.max(minHeight, size.height - step);
            }
            break;
          default:
            return;
        }

        e.preventDefault();
        const newSize = { width: newWidth, height: newHeight };
        setSize(newSize);
        onResize?.(newSize);
      },
      [resizable, size, minWidth, maxWidth, minHeight, maxHeight, onResize]
    );

    const containerStyle = {
      width: size.width,
      height: size.height,
    };

    return (
      <div
        ref={containerRef}
        className={cn(baseContainer, className)}
        style={{ ...containerStyle, ...style }}
        onMouseDown={e => {
          if (!(e.target as HTMLElement).classList.contains("handle")) {
            if (!showHandles) {
              handleMouseDown("both")(e);
            }
          }
        }}
        {...props}
      >
        {children}

        {showHandles && resizable && (
          <>
            {(direction === "horizontal" || direction === "both") && (
              <div
                className={cn(
                  baseHandle,
                  handleColors[handleColor],
                  handleClassName,
                  "handle",
                  (activeDirection === "horizontal" || activeDirection === "both") &&
                    "bg-primary ring-ring opacity-100 ring-1"
                )}
                style={{
                  top: 0,
                  right: 0,
                  height: "100%",
                  width: `${handleSize}px`,
                  cursor: "ew-resize",
                }}
                onMouseDown={handleMouseDown("horizontal")}
                onKeyDown={handleKeyDown("horizontal")}
                tabIndex={0}
                role="slider"
                aria-label="Resize width"
                aria-valuemin={minWidth}
                aria-valuemax={maxWidth}
                aria-valuenow={size.width}
              />
            )}

            {(direction === "vertical" || direction === "both") && (
              <div
                className={cn(
                  baseHandle,
                  handleColors[handleColor],
                  handleClassName,
                  "handle",
                  (activeDirection === "vertical" || activeDirection === "both") &&
                    "bg-primary ring-ring opacity-100 ring-1"
                )}
                style={{
                  bottom: 0,
                  left: 0,
                  width: "100%",
                  height: `${handleSize}px`,
                  cursor: "ns-resize",
                }}
                onMouseDown={handleMouseDown("vertical")}
                onKeyDown={handleKeyDown("vertical")}
                tabIndex={0}
                role="slider"
                aria-label="Resize height"
                aria-valuemin={minHeight}
                aria-valuemax={maxHeight}
                aria-valuenow={size.height}
              />
            )}

            {showCornerHandle && direction === "both" && (
              <div
                className={cn(
                  baseHandle,
                  handleColors[handleColor],
                  handleClassName,
                  "handle",
                  activeDirection === "both" && "bg-primary ring-ring opacity-100 ring-1"
                )}
                style={{
                  bottom: 0,
                  right: 0,
                  width: `${cornerHandleSize || handleSize}px`,
                  height: `${cornerHandleSize || handleSize}px`,
                  cursor: "nwse-resize",
                  zIndex: 15,
                }}
                onMouseDown={handleMouseDown("both")}
                onKeyDown={handleKeyDown("both")}
                tabIndex={0}
                role="slider"
                aria-label="Resize both dimensions"
                aria-valuemin={Math.min(minWidth, minHeight)}
                aria-valuemax={Math.max(maxWidth, maxHeight)}
                aria-valuenow={Math.max(size.width, size.height)}
              />
            )}
          </>
        )}
      </div>
    );
  }
);

Resizable.displayName = "Resizable";

import React, { useEffect, useRef, useState } from "react";
import { HiOutlineCheck, HiOutlineChevronDown } from "react-icons/hi";
import { cn, tw } from "@/lib/utils";

export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
  icon?: React.ReactNode;
}

export interface SelectProps {
  /**
   * The visual style of the select
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the select
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Control the border radius of the select
   * @default "sm"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Make select take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Preset width of the select wrapper
   * @default "md"
   */
  width?: "sm" | "md" | "lg" | "xl";
  /**
   * Optional left icon - accepts any React element
   */
  startIcon?: React.ReactNode;
  /**
   * Optional label text displayed above the select
   */
  label?: string;
  /**
   * Optional helper/description text displayed below the select
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the select
   */
  errorMessage?: string;
  /**
   * Array of options for the select
   */
  options: SelectOption[];
  /**
   * Placeholder text when no option is selected
   */
  placeholder?: string;
  /**
   * Selected value
   */
  value?: string;
  /**
   * Default selected value
   */
  defaultValue?: string;
  /**
   * Callback when value changes
   */
  onValueChange?: (value: string) => void;
  /**
   * Whether the select is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the select element
   */
  id?: string;
  /**
   * Name attribute for the select
   */
  name?: string;
}

const wrapperBase = tw`relative inline-flex w-full flex-col`;
const fieldBase = tw`rui-field-focus relative inline-flex items-center border bg-background text-foreground transition-colors duration-150`;

const variants = {
  primary: tw`border-input bg-background`,
  secondary: tw`border-input bg-muted`,
};

// IMPORTANT: Heights must match TextInput's size scale exactly.
// xs=h-8 sm=h-9 md=h-10 lg=h-12 xl=h-14
const sizes = {
  xs: { container: tw`h-7`, text: tw`text-xs`, padX: "px-2", padY: "py-1", gap: "gap-1" },
  sm: { container: tw`h-8`, text: tw`text-xs`, padX: "px-2.5", padY: "py-1.5", gap: "gap-1.5" },
  md: { container: tw`h-9`, text: tw`text-sm`, padX: "px-3", padY: "py-1.5", gap: "gap-2" },
  lg: { container: tw`h-10`, text: tw`text-sm`, padX: "px-3.5", padY: "py-2", gap: "gap-2" },
  xl: { container: tw`h-12`, text: tw`text-base`, padX: "px-4", padY: "py-2.5", gap: "gap-2.5" },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const labelSizes = {
  xs: tw`text-xs`,
  sm: tw`text-sm`,
  md: tw`text-sm`,
  lg: tw`text-base`,
  xl: tw`text-base`,
};

const widths = {
  sm: tw`w-64`,
  md: tw`w-80`,
  lg: tw`w-96`,
  xl: tw`w-[30rem]`,
} as const;

const dropdownBase = tw`absolute top-full left-0 z-50 mt-1.5 max-h-60 w-full overflow-auto border border-border bg-popover shadow-lg`;
const optionBase = tw`flex w-full cursor-pointer items-center justify-between gap-2 px-3 py-2 text-left text-sm text-popover-foreground hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:outline-none disabled:cursor-not-allowed disabled:opacity-50`;
const optionAnimated = tw`transition-colors duration-150`;
const optionSelected = tw`bg-accent text-accent-foreground`;
const optionDisabled = tw`cursor-not-allowed opacity-50`;
const chevronAnimated = tw`transition-transform duration-200`;

const ChevronDownIcon = ({ isOpen, animated }: { isOpen: boolean; animated: boolean }) => (
  <HiOutlineChevronDown
    className={cn(
      "text-muted-foreground h-4 w-4",
      animated && chevronAnimated,
      isOpen && "rotate-180"
    )}
  />
);

export const Select = React.forwardRef<HTMLButtonElement, SelectProps>(
  (
    {
      variant = "primary",
      size = "md",
      className = "",
      fullWidth = false,
      width = "md",
      rounded = "sm",
      animation = true,
      error = false,
      disabled = false,
      startIcon,
      label,
      description,
      errorMessage,
      options,
      placeholder = "Select...",
      value,
      defaultValue,
      onValueChange,
      id,
      name,
      ...props
    },
    ref
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [selectedValue, setSelectedValue] = useState(value || defaultValue || "");
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const [searchBuffer, setSearchBuffer] = useState("");
    const searchTimeout = useRef<NodeJS.Timeout | null>(null);
    const lastSearchedIndex = useRef<number>(-1);
    const triggerRef = useRef<HTMLButtonElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const autoId = React.useId();
    const selectId = id ?? autoId;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${selectId}-desc`;
    const listboxId = `${selectId}-listbox`;

    useEffect(() => {
      if (value !== undefined) setSelectedValue(value);
    }, [value]);

    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          dropdownRef.current &&
          !dropdownRef.current.contains(event.target as Node) &&
          triggerRef.current &&
          !triggerRef.current.contains(event.target as Node)
        ) {
          setIsOpen(false);
          setFocusedIndex(-1);
        }
      };
      if (isOpen) {
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
      }
    }, [isOpen]);

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (disabled) return;

      if (event.key.length === 1 && event.key.match(/^[^\s]$/)) {
        const char = event.key.toLowerCase();
        let newBuffer = searchBuffer + char;
        if (searchTimeout.current) clearTimeout(searchTimeout.current);
        searchTimeout.current = setTimeout(() => setSearchBuffer(""), 500);

        const matches = options
          .map((opt, idx) => ({ idx, opt }))
          .filter(({ opt }) => !opt.disabled && opt.label.toLowerCase().startsWith(newBuffer));

        if (matches.length === 0 && newBuffer.length > 1) {
          newBuffer = char;
          setSearchBuffer(newBuffer);
          const fallbackMatches = options
            .map((opt, idx) => ({ idx, opt }))
            .filter(({ opt }) => !opt.disabled && opt.label.toLowerCase().startsWith(newBuffer));
          if (fallbackMatches.length > 0) {
            lastSearchedIndex.current = fallbackMatches[0].idx;
            setFocusedIndex(fallbackMatches[0].idx);
            scrollToOption(fallbackMatches[0].idx);
          }
          return;
        }

        setSearchBuffer(newBuffer);
        if (matches.length > 0) {
          let nextIdx = matches[0].idx;
          if (
            matches.length > 1 &&
            lastSearchedIndex.current !== -1 &&
            matches.some(({ idx }) => idx === lastSearchedIndex.current)
          ) {
            const currentIdx = matches.findIndex(({ idx }) => idx === lastSearchedIndex.current);
            nextIdx = matches[(currentIdx + 1) % matches.length].idx;
          }
          lastSearchedIndex.current = nextIdx;
          setFocusedIndex(nextIdx);
          scrollToOption(nextIdx);
        }
        return;
      }

      switch (event.key) {
        case "Enter":
        case " ":
          event.preventDefault();
          if (!isOpen) {
            setIsOpen(true);
            setFocusedIndex(
              selectedValue ? options.findIndex(opt => opt.value === selectedValue) : 0
            );
            setSearchBuffer("");
            lastSearchedIndex.current = -1;
          } else if (focusedIndex >= 0) {
            handleOptionSelect(options[focusedIndex].value);
          }
          break;
        case "Escape":
          setIsOpen(false);
          setFocusedIndex(-1);
          setSearchBuffer("");
          lastSearchedIndex.current = -1;
          triggerRef.current?.focus();
          break;
        case "ArrowDown": {
          event.preventDefault();
          if (!isOpen) {
            setIsOpen(true);
            setFocusedIndex(0);
            setSearchBuffer("");
            lastSearchedIndex.current = -1;
          } else {
            const nextIndex = Math.min(focusedIndex + 1, options.length - 1);
            setFocusedIndex(nextIndex);
            scrollToOption(nextIndex);
          }
          break;
        }
        case "ArrowUp": {
          event.preventDefault();
          if (isOpen) {
            const prevIndex = Math.max(focusedIndex - 1, 0);
            setFocusedIndex(prevIndex);
            scrollToOption(prevIndex);
          }
          break;
        }
        case "Tab":
          setIsOpen(false);
          setFocusedIndex(-1);
          setSearchBuffer("");
          lastSearchedIndex.current = -1;
          break;
      }
    };

    const scrollToOption = (idx: number) => {
      if (!isOpen) return;
      const dropdown = dropdownRef.current;
      if (dropdown) {
        const optionEl = dropdown.querySelectorAll('button[role="option"]')[idx] as HTMLElement;
        optionEl?.scrollIntoView({ block: "nearest" });
      }
    };

    const handleOptionSelect = (optionValue: string) => {
      const option = options.find(opt => opt.value === optionValue);
      if (option?.disabled) return;
      setSelectedValue(optionValue);
      setIsOpen(false);
      setFocusedIndex(-1);
      onValueChange?.(optionValue);
      triggerRef.current?.focus();
    };

    const selectedOption = options.find(opt => opt.value === selectedValue);
    const dropdownRadius = rounded === "full" ? tw`rounded-xl` : roundedOptions[rounded];

    return (
      <div className={cn(wrapperBase, fullWidth ? "w-full" : (widths[width] ?? "w-auto"))}>
        <input type="hidden" name={name} value={selectedValue} />

        {label && (
          <label
            htmlFor={selectId}
            className={cn(
              "text-foreground mb-1 font-medium",
              labelSizes[size],
              error && "text-destructive"
            )}
          >
            {label}
          </label>
        )}

        <div
          className={cn(
            fieldBase,
            variants[variant],
            sizes[size].container,
            roundedOptions[rounded],
            sizes[size].padX,
            sizes[size].gap,
            error && "rui-field-error border-destructive",
            fullWidth && "w-full",
            disabled && "cursor-not-allowed opacity-50",
            className
          )}
        >
          {(selectedOption?.icon || startIcon) && (
            <span className="text-muted-foreground flex shrink-0 items-center">
              {selectedOption?.icon ? selectedOption.icon : startIcon}
            </span>
          )}
          <button
            ref={ref || triggerRef}
            type="button"
            className={cn(
              "min-w-0 flex-1 truncate bg-transparent text-left outline-none",
              sizes[size].text
            )}
            onClick={() => !disabled && setIsOpen(!isOpen)}
            onKeyDown={handleKeyDown}
            disabled={disabled}
            aria-expanded={isOpen}
            aria-haspopup="listbox"
            aria-controls={listboxId}
            aria-describedby={hasAssistive ? assistiveId : undefined}
            id={selectId}
            {...props}
          >
            {selectedOption ? (
              <span className="text-foreground truncate">{selectedOption.label}</span>
            ) : (
              <span className="text-muted-foreground truncate">{placeholder}</span>
            )}
          </button>
          <span className="flex shrink-0 items-center">
            <ChevronDownIcon isOpen={isOpen} animated={animation} />
          </span>

          {isOpen && (
            <div
              ref={dropdownRef}
              id={listboxId}
              className={cn(
                dropdownBase,
                dropdownRadius,
                animation &&
                  "animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 duration-150 ease-out"
              )}
              role="listbox"
            >
              {options.map((option, index) => {
                const isSelected = selectedValue === option.value;
                return (
                  <button
                    key={option.value}
                    type="button"
                    className={cn(
                      optionBase,
                      animation && optionAnimated,
                      isSelected && optionSelected,
                      option.disabled && optionDisabled,
                      index === focusedIndex && "bg-accent text-accent-foreground",
                      sizes[size].text,
                      sizes[size].padY
                    )}
                    onClick={() => handleOptionSelect(option.value)}
                    disabled={option.disabled}
                    role="option"
                    aria-selected={isSelected}
                  >
                    {option.icon && (
                      <span className="text-muted-foreground mr-2 flex items-center">
                        {option.icon}
                      </span>
                    )}
                    <span className="flex-1 truncate">{option.label}</span>
                    <HiOutlineCheck
                      className={cn(
                        "text-primary h-5 w-5 shrink-0",
                        isSelected ? "opacity-100" : "opacity-0"
                      )}
                      aria-hidden={!isSelected}
                      focusable="false"
                    />
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {hasAssistive && (
          <div id={assistiveId} className="mt-1 min-h-[1rem] px-1">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

Select.displayName = "Select";

import React from "react";
import { cn, tw } from "@/lib/utils";

export interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The shape of the skeleton
   * @default "rectangle"
   */
  variant?: "rectangle" | "circle" | "text";
  /**
   * The size of the skeleton
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * The width of the skeleton (can be a number in pixels or a string like "100%")
   * @default "auto"
   */
  width?: number | string;
  /**
   * The height of the skeleton (can be a number in pixels or a string like "100%")
   * @default "auto"
   */
  height?: number | string;
  /**
   * Animation type for the skeleton
   * @default "shimmer"
   */
  animation?: "shimmer" | "wave" | "fade" | "pulse" | "none";
  /**
   * Number of skeleton lines for text variant
   * @default 1
   */
  lines?: number;
  /**
   * Whether to show the skeleton or not
   * @default true
   */
  show?: boolean;
}

const variants = {
  rectangle: tw`rounded-md`,
  circle: tw`rounded-full`,
  text: tw`rounded-sm`,
};

const sizes = {
  xs: tw`h-2`,
  sm: tw`h-3`,
  md: tw`h-4`,
  lg: tw`h-5`,
  xl: tw`h-6`,
};

const animations = {
  shimmer: tw`relative overflow-hidden before:absolute before:inset-0 before:z-10 before:w-full before:animate-[skeleton-shimmer_2s_ease-in-out_infinite] before:bg-gradient-to-r before:from-transparent before:via-white/80 before:to-transparent`,
  wave: tw`relative overflow-hidden before:absolute before:inset-0 before:z-10 before:animate-[skeleton-wave_1.5s_ease-in-out_infinite] before:bg-gradient-to-r before:from-transparent before:via-white/60 before:to-transparent`,
  fade: tw`animate-[skeleton-fade_1.5s_ease-in-out_infinite]`,
  pulse: tw`animate-pulse`,
  none: tw``,
};

const textLineSpacing = tw`mb-2 last:mb-0`;

export const Skeleton = React.forwardRef<HTMLDivElement, SkeletonProps>(
  (
    {
      variant = "rectangle",
      size = "md",
      width = "auto",
      height = "auto",
      animation = "shimmer",
      lines = 1,
      show = true,
      className = "",
      style,
      ...props
    },
    ref
  ) => {
    if (!show) return null;

    const skeletonStyle: React.CSSProperties = {
      width: typeof width === "number" ? `${width}px` : width,
      height: typeof height === "number" ? `${height}px` : height,
      ...style,
    };

    if (variant === "text") {
      return (
        <div ref={ref} className={cn("flex flex-col", className)} {...props}>
          {Array.from({ length: lines }, (_, index) => (
            <div
              key={index}
              className={cn(
                "bg-muted rounded-sm",
                sizes[size],
                animations[animation],
                textLineSpacing,
                // Make last line shorter for more realistic text appearance
                index === lines - 1 && lines > 1 && "w-3/4"
              )}
              style={{
                width: index === lines - 1 && lines > 1 ? "75%" : skeletonStyle.width,
                ...style,
              }}
            />
          ))}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn(
          "bg-muted relative overflow-hidden",
          variants[variant],
          variant !== "circle" && sizes[size],
          animations[animation],
          className
        )}
        style={skeletonStyle}
        {...props}
      />
    );
  }
);

Skeleton.displayName = "Skeleton";

import React, { useEffect, useRef, useState } from "react";
import { cn, tw } from "@/lib/utils";

export interface SliderProps {
  /**
   * The current value of the slider
   */
  value?: number;
  /**
   * Default value for uncontrolled slider
   * @default 0
   */
  defaultValue?: number;
  /**
   * Minimum value
   * @default 0
   */
  min?: number;
  /**
   * Maximum value
   * @default 100
   */
  max?: number;
  /**
   * Step increment
   * @default 1
   */
  step?: number;
  /**
   * Whether the slider is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * The visual style of the slider
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the slider
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Show value label
   * @default false
   */
  showValue?: boolean;
  /**
   * Custom value formatter
   */
  valueFormatter?: (value: number) => string;
  /**
   * Optional label text displayed above the slider
   */
  label?: string;
  /**
   * Optional helper/description text displayed below the slider
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the slider
   */
  errorMessage?: string;
  /**
   * Callback when slider value changes
   */
  onChange?: (value: number) => void;
  /**
   * Callback when slider value change ends
   */
  onChangeEnd?: (value: number) => void;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the slider element
   */
  id?: string;
}

// rui-focus-ring: keyboard-only :focus-visible ring via .rui-focus-ring CSS class.
// The slider wrapper needs an explicit height equal to the thumb so the
// absolute-positioned track has a proper containing block.
const wrapperBase = tw`inline-flex w-full flex-col`;

// Per-size table: wrapper height must be >= thumb height so the absolute
// track center-aligns properly. Track height defines the rail.
const sizes = {
  sm: { wrapper: tw`h-4 min-w-[120px]`, track: tw`h-1`, thumb: tw`h-3 w-3`, text: tw`text-xs` },
  md: { wrapper: tw`h-5 min-w-[160px]`, track: tw`h-2`, thumb: tw`h-4 w-4`, text: tw`text-sm` },
  lg: { wrapper: tw`h-6 min-w-[200px]`, track: tw`h-3`, thumb: tw`h-5 w-5`, text: tw`text-base` },
} as const;

const trackFillVariants = {
  primary: tw`bg-primary`,
  secondary: tw`bg-secondary-foreground`,
};

// Thumb: bg-background with border so it reads on any surface
const thumbBase = tw`
  absolute top-1/2 -translate-x-1/2 -translate-y-1/2
  block cursor-pointer rounded-full
  border border-border bg-background
  shadow-sm transition-[transform,shadow,border-color,background-color] duration-150 ease-in-out
  hover:scale-110 hover:shadow-md
  disabled:cursor-not-allowed disabled:opacity-50 disabled:shadow-none
`;

const labelBase = tw`mb-1.5 font-medium text-foreground`;

export const Slider = React.forwardRef<HTMLDivElement, SliderProps>(
  (
    {
      value,
      defaultValue = 0,
      min = 0,
      max = 100,
      step = 1,
      disabled = false,
      variant = "primary",
      size = "md",
      showValue = false,
      valueFormatter,
      label,
      description,
      error = false,
      errorMessage,
      onChange,
      onChangeEnd,
      className = "",
      id,
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = useState(defaultValue);
    const trackRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const autoId = React.useId();
    const sliderId = id ?? autoId;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${sliderId}-desc`;

    const isControlled = value !== undefined;

    useEffect(() => {
      if (!isControlled) setInternalValue(defaultValue);
    }, [defaultValue, isControlled]);

    useEffect(() => {
      if (isControlled) setInternalValue(value);
    }, [value, isControlled]);

    const currentValue = isControlled && value !== undefined ? value : internalValue;
    const clampedValue = Math.min(Math.max(currentValue, min), max);
    const percentage = ((clampedValue - min) / (max - min)) * 100;
    const formatValue = (val: number) => (valueFormatter ? valueFormatter(val) : val.toString());

    const getValueFromPosition = (clientX: number) => {
      if (!trackRef.current) return clampedValue;
      const rect = trackRef.current.getBoundingClientRect();
      const pct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      return Math.min(max, Math.max(min, Math.round((pct * (max - min) + min) / step) * step));
    };

    const updateValue = (newVal: number) => {
      const clamped = Math.min(max, Math.max(min, newVal));
      if (!isControlled) setInternalValue(clamped);
      onChange?.(clamped);
    };

    const handlePointerDown = (e: React.PointerEvent) => {
      if (disabled) return;
      e.preventDefault();
      setIsDragging(true);
      let current = getValueFromPosition(e.clientX);
      updateValue(current);

      const onMove = (ev: PointerEvent) => {
        current = getValueFromPosition(ev.clientX);
        updateValue(current);
      };
      const onUp = () => {
        setIsDragging(false);
        onChangeEnd?.(current);
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", onUp);
      };
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (disabled) return;
      let next = clampedValue;
      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          e.preventDefault();
          next = Math.min(max, clampedValue + step);
          break;
        case "ArrowLeft":
        case "ArrowDown":
          e.preventDefault();
          next = Math.max(min, clampedValue - step);
          break;
        case "Home":
          e.preventDefault();
          next = min;
          break;
        case "End":
          e.preventDefault();
          next = max;
          break;
        case "PageUp":
          e.preventDefault();
          next = Math.min(max, clampedValue + (max - min) * 0.1);
          break;
        case "PageDown":
          e.preventDefault();
          next = Math.max(min, clampedValue - (max - min) * 0.1);
          break;
        default:
          return;
      }
      updateValue(next);
      onChangeEnd?.(next);
    };

    const thumbClasses = cn(
      thumbBase,
      sizes[size].thumb,
      error && "border-destructive",
      isDragging &&
        "scale-110 shadow-[0_0_0_var(--ring-offset)_hsl(var(--background)),0_0_0_calc(var(--ring-offset)+var(--ring-width))_var(--ring-color)]"
    );

    return (
      <div ref={ref} className={cn(wrapperBase, className)}>
        {/* Label row */}
        {(label || showValue) && (
          <div className="mb-2 flex items-center justify-between">
            {label && (
              <label
                htmlFor={sliderId}
                className={cn(
                  labelBase,
                  sizes[size].text,
                  error && "text-destructive",
                  disabled && "text-muted-foreground"
                )}
              >
                {label}
              </label>
            )}
            {showValue && (
              <span
                className={cn(
                  "text-muted-foreground tabular-nums",
                  sizes[size].text,
                  error && "text-destructive"
                )}
              >
                {formatValue(clampedValue)}
              </span>
            )}
          </div>
        )}

        {/*
          Slider interaction area.
          - Has an explicit height (= thumb height) so the absolute track has a
            proper containing block and `top-1/2` works correctly.
          - `flex items-center` centers the track rail within the wrapper.
          - rui-focus-ring handles :focus-visible ring for keyboard nav.
        */}
        <div
          className={cn(
            "rui-focus-ring relative flex w-full cursor-pointer items-center outline-none",
            sizes[size].wrapper,
            disabled && "cursor-not-allowed opacity-50"
          )}
          onPointerDown={handlePointerDown}
          onKeyDown={handleKeyDown}
          tabIndex={disabled ? -1 : 0}
          role="slider"
          aria-valuemin={min}
          aria-valuemax={max}
          aria-valuenow={clampedValue}
          aria-disabled={disabled}
          aria-describedby={hasAssistive ? assistiveId : undefined}
          id={sliderId}
          {...props}
        >
          {/* Track rail — full width, relative so fill + thumb are positioned within it */}
          <div
            ref={trackRef}
            className={cn("bg-secondary relative w-full rounded-full", sizes[size].track)}
          >
            {/* Filled portion */}
            <div
              className={cn("absolute inset-y-0 left-0 rounded-full", trackFillVariants[variant])}
              style={{ width: `${percentage}%` }}
            />
            {/* Thumb */}
            <div className={thumbClasses} style={{ left: `${percentage}%` }} />
          </div>
        </div>

        {/* Assistive text */}
        {hasAssistive && (
          <div id={assistiveId} className="mt-2 px-0.5">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

Slider.displayName = "Slider";

import { cn, tw } from "@/lib/utils";
import React, { useCallback, useEffect, useState } from "react";
import { FaGripVertical } from "react-icons/fa";

export interface SortableListProps<T = unknown>
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /**
   * Array of items to display in the sortable list
   */
  items: T[];
  /**
   * Function to render each item. Receives the item, its index, and drag state
   */
  renderItem: (item: T, index: number, isDragging: boolean) => React.ReactNode;
  /**
   * Callback when items are reordered
   */
  onReorder?: (items: T[], fromIndex: number, toIndex: number) => void;
  /**
   * Callback when the order changes (items array is updated)
   */
  onChange?: (items: T[]) => void;
  /**
   * Unique key extractor for items (used for React keys and drag identification)
   */
  getItemKey?: (item: T, index: number) => string;
  /**
   * Whether the list is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Direction of sorting
   * @default "vertical"
   */
  direction?: "vertical" | "horizontal";
  /**
   * Custom drag handle renderer. If not provided, the entire item is draggable
   */
  renderDragHandle?: (item: T, index: number) => React.ReactNode;
  /**
   * Animation duration for reorder transitions
   * @default 200
   */
  animationDuration?: number;
  /**
   * Whether to show real-time preview of changes during drag
   * @default true
   */
  showDragPreview?: boolean;
}

export interface SortableItemProps<T = unknown>
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    "children" | "onDragStart" | "onDragEnd" | "onDrop"
  > {
  /**
   * The item data
   */
  item: T;
  /**
   * Item index in the list
   */
  index: number;
  /**
   * Whether the item is currently being dragged
   */
  isDragging: boolean;
  /**
   * Whether the item is being dragged over
   */
  isDragOver: boolean;
  /**
   * Callback to start dragging
   */
  onDragStart: (index: number) => void;
  /**
   * Callback when drag ends
   */
  onDragEnd: () => void;
  /**
   * Callback when item is dropped
   */
  onDrop: (fromIndex: number, toIndex: number) => void;
  /**
   * Direction of sorting
   */
  direction: "vertical" | "horizontal";
  /**
   * Whether the list is disabled
   */
  disabled: boolean;
  /**
   * Custom drag handle renderer
   */
  renderDragHandle?: (item: T, index: number) => React.ReactNode;
  /**
   * Animation duration
   */
  animationDuration: number;
  /**
   * Children renderer
   */
  children: (item: T, index: number, isDragging: boolean) => React.ReactNode;
}

const baseList = tw`relative w-full gap-3 select-none`;

const baseItem = tw`relative cursor-move rounded-lg border border-border bg-card shadow-sm transition-all duration-200 ease-in-out hover:border-input hover:shadow-md rui-focus-ring focus-visible:outline-none`;

const draggingItem = tw`z-50 scale-105 rotate-1 border-primary/40 bg-primary/5 shadow-xl`;

const dragOverItem = tw`scale-102 bg-accent shadow-lg`;

const disabledItem = tw`cursor-not-allowed border-border/50 bg-muted opacity-60 hover:border-border/50 hover:shadow-none`;

const dragHandle = tw`flex cursor-grab items-center justify-center rounded-sm text-muted-foreground transition-all duration-200 active:cursor-grabbing disabled:cursor-not-allowed disabled:opacity-50`;

const dragIndicator = tw`pointer-events-none absolute inset-0 rounded-lg border-2 border-primary/40 bg-gradient-to-r from-primary/5 to-primary/10 opacity-0 transition-all duration-200`;

const dropZoneIndicator = tw`pointer-events-none h-1 rounded-full bg-primary opacity-0 transition-all duration-200`;

const keyboardHint = tw`sr-only`;

// Default drag handle icon using react-icons
const DefaultDragHandle: React.FC<{ className?: string }> = ({ className }) => (
  <FaGripVertical className={className} />
);

export const SortableItem = React.forwardRef<HTMLDivElement, SortableItemProps>(
  <T,>(
    {
      item,
      index,
      isDragging,
      isDragOver,
      onDragStart,
      onDragEnd,
      onDrop,
      direction,
      disabled,
      renderDragHandle,
      animationDuration,
      children,
      className,
      style,
      ...props
    }: SortableItemProps<T>,
    ref: React.ForwardedRef<HTMLDivElement>
  ) => {
    const itemRef = React.useRef<HTMLDivElement | null>(null);
    const dragHandleRef = React.useRef<HTMLButtonElement | null>(null);

    // Combine forwarded ref and local ref
    React.useImperativeHandle(ref, () => itemRef.current as HTMLDivElement);

    const handleDragStart = useCallback(
      (e: React.DragEvent) => {
        if (disabled) return;

        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/plain", index.toString());

        // Add drag image if available
        if (itemRef.current) {
          const rect = itemRef.current.getBoundingClientRect();
          const dragImage = new Image();
          dragImage.src =
            "data:image/svg+xml;base64," +
            btoa(`
                        <svg width="${rect.width}" height="${rect.height}" xmlns="http://www.w3.org/2000/svg">
                            <defs>
                                <linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
                                    <stop offset="0%" style="stop-color:#3b82f6;stop-opacity:0.1" />
                                    <stop offset="100%" style="stop-color:#1d4ed8;stop-opacity:0.2" />
                                </linearGradient>
                            </defs>
                            <rect width="100%" height="100%" fill="url(#grad)" stroke="#3b82f6" stroke-width="2" stroke-dasharray="6,4" rx="8"/>
                            <text x="50%" y="50%" text-anchor="middle" dy=".3em" fill="#1e40af" font-family="system-ui, -apple-system, sans-serif" font-size="14" font-weight="600">↕ Move</text>
                        </svg>
                    `);
          e.dataTransfer.setDragImage(dragImage, rect.width / 2, rect.height / 2);
        }

        onDragStart(index);
      },
      [disabled, index, onDragStart]
    );

    const handleDragEnd = useCallback(() => {
      onDragEnd();
      // Add a subtle success animation
      if (itemRef.current) {
        itemRef.current.style.transform = "scale(1.02)";
        setTimeout(() => {
          if (itemRef.current) {
            itemRef.current.style.transform = "";
          }
        }, 150);
      }
    }, [onDragEnd]);

    const handleDragOver = useCallback(
      (e: React.DragEvent) => {
        if (disabled) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
      },
      [disabled]
    );

    const handleDrop = useCallback(
      (e: React.DragEvent) => {
        if (disabled) return;
        e.preventDefault();

        const fromIndex = parseInt(e.dataTransfer.getData("text/plain"), 10);
        if (fromIndex !== index) {
          onDrop(fromIndex, index);
        }
      },
      [disabled, index, onDrop]
    );

    const handleKeyDown = useCallback(
      (e: React.KeyboardEvent) => {
        if (disabled) return;

        switch (e.key) {
          case "ArrowUp":
            e.preventDefault();
            if (direction === "vertical" && index > 0) {
              onDrop(index, index - 1);
            }
            break;
          case "ArrowDown":
            e.preventDefault();
            if (
              direction === "vertical" &&
              index < (itemRef.current?.parentElement?.children.length || 0) - 1
            ) {
              onDrop(index, index + 1);
            }
            break;
          case "ArrowLeft":
            e.preventDefault();
            if (direction === "horizontal" && index > 0) {
              onDrop(index, index - 1);
            }
            break;
          case "ArrowRight":
            e.preventDefault();
            if (
              direction === "horizontal" &&
              index < (itemRef.current?.parentElement?.children.length || 0) - 1
            ) {
              onDrop(index, index + 1);
            }
            break;
          case "Home":
            e.preventDefault();
            if (index > 0) {
              onDrop(index, 0);
            }
            break;
          case "End": {
            e.preventDefault();
            const totalItems = itemRef.current?.parentElement?.children.length || 0;
            if (index < totalItems - 1) {
              onDrop(index, totalItems - 1);
            }
            break;
          }
          case " ":
            e.preventDefault();
            // Focus the drag handle for better accessibility
            dragHandleRef.current?.focus();
            break;
        }
      },
      [disabled, direction, index, onDrop]
    );

    const dragHandleElement = renderDragHandle ? (
      renderDragHandle(item, index)
    ) : (
      <button
        className={cn(
          dragHandle,
          !isDragging && "hover:bg-accent hover:text-accent-foreground",
          disabled && "cursor-not-allowed opacity-50"
        )}
        ref={dragHandleRef}
        aria-label="Drag to reorder"
        type="button"
        disabled={disabled}
      >
        <DefaultDragHandle />
      </button>
    );

    return (
      <div
        ref={itemRef}
        className={cn(
          baseItem,
          isDragging && draggingItem,
          isDragOver && dragOverItem,
          disabled && disabledItem,
          className
        )}
        style={{
          ...style,
          transitionDuration: `${animationDuration}ms`,
        }}
        draggable={!disabled}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        onKeyDown={handleKeyDown}
        tabIndex={disabled ? -1 : 0}
        role="listitem"
        aria-label={`Item ${index + 1} of ${itemRef.current?.parentElement?.children.length || 1}`}
        aria-describedby={`sortable-item-${index}-hint`}
        aria-grabbed={isDragging ? "true" : "false"}
        {...props}
      >
        {isDragOver && (
          <div
            className={dragIndicator}
            style={{
              opacity: isDragOver ? 1 : 0,
            }}
          />
        )}

        {/* Subtle border animation for drag over state */}
        {isDragOver && (
          <div className="border-primary/40 pointer-events-none absolute inset-0 animate-pulse rounded-lg border-2" />
        )}

        <div className="flex w-full items-center gap-4 p-3">
          {!disabled && (
            <div className="flex shrink-0 items-center self-start pt-1">{dragHandleElement}</div>
          )}
          <div className="min-w-0 flex-1">{children(item, index, isDragging)}</div>
        </div>

        <div id={`sortable-item-${index}-hint`} className={keyboardHint}>
          Press arrow keys to reorder, Home/End to jump to start/end, Space to grab item
        </div>
      </div>
    );
  }
);

SortableItem.displayName = "SortableItem";

export const SortableList = React.forwardRef<HTMLDivElement, SortableListProps>(
  <T,>(
    {
      items,
      renderItem,
      onReorder,
      onChange,
      getItemKey = (item: T, index: number) => `item-${index}`,
      disabled = false,
      direction = "vertical",
      renderDragHandle,
      animationDuration = 200,
      showDragPreview = true,
      className,
      style,
      ...props
    }: SortableListProps<T>,
    ref: React.ForwardedRef<HTMLDivElement>
  ) => {
    const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
    const [localItems, setLocalItems] = useState<T[]>(items);
    const [tempItems, setTempItems] = useState<T[]>(items);
    const listRef = React.useRef<HTMLDivElement | null>(null);

    // Combine forwarded ref and local ref
    React.useImperativeHandle(ref, () => listRef.current as HTMLDivElement);

    // Update temp items for drag preview (only when enabled)
    useEffect(() => {
      if (showDragPreview && draggedIndex !== null && dragOverIndex !== null) {
        // Always update tempItems when dragging, regardless of position
        const newTempItems = [...localItems];
        const [movedItem] = newTempItems.splice(draggedIndex, 1);
        newTempItems.splice(dragOverIndex, 0, movedItem);
        setTempItems(newTempItems);
      } else {
        setTempItems(localItems);
      }
    }, [draggedIndex, dragOverIndex, localItems, showDragPreview]);

    const handleDragStart = useCallback((index: number) => {
      setDraggedIndex(index);
    }, []);

    const handleDragEnd = useCallback(() => {
      setDraggedIndex(null);
      setDragOverIndex(null);
    }, []);

    const handleDragOver = useCallback(
      (index: number) => {
        if (showDragPreview) {
          // When preview is enabled, set dragOverIndex to the target position
          setDragOverIndex(index);
        } else {
          setDragOverIndex(index);
        }
      },
      [showDragPreview]
    );

    const itemsToRender = showDragPreview && draggedIndex !== null ? tempItems : localItems;

    const handleDrop = useCallback(
      (fromIndex: number, toIndex: number) => {
        if (fromIndex === toIndex) return;

        // When preview is enabled, toIndex is the visual position
        // We need to map it back to the original position
        let actualToIndex = toIndex;
        if (showDragPreview && draggedIndex !== null) {
          // Find the original index of the item at the visual drop position
          const itemAtDropPosition = itemsToRender[toIndex];
          actualToIndex = localItems.findIndex(item => item === itemAtDropPosition);
        }

        const newItems = [...localItems];
        const [movedItem] = newItems.splice(fromIndex, 1);
        newItems.splice(actualToIndex, 0, movedItem);

        setLocalItems(newItems);
        onReorder?.(newItems, fromIndex, actualToIndex);
        onChange?.(newItems);
        setDraggedIndex(null);
        setDragOverIndex(null);
      },
      [localItems, onReorder, onChange, showDragPreview, draggedIndex, itemsToRender]
    );

    const handleItemDragOver = useCallback(
      (visualIndex: number, isAfterItem = false) =>
        (e: React.DragEvent) => {
          if (disabled) return;
          e.preventDefault();

          // If hovering over the area after an item, the insertion point is visualIndex + 1
          const insertionIndex = isAfterItem ? visualIndex + 1 : visualIndex;
          handleDragOver(insertionIndex);
        },
      [disabled, handleDragOver]
    );

    return (
      <div
        ref={listRef}
        className={cn(
          baseList,
          direction === "horizontal" && "flex overflow-x-auto p-1",
          direction === "vertical" && "flex flex-col p-1",
          className
        )}
        style={style}
        role="list"
        aria-label="Sortable list"
        {...props}
      >
        {/* Drop zone indicator at the beginning of the list */}
        {draggedIndex !== null && (
          <div
            className={cn(
              dropZoneIndicator,
              direction === "vertical" ? "mx-2 w-full" : "my-2 h-full w-1",
              dragOverIndex === 0 && "opacity-100"
            )}
            onDragOver={handleItemDragOver(-1, true)}
          />
        )}

        {itemsToRender.map((item, index) => {
          // Determine if this item is being dragged
          const isItemDragging =
            draggedIndex !== null &&
            (showDragPreview
              ? item === localItems[draggedIndex] // When preview is enabled, check by item reference
              : draggedIndex === index); // When preview is disabled, check by current index

          return (
            <React.Fragment key={getItemKey(item, index)}>
              <SortableItem
                item={item}
                index={index}
                isDragging={isItemDragging}
                isDragOver={dragOverIndex === index}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
                onDrop={handleDrop}
                direction={direction}
                disabled={disabled}
                renderDragHandle={
                  renderDragHandle as
                    | ((item: unknown, index: number) => React.ReactNode)
                    | undefined
                }
                animationDuration={animationDuration}
                onDragOver={handleItemDragOver(index)}
              >
                {
                  renderItem as (
                    item: unknown,
                    index: number,
                    isDragging: boolean
                  ) => React.ReactNode
                }
              </SortableItem>

              {/* Drop zone indicator after this item */}
              {draggedIndex !== null && index < itemsToRender.length - 1 && (
                <div
                  className={cn(
                    dropZoneIndicator,
                    direction === "vertical" ? "mx-2 w-full" : "my-2 h-full w-1",
                    dragOverIndex === index + 1 && "opacity-100"
                  )}
                  onDragOver={handleItemDragOver(index, true)}
                />
              )}

              {/* Drop zone indicator after last item */}
              {draggedIndex !== null && index === itemsToRender.length - 1 && (
                <div
                  className={cn(
                    dropZoneIndicator,
                    direction === "vertical" ? "mx-2 w-full" : "my-2 h-full w-1",
                    dragOverIndex === itemsToRender.length && "opacity-100"
                  )}
                  onDragOver={handleItemDragOver(index, true)}
                />
              )}
            </React.Fragment>
          );
        })}
      </div>
    );
  }
);

SortableList.displayName = "SortableList";

import React from "react";
import { HiOutlineCheck } from "react-icons/hi";
import { cn, tw } from "@/lib/utils";

export interface Step {
  /**
   * Unique identifier for the step
   */
  id: string;
  /**
   * Title of the step
   */
  title: string;
  /**
   * Optional description of the step
   */
  description?: string;
  /**
   * Optional icon for the step
   */
  icon?: React.ReactNode;
  /**
   * Whether the step is disabled
   * @default false
   */
  disabled?: boolean;
}

export interface StepperProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /**
   * Array of steps to display
   */
  steps: Step[];
  /**
   * The current active step index (0-based)
   * @default 0
   */
  activeStep?: number;
  /**
   * The visual style of the stepper
   * @default "default"
   */
  variant?: "default" | "numbered" | "minimal";
  /**
   * The orientation of the stepper
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * The size of the stepper
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Whether steps are clickable for navigation
   * @default false
   */
  clickable?: boolean;
  /**
   * Whether to show step connectors
   * @default true
   */
  showConnector?: boolean;
  /**
   * Whether to show step descriptions
   * @default true
   */
  showDescription?: boolean;
  /**
   * Callback when a step is clicked (only works if clickable is true)
   */
  onStepClick?: (stepIndex: number, step: Step) => void;
  /**
   * Callback when the active step changes
   */
  onChange?: (stepIndex: number) => void;
}

// Base styles
const stepperBase = tw`flex w-full`;

// Step base styles
const stepBase = tw`relative flex items-center gap-3`;

// Step indicator styles
const stepIndicatorBase = tw`flex items-center justify-center rounded-full border-2 transition-all duration-200`;

// Step content styles
const stepContentBase = tw`flex min-w-0 flex-1 flex-col gap-1`;

// Step title styles
const stepTitleBase = tw`font-medium transition-colors duration-200`;

// Step description styles
const stepDescriptionBase = tw`text-sm transition-colors duration-200`;

// Connector styles
const connectorBase = tw`transition-all duration-200`;

// Variants
const variants = {
  default: {
    stepIndicator: {
      inactive: tw`border-border bg-background text-muted-foreground`,
      active: tw`border-primary bg-primary text-primary-foreground`,
      completed: tw`border-success bg-success text-success-foreground`,
      disabled: tw`border-border bg-muted text-muted-foreground opacity-50`,
    },
    stepTitle: {
      inactive: tw`text-muted-foreground`,
      active: tw`text-primary`,
      completed: tw`text-success`,
      disabled: tw`text-muted-foreground opacity-50`,
    },
    stepDescription: {
      inactive: tw`text-muted-foreground/70`,
      active: tw`text-foreground/80`,
      completed: tw`text-foreground/80`,
      disabled: tw`text-muted-foreground/40`,
    },
    connector: {
      inactive: tw`bg-border`,
      active: tw`bg-primary`,
      completed: tw`bg-success`,
    },
  },
  numbered: {
    stepIndicator: {
      inactive: tw`border-border bg-background text-muted-foreground`,
      active: tw`border-primary bg-primary text-primary-foreground`,
      completed: tw`border-success bg-success text-success-foreground`,
      disabled: tw`border-border bg-muted text-muted-foreground opacity-50`,
    },
    stepTitle: {
      inactive: tw`text-muted-foreground`,
      active: tw`text-primary`,
      completed: tw`text-success`,
      disabled: tw`text-muted-foreground opacity-50`,
    },
    stepDescription: {
      inactive: tw`text-muted-foreground/70`,
      active: tw`text-foreground/80`,
      completed: tw`text-foreground/80`,
      disabled: tw`text-muted-foreground/40`,
    },
    connector: {
      inactive: tw`bg-border`,
      active: tw`bg-primary`,
      completed: tw`bg-success`,
    },
  },
  minimal: {
    stepIndicator: {
      inactive: tw`border-border bg-background text-muted-foreground`,
      active: tw`border-primary bg-primary text-primary-foreground`,
      completed: tw`border-success bg-success text-success-foreground`,
      disabled: tw`border-border/50 bg-muted/50 text-muted-foreground/40`,
    },
    stepTitle: {
      inactive: tw`text-muted-foreground`,
      active: tw`text-primary`,
      completed: tw`text-success`,
      disabled: tw`text-muted-foreground/40`,
    },
    stepDescription: {
      inactive: tw`text-muted-foreground/50`,
      active: tw`text-foreground/70`,
      completed: tw`text-foreground/70`,
      disabled: tw`text-muted-foreground/30`,
    },
    connector: {
      inactive: tw`bg-border/60`,
      active: tw`bg-primary`,
      completed: tw`bg-success`,
    },
  },
};

// Sizes
const sizes = {
  sm: {
    stepIndicator: tw`h-6 w-6 text-xs`,
    stepTitle: tw`text-sm`,
    stepDescription: tw`text-xs`,
    connector: {
      horizontal: tw`h-0.5 w-full`,
      vertical: tw`h-full w-0.5`,
    },
    gap: tw`gap-2`,
  },
  md: {
    stepIndicator: tw`h-8 w-8 text-sm`,
    stepTitle: tw`text-base`,
    stepDescription: tw`text-sm`,
    connector: {
      horizontal: tw`h-0.5 w-full`,
      vertical: tw`h-full w-0.5`,
    },
    gap: tw`gap-3`,
  },
  lg: {
    stepIndicator: tw`h-10 w-10 text-base`,
    stepTitle: tw`text-lg`,
    stepDescription: tw`text-base`,
    connector: {
      horizontal: tw`h-1 w-full`,
      vertical: tw`h-full w-1`,
    },
    gap: tw`gap-4`,
  },
};

// Orientation styles
const orientations = {
  horizontal: tw`flex-row items-center`,
  vertical: tw`flex-col`,
};

export const Stepper = React.forwardRef<HTMLDivElement, StepperProps>(
  (
    {
      steps,
      activeStep = 0,
      variant = "default",
      orientation = "horizontal",
      size = "md",
      clickable = false,
      showConnector = true,
      showDescription = true,
      onStepClick,
      onChange,
      className = "",
      ...props
    },
    ref
  ) => {
    const handleStepClick = (stepIndex: number, step: Step) => {
      if (!clickable || step.disabled) return;

      onStepClick?.(stepIndex, step);
      onChange?.(stepIndex);
    };

    const getStepState = (stepIndex: number, step: Step) => {
      if (step.disabled) return "disabled";
      if (stepIndex < activeStep) return "completed";
      if (stepIndex === activeStep) return "active";
      return "inactive";
    };

    const getStepIndicatorContent = (stepIndex: number, step: Step, state: string) => {
      if (variant === "numbered") {
        return stepIndex + 1;
      }

      if (state === "completed") {
        return <HiOutlineCheck className="h-4 w-4" />;
      }

      if (step.icon) {
        return step.icon;
      }

      return stepIndex + 1;
    };

    const renderConnector = (stepIndex: number) => {
      if (!showConnector || stepIndex === steps.length - 1) return null;

      const nextStep = steps[stepIndex + 1];
      const currentState = getStepState(stepIndex, steps[stepIndex]);
      const nextState = getStepState(stepIndex + 1, nextStep);

      let connectorState: "inactive" | "active" | "completed" = "inactive";
      if (currentState === "completed" || nextState === "active" || nextState === "completed") {
        connectorState = currentState === "completed" ? "completed" : "active";
      }

      const connectorStyles = [
        connectorBase,
        sizes[size].connector[orientation],
        variants[variant].connector[connectorState],
      ];

      if (orientation === "horizontal") {
        return <div className={cn("mx-4 flex-1", connectorStyles)} />;
      } else {
        return <div className={cn("my-2 ml-4", connectorStyles)} />;
      }
    };

    return (
      <div
        ref={ref}
        className={cn(stepperBase, orientations[orientation], sizes[size].gap, className)}
        role="tablist"
        aria-orientation={orientation}
        {...props}
      >
        {steps.map((step, stepIndex) => {
          const state = getStepState(stepIndex, step);
          const isClickable = clickable && !step.disabled;

          return (
            <React.Fragment key={step.id}>
              <div
                className={cn(
                  stepBase,
                  sizes[size].gap,
                  orientation === "vertical" && "w-full",
                  isClickable && "cursor-pointer"
                )}
                onClick={() => handleStepClick(stepIndex, step)}
                role={isClickable ? "tab" : undefined}
                aria-selected={stepIndex === activeStep}
                aria-disabled={step.disabled}
                tabIndex={isClickable ? 0 : undefined}
                onKeyDown={e => {
                  if (isClickable && (e.key === "Enter" || e.key === " ")) {
                    e.preventDefault();
                    handleStepClick(stepIndex, step);
                  }
                }}
              >
                {/* Step Indicator */}
                <div
                  className={cn(
                    stepIndicatorBase,
                    sizes[size].stepIndicator,
                    variants[variant].stepIndicator[state],
                    isClickable && "hover:shadow-md"
                  )}
                >
                  {getStepIndicatorContent(stepIndex, step, state)}
                </div>

                {/* Step Content */}
                <div className={cn(stepContentBase)}>
                  <div
                    className={cn(
                      stepTitleBase,
                      sizes[size].stepTitle,
                      variants[variant].stepTitle[state]
                    )}
                  >
                    {step.title}
                  </div>
                  {showDescription && step.description && (
                    <div
                      className={cn(
                        stepDescriptionBase,
                        sizes[size].stepDescription,
                        variants[variant].stepDescription[state]
                      )}
                    >
                      {step.description}
                    </div>
                  )}
                </div>
              </div>

              {/* Connector */}
              {renderConnector(stepIndex)}
            </React.Fragment>
          );
        })}
      </div>
    );
  }
);

Stepper.displayName = "Stepper";

import React, { useEffect, useState } from "react";
import { cn, tw } from "@/lib/utils";

export interface SwitchProps {
  /**
   * The visual style of the switch
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the switch
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Control the border radius of the switch
   * @default "full"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Whether the switch is checked
   */
  checked?: boolean;
  /**
   * Default checked state (uncontrolled)
   */
  defaultChecked?: boolean;
  /**
   * Callback when switch state changes
   */
  onCheckedChange?: (checked: boolean) => void;
  /**
   * Whether the switch is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Optional label text displayed next to the switch
   */
  label?: string;
  /**
   * Position of the label relative to the switch
   * @default "right"
   */
  labelPosition?: "left" | "right";
  /**
   * Optional helper/description text displayed below the switch
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the switch
   */
  errorMessage?: string;
  /**
   * Custom class name
   */
  className?: string;
  /**
   * ID for the switch element
   */
  id?: string;
  /**
   * Name attribute for the switch
   */
  name?: string;
  /**
   * Value attribute for the switch
   */
  value?: string;
}

const wrapperBase = tw`relative inline-flex flex-col`;
const containerBase = tw`inline-flex items-center gap-2`;

// rui-focus-ring: keyboard-only :focus-visible ring
const switchBase = tw`rui-focus-ring relative inline-flex shrink-0 cursor-pointer border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none`;

const variants = {
  primary: {
    off: tw`bg-secondary`,
    on: tw`bg-primary`,
  },
  secondary: {
    off: tw`bg-secondary`,
    on: tw`bg-secondary-foreground`,
  },
};

const sizes = {
  sm: { switch: tw`h-4 w-7`, thumb: tw`h-3 w-3`, translate: tw`translate-x-3`, text: tw`text-xs` },
  md: { switch: tw`h-5 w-9`, thumb: tw`h-4 w-4`, translate: tw`translate-x-4`, text: tw`text-sm` },
  lg: {
    switch: tw`h-6 w-11`,
    thumb: tw`h-5 w-5`,
    translate: tw`translate-x-5`,
    text: tw`text-base`,
  },
};

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const thumbBase = tw`pointer-events-none absolute top-0 left-0 inline-block transform bg-background shadow-sm transition duration-200 ease-in-out`;

export const Switch = React.forwardRef<HTMLButtonElement, SwitchProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "full",
      animation = true,
      checked,
      defaultChecked = false,
      onCheckedChange,
      disabled = false,
      label,
      labelPosition = "right",
      description,
      error = false,
      errorMessage,
      className = "",
      id,
      name,
      value,
      ...props
    },
    ref
  ) => {
    const [isChecked, setIsChecked] = useState(checked ?? defaultChecked);

    const autoId = React.useId();
    const switchId = id ?? autoId;
    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${switchId}-desc`;

    useEffect(() => {
      if (checked !== undefined) setIsChecked(checked);
    }, [checked]);

    const handleToggle = () => {
      if (disabled) return;
      const newChecked = !isChecked;
      if (checked === undefined) setIsChecked(newChecked);
      onCheckedChange?.(newChecked);
    };

    const switchClasses = cn(
      switchBase,
      sizes[size].switch,
      roundedOptions[rounded],
      isChecked ? variants[variant].on : variants[variant].off,
      disabled && "cursor-not-allowed opacity-50",
      error && "ring-1 ring-destructive",
      !animation && "transition-none",
      className
    );

    const thumbClasses = cn(
      thumbBase,
      sizes[size].thumb,
      roundedOptions[rounded],
      isChecked ? sizes[size].translate : "translate-x-0",
      !animation && "transition-none"
    );

    const SwitchElement = (
      <button
        ref={ref}
        type="button"
        role="switch"
        aria-checked={isChecked}
        aria-describedby={hasAssistive ? assistiveId : undefined}
        onClick={handleToggle}
        disabled={disabled}
        id={switchId}
        name={name}
        value={value}
        className={switchClasses}
        {...props}
      >
        <span className={thumbClasses} />
      </button>
    );

    const LabelElement = label && (
      <label
        htmlFor={switchId}
        className={cn(
          "text-foreground font-medium",
          sizes[size].text,
          error && "text-destructive",
          disabled ? "text-muted-foreground cursor-not-allowed" : "cursor-pointer"
        )}
      >
        {label}
      </label>
    );

    return (
      <div className={wrapperBase}>
        <div
          className={cn(containerBase, labelPosition === "left" ? "flex-row-reverse" : "flex-row")}
        >
          {labelPosition === "left" && LabelElement}
          {SwitchElement}
          {labelPosition === "right" && LabelElement}
          {label && <div className={labelPosition === "left" ? "mr-3" : "ml-3"} />}
        </div>

        {hasAssistive && (
          <div id={assistiveId} className="mt-1 min-h-[1rem] px-1">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

Switch.displayName = "Switch";

import { cn, tw } from "@/lib/utils";
import React, { useCallback, useEffect, useRef, useState } from "react";

export type TableDensity = "compact" | "normal" | "comfortable";
export type TableVariant = "plain" | "zebra" | "outlined";
export type TableAlign = "left" | "center" | "right";

export interface Column<T> {
  /** Unique key for the column. Used to map row data */
  key: keyof T | string;
  /** Header label or custom node */
  header: React.ReactNode;
  /** Optional accessor for derived values */
  accessor?: (row: T, rowIndex: number) => React.ReactNode;
  /** Text alignment for the column */
  align?: TableAlign;
  /** Optional width (tailwind classes or fixed css width) */
  width?: string;
  /** Whether this column is sticky on the left */
  sticky?: boolean;
  /** Whether this column is resizable */
  resizable?: boolean;
  /** Minimum width for resizable columns */
  minWidth?: number;
  /** Maximum width for resizable columns */
  maxWidth?: number;
  /** Custom className for the column header */
  className?: string | ((column: Column<T>) => string);
}

export interface TableProps<T> {
  /** Columns configuration */
  columns: Column<T>[];
  /** Data rows */
  data: T[];
  /** Visual density */
  density?: TableDensity;
  /** Visual variant */
  variant?: TableVariant;
  /** Add hover effect for rows */
  highlightOnHover?: boolean;
  /** Render when there is no data */
  emptyState?: React.ReactNode;
  /** Optional caption for accessibility */
  caption?: string;
  /** Controlled selection: selected row indices */
  selectedRows?: number[];
  /** Callback when a row is clicked */
  onRowClick?: (row: T, index: number) => void;
  /** Callback when selection toggles for a row (if selection is implemented externally) */
  onSelectRow?: (row: T, index: number, selected: boolean) => void;
  /** Optional className for the wrapper */
  className?: string;
  /** Optional max height to enable scroll with sticky header */
  maxHeight?: string | number;
  /** Enable sticky header */
  stickyHeader?: boolean;
  /** ARIA label (when no visible caption) */
  ariaLabel?: string;
  /** Enable virtualization for large datasets */
  virtualization?: boolean;
  /** Row height for virtualization (in pixels) */
  rowHeight?: number;
  /** Overscan count for virtualization */
  overscan?: number;
  /** Custom className for rows */
  rowClassName?: string | ((row: T, index: number) => string);
  /** Custom className for cells */
  cellClassName?:
    | string
    | ((row: T, column: Column<T>, rowIndex: number, colIndex: number) => string);
  /** Callback when column is resized */
  onColumnResize?: (columnKey: string | keyof T, width: number) => void;
}

const tableBase = tw`w-full border-collapse text-foreground`;
const wrapperBase = tw`relative w-full overflow-auto rounded-md border border-border bg-card`;
const headerBase = tw`bg-muted/40 text-left text-sm font-semibold text-muted-foreground`;
const cellBase = tw`text-sm text-foreground`;
const outlinedCell = tw`border border-border`;

const densityRow: Record<TableDensity, string> = {
  compact: tw`[&>td]:py-2 [&>th]:py-2`,
  normal: tw`[&>td]:py-3 [&>th]:py-3`,
  comfortable: tw`[&>td]:py-4 [&>th]:py-4`,
};

const densityCellPadding: Record<TableDensity, string> = {
  compact: tw`px-3`,
  normal: tw`px-4`,
  comfortable: tw`px-5`,
};

const densityRowHeight: Record<TableDensity, number> = {
  compact: 36,
  normal: 48,
  comfortable: 60,
};

function getAlign(align?: TableAlign) {
  if (align === "center") return "text-center";
  if (align === "right") return "text-right";
  return "text-left";
}

// Hook for virtualization
function useVirtualization(
  enabled: boolean,
  itemCount: number,
  itemHeight: number,
  containerHeight: number,
  overscan = 5
) {
  const [scrollTop, setScrollTop] = useState(0);

  const onScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  if (!enabled || containerHeight === 0) {
    return {
      startIndex: 0,
      endIndex: itemCount - 1,
      visibleItems: itemCount,
      totalHeight: 0,
      offsetY: 0,
      onScroll,
    };
  }

  const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
  const visibleItemsCount = Math.ceil(containerHeight / itemHeight) + overscan * 2;
  const endIndex = Math.min(itemCount - 1, startIndex + visibleItemsCount);
  const totalHeight = itemCount * itemHeight;
  const offsetY = startIndex * itemHeight;

  return {
    startIndex,
    endIndex,
    visibleItems: endIndex - startIndex + 1,
    totalHeight,
    offsetY,
    onScroll,
  };
}

// Hook for column resizing
function useColumnResizing<T>(
  columns: Column<T>[],
  onColumnResize?: (columnKey: string | keyof T, width: number) => void
) {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const [isResizing, setIsResizing] = useState<string | null>(null);
  const [startX, setStartX] = useState(0);
  const [startWidth, setStartWidth] = useState(0);

  const handleMouseDown = useCallback(
    (e: React.MouseEvent, columnKey: string | keyof T, currentWidth: number) => {
      e.preventDefault();
      setIsResizing(String(columnKey));
      setStartX(e.clientX);
      setStartWidth(currentWidth);
    },
    []
  );

  const handleMouseMove = useCallback(
    (e: MouseEvent) => {
      if (!isResizing) return;

      const diff = e.clientX - startX;
      const newWidth = Math.max(50, startWidth + diff); // Minimum width of 50px

      const column = columns.find(col => String(col.key) === isResizing);
      if (column?.minWidth && newWidth < column.minWidth) return;
      if (column?.maxWidth && newWidth > column.maxWidth) return;

      setColumnWidths(prev => ({
        ...prev,
        [isResizing]: newWidth,
      }));
    },
    [isResizing, startX, startWidth, columns]
  );

  const handleMouseUp = useCallback(() => {
    if (isResizing && columnWidths[isResizing]) {
      onColumnResize?.(isResizing, columnWidths[isResizing]);
    }
    setIsResizing(null);
  }, [isResizing, columnWidths, onColumnResize]);

  useEffect(() => {
    if (isResizing) {
      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", handleMouseUp);
      return () => {
        document.removeEventListener("mousemove", handleMouseMove);
        document.removeEventListener("mouseup", handleMouseUp);
      };
    }
  }, [isResizing, handleMouseMove, handleMouseUp]);

  const getColumnWidth = (column: Column<T>) => {
    const key = String(column.key);
    return columnWidths[key] ? `${columnWidths[key]}px` : column.width;
  };

  return {
    getColumnWidth,
    handleMouseDown,
    isResizing,
  };
}

export function Table<T extends Record<string, unknown>>({
  columns,
  data = [],
  density = "normal",
  variant = "plain",
  highlightOnHover = true,
  emptyState = <div className="text-muted-foreground p-6 text-center text-sm">No data</div>,
  caption,
  selectedRows,
  onRowClick,
  onSelectRow,
  className = "",
  maxHeight,
  stickyHeader = true,
  ariaLabel,
  virtualization = false,
  rowHeight,
  overscan = 5,
  rowClassName,
  cellClassName,
  onColumnResize,
}: TableProps<T>) {
  const tableId = React.useId();
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerHeight, setContainerHeight] = useState(0);

  const hasData = data && data.length > 0;
  const effectiveRowHeight = rowHeight || densityRowHeight[density];

  // Column resizing
  const { getColumnWidth, handleMouseDown, isResizing } = useColumnResizing(
    columns,
    onColumnResize
  );

  // Virtualization
  const { startIndex, endIndex, totalHeight, offsetY, onScroll } = useVirtualization(
    virtualization && hasData,
    data.length,
    effectiveRowHeight,
    containerHeight,
    overscan
  );

  // Update container height
  useEffect(() => {
    if (containerRef.current && (virtualization || stickyHeader || maxHeight)) {
      const updateHeight = () => {
        const rect = containerRef.current?.getBoundingClientRect();
        if (rect) {
          setContainerHeight(rect.height);
        }
      };

      // Initial measurement
      updateHeight();

      // Use ResizeObserver to track container size changes
      const resizeObserver = new ResizeObserver(updateHeight);
      resizeObserver.observe(containerRef.current);

      // Also update on window resize
      window.addEventListener("resize", updateHeight);

      return () => {
        resizeObserver.disconnect();
        window.removeEventListener("resize", updateHeight);
      };
    }
  }, [virtualization, stickyHeader, maxHeight]);

  const getRowClassName = (row: T, index: number) => {
    if (typeof rowClassName === "function") {
      return rowClassName(row, index);
    }
    return rowClassName || "";
  };

  const getCellClassName = (row: T, column: Column<T>, rowIndex: number, colIndex: number) => {
    if (typeof cellClassName === "function") {
      return cellClassName(row, column, rowIndex, colIndex);
    }
    return cellClassName || "";
  };

  const getColumnClassName = (column: Column<T>) => {
    if (typeof column.className === "function") {
      return column.className(column);
    }
    return column.className || "";
  };

  const visibleData = virtualization && hasData ? data.slice(startIndex, endIndex + 1) : data;

  // Sticky header implementation
  const headerElement = (
    <thead className={cn(headerBase, stickyHeader && "bg-card sticky top-0 z-20")}>
      <tr className={cn(densityRow[density])}>
        {columns.map((col, i) => (
          <th
            key={String(col.key) + i}
            scope="col"
            className={cn(
              densityCellPadding[density],
              variant === "outlined" && outlinedCell,
              getAlign(col.align),
              col.sticky && "bg-card sticky left-0 z-30",
              getColumnClassName(col),
              "relative"
            )}
            style={{ width: getColumnWidth(col) }}
          >
            <div
              className={cn(
                "flex items-center",
                col.align === "right"
                  ? "justify-end"
                  : col.align === "center"
                    ? "justify-center"
                    : "justify-between"
              )}
            >
              <span
                className={cn(
                  col.align === "right" && col.resizable ? "mr-2" : "",
                  col.align === "center" ? "flex-1 text-center" : ""
                )}
              >
                {col.header}
              </span>
              {col.resizable && (
                <div
                  className={cn(
                    "hover:bg-primary absolute top-0 right-0 h-full w-1 cursor-col-resize bg-transparent",
                    isResizing === String(col.key) && "bg-primary",
                    col.align === "right" ? "relative" : ""
                  )}
                  onMouseDown={e => {
                    const currentWidth = getColumnWidth(col);
                    const widthInPx = currentWidth?.includes("px")
                      ? parseInt(currentWidth)
                      : currentWidth?.includes("rem")
                        ? parseInt(currentWidth) * 16
                        : 150; // default fallback
                    handleMouseDown(e, col.key, widthInPx);
                  }}
                />
              )}
            </div>
          </th>
        ))}
      </tr>
    </thead>
  );

  const bodyElement = (
    <tbody>
      {!hasData && (
        <tr>
          <td
            colSpan={columns.length}
            className={cn("p-0", variant === "outlined" && outlinedCell)}
          >
            {emptyState}
          </td>
        </tr>
      )}
      {virtualization && hasData && offsetY > 0 && (
        <tr>
          <td colSpan={columns.length} style={{ height: offsetY, padding: 0, border: "none" }} />
        </tr>
      )}
      {hasData &&
        visibleData.map((row, relativeIndex) => {
          const actualIndex = virtualization ? startIndex + relativeIndex : relativeIndex;
          const isSelected = selectedRows?.includes(actualIndex) ?? false;
          return (
            <tr
              key={`${tableId}-row-${actualIndex}`}
              className={cn(
                "group",
                densityRow[density],
                variant === "zebra" && actualIndex % 2 === 1 && "bg-muted/35",
                isSelected && "!bg-accent/40",
                highlightOnHover && "hover:bg-accent/25",
                onRowClick && "cursor-pointer",
                getRowClassName(row, actualIndex)
              )}
              onClick={() => onRowClick?.(row, actualIndex)}
              style={virtualization ? { height: effectiveRowHeight } : {}}
              onMouseEnter={e => {
                if (highlightOnHover) {
                  e.currentTarget.style.setProperty("--row-hover-bg", "hsl(var(--accent) / 0.25)");
                }
              }}
              onMouseLeave={e => {
                if (highlightOnHover) {
                  e.currentTarget.style.removeProperty("--row-hover-bg");
                }
              }}
            >
              {columns.map((col, colIndex) => {
                const value = col.accessor
                  ? col.accessor(row, actualIndex)
                  : (row as Record<string, unknown>)[col.key as string];
                return (
                  <td
                    key={`${tableId}-cell-${actualIndex}-${colIndex}`}
                    className={cn(
                      cellBase,
                      densityCellPadding[density],
                      variant === "outlined" && outlinedCell,
                      getAlign(col.align),
                      col.sticky && "sticky left-0 z-10",
                      getCellClassName(row, col, actualIndex, colIndex)
                    )}
                    style={{
                      width: getColumnWidth(col),
                      backgroundColor: col.sticky
                        ? isSelected
                          ? "hsl(var(--accent) / 0.4)"
                          : "var(--row-hover-bg, " +
                            (variant === "zebra" && actualIndex % 2 === 1
                              ? "hsl(var(--muted) / 0.35)"
                              : "hsl(var(--background))") +
                            ")"
                        : undefined,
                    }}
                  >
                    {value as React.ReactNode}
                  </td>
                );
              })}
            </tr>
          );
        })}
      {virtualization &&
        hasData &&
        totalHeight - offsetY - visibleData.length * effectiveRowHeight > 0 && (
          <tr>
            <td
              colSpan={columns.length}
              style={{
                height: totalHeight - offsetY - visibleData.length * effectiveRowHeight,
                padding: 0,
                border: "none",
              }}
            />
          </tr>
        )}
    </tbody>
  );

  const table = (
    <table
      className={cn(
        tableBase,
        variant !== "plain" && "w-full",
        variant === "outlined" && "border-border border",
        className
      )}
      aria-label={ariaLabel}
    >
      {caption && <caption className="sr-only">{caption}</caption>}
      {headerElement}
      {bodyElement}
    </table>
  );

  if (stickyHeader || maxHeight || virtualization) {
    return (
      <div
        ref={containerRef}
        className={cn(wrapperBase, "overflow-auto")}
        style={{
          maxHeight: typeof maxHeight === "number" ? `${maxHeight}px` : maxHeight,
          height: virtualization
            ? typeof maxHeight === "number"
              ? `${maxHeight}px`
              : maxHeight || "400px"
            : "auto",
        }}
        role="region"
        aria-label={caption || ariaLabel}
        onScroll={virtualization ? onScroll : undefined}
      >
        {table}
      </div>
    );
  }

  return <div className={cn(wrapperBase)}>{table}</div>;
}

Table.displayName = "Table";

import React, { createContext, useCallback, useContext, useEffect, useState } from "react";
import { cn, tw } from "@/lib/utils";

export interface TabsProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The default active tab value (uncontrolled)
   * @default first tab
   */
  defaultValue?: string;
  /**
   * The controlled active tab value
   */
  value?: string;
  /**
   * Callback when active tab changes
   */
  onValueChange?: (value: string) => void;
  /**
   * The visual style of the tabs
   * @default "default"
   */
  variant?: "default" | "underline" | "pills";
  /**
   * The size of the tabs
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Orientation of the tabs
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Whether tabs should take full width
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Tab content
   */
  children: React.ReactNode;
}

export interface TabListProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Tab list content (Tab components)
   */
  children: React.ReactNode;
}

export interface TabProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Unique value for the tab
   */
  value: string;
  /**
   * Whether the tab is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Tab content
   */
  children: React.ReactNode;
}

export interface TabPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Value that corresponds to the tab
   */
  value: string;
  /**
   * Panel content
   */
  children: React.ReactNode;
}

// Context for tabs state management
interface TabsContextType {
  value: string;
  onValueChange: (value: string) => void;
  variant: "default" | "underline" | "pills";
  size: "sm" | "md" | "lg";
  orientation: "horizontal" | "vertical";
  fullWidth: boolean;
}

const TabsContext = createContext<TabsContextType | null>(null);

const useTabs = () => {
  const context = useContext(TabsContext);
  if (!context) {
    throw new Error("Tab components must be used within a Tabs component");
  }
  return context;
};

const baseTabList = tw`flex border-b border-border bg-background`;
const baseTab = tw`relative inline-flex items-center justify-center px-3 py-2 text-sm font-medium whitespace-nowrap transition-all focus:outline-none rui-focus-ring disabled:pointer-events-none disabled:opacity-50`;
const baseTabPanel = tw`mt-4 focus-visible:outline-none`;

const tabListVariants = {
  default: tw``,
  underline: tw`border-b-2`,
  pills: tw`rounded-lg bg-muted p-1`,
};

const tabListOrientations = {
  horizontal: tw`flex-row`,
  vertical: tw`flex-col border-r border-b-0 border-border`,
};

const tabVariants = {
  default: {
    inactive: tw`cursor-pointer border-b-2 border-transparent text-muted-foreground hover:text-primary`,
    active: tw`border-b-2 border-primary text-primary`,
  },
  underline: {
    inactive: tw`cursor-pointer border-b-2 border-transparent text-muted-foreground hover:text-primary`,
    active: tw`border-b-2 border-primary text-primary`,
  },
  pills: {
    inactive: tw`cursor-pointer bg-transparent text-muted-foreground hover:text-foreground`,
    active: tw`bg-background text-primary shadow-sm`,
  },
};

const tabSizes = {
  sm: tw`px-2 py-1.5 text-xs`,
  md: tw`px-3 py-2 text-sm`,
  lg: tw`px-4 py-2.5 text-base`,
};

const tabPanelVariants = {
  horizontal: tw``,
  vertical: tw`ml-8`,
};

export const Tabs: React.FC<TabsProps> = ({
  children,
  className,
  defaultValue,
  value: controlledValue,
  onValueChange,
  variant = "default",
  size = "md",
  orientation = "horizontal",
  fullWidth = false,
  ...props
}) => {
  const [internalValue, setInternalValue] = useState<string>("");

  // Determine if controlled or uncontrolled
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : internalValue;

  const handleValueChange = useCallback(
    (newValue: string) => {
      if (!isControlled) {
        setInternalValue(newValue);
      }
      onValueChange?.(newValue);
    },
    [isControlled, onValueChange]
  );

  // Set default value on mount
  useEffect(() => {
    if (!value && defaultValue) {
      handleValueChange(defaultValue);
    }
  }, [defaultValue, value, handleValueChange]);

  const contextValue: TabsContextType = {
    value,
    onValueChange: handleValueChange,
    variant,
    size,
    orientation,
    fullWidth,
  };

  return (
    <TabsContext.Provider value={contextValue}>
      <div className={cn("", className)} {...props}>
        {children}
      </div>
    </TabsContext.Provider>
  );
};

export const TabList: React.FC<TabListProps> = ({ children, className, ...props }) => {
  const { variant, orientation, fullWidth } = useTabs();

  return (
    <div
      className={cn(
        baseTabList,
        tabListVariants[variant],
        tabListOrientations[orientation],
        fullWidth && "w-full",
        className
      )}
      role="tablist"
      {...props}
    >
      {children}
    </div>
  );
};

export const Tab: React.FC<TabProps> = ({
  children,
  className,
  value,
  disabled = false,
  onClick,
  ...props
}) => {
  const { value: activeValue, onValueChange, variant, size, fullWidth } = useTabs();
  const isActive = activeValue === value;

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!disabled) {
      onValueChange(value);
    }
    onClick?.(e);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
    // Handle keyboard navigation
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (!disabled) {
        onValueChange(value);
      }
    }
  };

  return (
    <button
      className={cn(
        baseTab,
        tabSizes[size],
        isActive ? tabVariants[variant].active : tabVariants[variant].inactive,
        fullWidth && "flex-1",
        variant === "pills" && isActive && "rounded-md",
        variant === "pills" && !isActive && "rounded-md",
        className
      )}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      disabled={disabled}
      role="tab"
      aria-selected={isActive}
      aria-controls={`tabpanel-${value}`}
      id={`tab-${value}`}
      tabIndex={isActive ? 0 : -1}
      {...props}
    >
      {children}
    </button>
  );
};

export const TabPanel: React.FC<TabPanelProps> = ({ children, className, value, ...props }) => {
  const { value: activeValue, orientation } = useTabs();
  const isActive = activeValue === value;

  if (!isActive) return null;

  return (
    <div
      className={cn(baseTabPanel, tabPanelVariants[orientation], className)}
      role="tabpanel"
      aria-labelledby={`tab-${value}`}
      id={`tabpanel-${value}`}
      {...props}
    >
      {children}
    </div>
  );
};

import React from "react";
import { cn, tw } from "@/lib/utils";

export interface TextInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> {
  /**
   * The visual style of the input
   * @default "primary"
   */
  variant?: "primary" | "secondary";
  /**
   * The size of the input
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * Control the border radius of the input
   * @default "sm"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Make input take full width of its container
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Optional left icon - accepts any React element
   */
  startIcon?: React.ReactNode;
  /**
   * Optional right icon - accepts any React element
   */
  endIcon?: React.ReactNode;
  /**
   * Optional label text displayed above the input
   */
  label?: string;
  /**
   * Optional helper/description text displayed below the input
   */
  description?: string;
  /**
   * Show error state
   * @default false
   */
  error?: boolean;
  /**
   * Error message to display below the input
   */
  errorMessage?: string;
  /**
   * Preset width of the input wrapper
   * @default "md"
   */
  width?: "sm" | "md" | "lg" | "xl";
}

const wrapperBase = tw`relative inline-flex w-full flex-col`;

// rui-field-focus: handles border-color transition on focus (no ring, clean)
const fieldBase = tw`rui-field-focus relative inline-flex items-center border bg-background text-foreground transition-colors duration-150 disabled:cursor-not-allowed disabled:opacity-50`;

const variants = {
  primary: tw`border-input bg-background`,
  secondary: tw`border-input bg-muted`,
};

const sizes = {
  xs: { container: tw`h-7`, input: tw`text-xs`, padX: "px-2", gap: "gap-1" },
  sm: { container: tw`h-8`, input: tw`text-xs`, padX: "px-2.5", gap: "gap-1.5" },
  md: { container: tw`h-9`, input: tw`text-sm`, padX: "px-3", gap: "gap-2" },
  lg: { container: tw`h-10`, input: tw`text-sm`, padX: "px-3.5", gap: "gap-2" },
  xl: { container: tw`h-12`, input: tw`text-base`, padX: "px-4", gap: "gap-2.5" },
} as const;

const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

const labelSizes = {
  xs: tw`text-xs`,
  sm: tw`text-sm`,
  md: tw`text-sm`,
  lg: tw`text-base`,
  xl: tw`text-base`,
};

const widths = {
  sm: tw`w-64`,
  md: tw`w-80`,
  lg: tw`w-96`,
  xl: tw`w-[30rem]`,
} as const;

export const TextInput = React.forwardRef<HTMLInputElement, TextInputProps>(
  (
    {
      variant = "primary",
      size = "md",
      rounded = "sm",
      fullWidth = false,
      width = "md",
      startIcon,
      endIcon,
      label,
      description,
      error = false,
      errorMessage,
      className = "",
      id,
      disabled,
      ...props
    },
    ref
  ) => {
    const inputRef = React.useRef<HTMLInputElement | null>(null);
    React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement);
    const autoId = React.useId();
    const inputId = id ?? autoId;

    const hasAssistive = Boolean(description || (error && errorMessage));
    const assistiveId = `${inputId}-desc`;

    return (
      <div className={cn(wrapperBase, fullWidth ? "w-full" : (widths[width] ?? "w-auto"))}>
        {label && (
          <label
            htmlFor={inputId}
            className={cn(
              "text-foreground mb-1 font-medium",
              labelSizes[size],
              error && "text-destructive"
            )}
          >
            {label}
          </label>
        )}
        <div
          className={cn(
            fieldBase,
            variants[variant],
            sizes[size].container,
            roundedOptions[rounded],
            sizes[size].padX,
            sizes[size].gap,
            error && "rui-field-error border-destructive",
            fullWidth && "w-full",
            className
          )}
        >
          {startIcon && (
            <span className="text-muted-foreground flex shrink-0 items-center">{startIcon}</span>
          )}
          <input
            ref={inputRef}
            id={inputId}
            className="placeholder:text-muted-foreground min-w-0 flex-1 bg-transparent outline-none placeholder:font-light"
            aria-invalid={error || undefined}
            aria-describedby={hasAssistive ? assistiveId : undefined}
            disabled={disabled}
            {...props}
          />
          {endIcon && (
            <span className="text-muted-foreground flex shrink-0 items-center">{endIcon}</span>
          )}
        </div>
        {hasAssistive && (
          <div id={assistiveId} className="mt-1 min-h-[1rem]">
            {error && errorMessage ? (
              <span className="text-destructive text-sm">{errorMessage}</span>
            ) : description ? (
              <span className="text-muted-foreground text-sm">{description}</span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);

TextInput.displayName = "TextInput";

