import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
  HiOutlineCheckCircle,
  HiOutlineExclamation,
  HiOutlineExclamationCircle,
  HiOutlineInformationCircle,
} from "react-icons/hi";
import { IoClose } from "react-icons/io5";
import { cn, tw } from "@/lib/utils";

export interface ToastProps {
  /**
   * Whether the toast is visible
   */
  open: boolean;
  /**
   * Callback when toast should close
   */
  onClose: () => void;
  /**
   * The type of toast which determines the visual style and icon
   * @default "info"
   */
  variant?: "success" | "error" | "warning" | "info";
  /**
   * The position of the toast on screen
   * @default "top-right"
   */
  position?:
    | "top-left"
    | "top-center"
    | "top-right"
    | "bottom-left"
    | "bottom-center"
    | "bottom-right";
  /**
   * The size of the toast
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Auto-dismiss duration in milliseconds. Set to 0 to disable auto-dismiss
   * @default 5000
   */
  duration?: number;
  /**
   * Custom icon to display instead of default variant icon
   */
  icon?: React.ReactNode;
  /**
   * Toast title
   */
  title?: string;
  /**
   * Toast description/content
   */
  description?: string;
  /**
   * Toast content (alternative to title/description)
   */
  children?: React.ReactNode;
  /**
   * Show close button
   * @default true
   */
  showCloseButton?: boolean;
  /**
   * Enable/disable animations
   * @default true
   */
  animation?: boolean;
  /**
   * Custom class name for the toast container
   */
  className?: string;
  /**
   * ID for the toast element
   */
  id?: string;
  /**
   * Aria label for accessibility
   */
  ariaLabel?: string;
}

// Base styles
const toastBase = tw`relative flex max-w-sm items-start gap-3 rounded-lg border border-border p-4 shadow-md outline-none bg-background text-foreground`;
const contentBase = tw`min-w-0 flex-1`;
const titleBase = tw`text-sm font-semibold break-words`;
const descriptionBase = tw`text-sm text-foreground/80 break-words`;
const closeButtonBase = tw`flex shrink-0 items-center justify-center rounded-md p-1 text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground rui-focus-ring focus:outline-none`;

// Variants — semantic status toasts
const variants = {
  success: tw`border-success/30 bg-success/10 text-success`,
  error: tw`border-destructive/30 bg-destructive/10 text-destructive`,
  warning: tw`border-warning/30 bg-warning/10 text-warning`,
  info: tw`border-info/30 bg-info/10 text-info`,
};

// Sizes
const sizes = {
  sm: tw`gap-2 p-3`,
  md: tw`gap-3 p-4`,
  lg: tw`gap-4 p-5`,
};

// Positions
const positions = {
  "top-left": tw`top-4 left-4`,
  "top-center": tw`top-4 left-1/2 -translate-x-1/2`,
  "top-right": tw`top-4 right-4`,
  "bottom-left": tw`bottom-4 left-4`,
  "bottom-center": tw`bottom-4 left-1/2 -translate-x-1/2`,
  "bottom-right": tw`right-4 bottom-4`,
};

// Animation classes
const toastAnimations = {
  enter: tw`animate-in fade-in-0 slide-in-from-top-2 duration-300 ease-out`,
  exit: tw`animate-out fade-out-0 slide-out-to-top-2 duration-200 ease-in`,
};

// Default icons for variants
const variantIcons = {
  success: <HiOutlineCheckCircle className="h-5 w-5" />,
  error: <HiOutlineExclamationCircle className="h-5 w-5" />,
  warning: <HiOutlineExclamation className="h-5 w-5" />,
  info: <HiOutlineInformationCircle className="h-5 w-5" />,
};

export const Toast = React.forwardRef<HTMLDivElement, ToastProps>(
  (
    {
      open,
      onClose,
      variant = "info",
      position = "top-right",
      size = "md",
      duration = 5000,
      icon,
      title,
      description,
      children,
      showCloseButton = true,
      animation = true,
      className = "",
      id,
      ariaLabel,
      ...props
    },
    ref
  ) => {
    const toastRef = useRef<HTMLDivElement>(null);
    const autoDismissRef = useRef<NodeJS.Timeout | null>(null);

    const autoId = React.useId();
    const toastId = id ?? autoId;
    const titleId = `${toastId}-title`;
    const descId = `${toastId}-description`;

    // Auto-dismiss functionality
    useEffect(() => {
      if (open && duration > 0) {
        autoDismissRef.current = setTimeout(() => {
          onClose();
        }, duration);
      }

      return () => {
        if (autoDismissRef.current) {
          clearTimeout(autoDismissRef.current);
        }
      };
    }, [open, duration, onClose]);

    // Clear auto-dismiss on hover
    const handleMouseEnter = () => {
      if (autoDismissRef.current) {
        clearTimeout(autoDismissRef.current);
      }
    };

    // Restart auto-dismiss on mouse leave
    const handleMouseLeave = () => {
      if (open && duration > 0) {
        autoDismissRef.current = setTimeout(() => {
          onClose();
        }, duration);
      }
    };

    // Support exit animations by keeping mounted until animation completes
    const [isMounted, setIsMounted] = useState(open);
    const [isAnimatingOut, setIsAnimatingOut] = useState(false);

    useEffect(() => {
      if (open) {
        setIsMounted(true);
        setIsAnimatingOut(false);
      } else if (animation) {
        setIsAnimatingOut(true);
        const t = setTimeout(() => {
          setIsMounted(false);
          setIsAnimatingOut(false);
        }, 210); // match duration-200 + small buffer
        return () => clearTimeout(t);
      } else {
        setIsMounted(false);
      }
    }, [open, animation]);

    if (!isMounted) return null;

    const toastClasses = cn(
      toastBase,
      variants[variant],
      sizes[size],
      animation && (isAnimatingOut ? toastAnimations.exit : toastAnimations.enter),
      className
    );

    const toastContent = (
      <div
        ref={ref || toastRef}
        className={toastClasses}
        role="alert"
        aria-live="assertive"
        aria-atomic="true"
        aria-label={ariaLabel}
        aria-labelledby={title ? titleId : undefined}
        aria-describedby={description || children ? descId : undefined}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        id={toastId}
        {...props}
      >
        {/* Icon */}
        <div className="flex shrink-0 items-center">{icon || variantIcons[variant]}</div>

        {/* Content */}
        <div className={contentBase}>
          {children ? (
            <div id={descId} className="break-words">
              {children}
            </div>
          ) : (
            <>
              {title && (
                <div id={titleId} className={titleBase}>
                  {title}
                </div>
              )}
              {description && (
                <div id={descId} className={cn(descriptionBase, title && "mt-1")}>
                  {description}
                </div>
              )}
            </>
          )}
        </div>

        {/* Close button */}
        {showCloseButton && (
          <button
            type="button"
            className={closeButtonBase}
            onClick={onClose}
            aria-label="Close notification"
          >
            <IoClose className="h-4 w-4" />
          </button>
        )}
      </div>
    );

    // Position the toast using a portal
    const positionClasses = cn("pointer-events-auto fixed z-50", positions[position]);

    return createPortal(<div className={positionClasses}>{toastContent}</div>, document.body);
  }
);

Toast.displayName = "Toast";

// Toast context and hook

export interface ToastItem {
  id: string;
  open: boolean;
  variant?: "success" | "error" | "warning" | "info";
  position?:
    | "top-left"
    | "top-center"
    | "top-right"
    | "bottom-left"
    | "bottom-center"
    | "bottom-right";
  size?: "sm" | "md" | "lg";
  duration?: number;
  icon?: React.ReactNode;
  title?: string;
  description?: string;
  children?: React.ReactNode;
  showCloseButton?: boolean;
  animation?: boolean;
  className?: string;
}

interface ToastContextType {
  toasts: ToastItem[];
  addToast: (toast: Omit<ToastItem, "id" | "open">) => string;
  removeToast: (id: string) => void;
  updateToast: (id: string, updates: Partial<ToastItem>) => void;
  success: (
    title: string,
    description?: string,
    options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
  ) => string;
  error: (
    title: string,
    description?: string,
    options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
  ) => string;
  warning: (
    title: string,
    description?: string,
    options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
  ) => string;
  info: (
    title: string,
    description?: string,
    options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
  ) => string;
  promise: <T>(
    promise: Promise<T>,
    messages: {
      loading: string;
      success: string | ((data: T) => string);
      error: string | ((error: unknown) => string);
    },
    options?: Partial<Omit<ToastItem, "id" | "open" | "title" | "description">>
  ) => Promise<T>;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error("useToast must be used within a ToastProvider");
  }
  return context;
};

interface ToastProviderProps {
  children: React.ReactNode;
}

export const ToastProvider: React.FC<ToastProviderProps> = ({ children }) => {
  const [toasts, setToasts] = useState<ToastItem[]>([]);

  const addToast = useCallback((toast: Omit<ToastItem, "id" | "open">) => {
    const id = Math.random().toString(36).substring(2, 9);
    const newToast: ToastItem = {
      ...toast,
      id,
      open: true,
    };
    setToasts(prev => [...prev, newToast]);
    return id;
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.map(toast => (toast.id === id ? { ...toast, open: false } : toast)));
    // Remove from state after animation
    setTimeout(() => {
      setToasts(prev => prev.filter(toast => toast.id !== id));
    }, 300);
  }, []);

  const updateToast = useCallback((id: string, updates: Partial<ToastItem>) => {
    setToasts(prev => prev.map(toast => (toast.id === id ? { ...toast, ...updates } : toast)));
  }, []);

  const success = useCallback(
    (
      title: string,
      description?: string,
      options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
    ) => {
      return addToast({
        variant: "success",
        title,
        description,
        ...options,
      });
    },
    [addToast]
  );

  const error = useCallback(
    (
      title: string,
      description?: string,
      options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
    ) => {
      return addToast({
        variant: "error",
        title,
        description,
        ...options,
      });
    },
    [addToast]
  );

  const warning = useCallback(
    (
      title: string,
      description?: string,
      options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
    ) => {
      return addToast({
        variant: "warning",
        title,
        description,
        ...options,
      });
    },
    [addToast]
  );

  const info = useCallback(
    (
      title: string,
      description?: string,
      options?: Partial<Omit<ToastItem, "id" | "open" | "variant" | "title" | "description">>
    ) => {
      return addToast({
        variant: "info",
        title,
        description,
        ...options,
      });
    },
    [addToast]
  );

  const promise = useCallback(
    async <T,>(
      promise: Promise<T>,
      messages: {
        loading: string;
        success: string | ((data: T) => string);
        error: string | ((error: unknown) => string);
      },
      options?: Partial<Omit<ToastItem, "id" | "open" | "title" | "description">>
    ): Promise<T> => {
      const id = addToast({
        variant: "info",
        title: messages.loading,
        ...options,
      });

      try {
        const data = await promise;
        const successMessage =
          typeof messages.success === "function" ? messages.success(data) : messages.success;
        updateToast(id, {
          variant: "success",
          title: successMessage,
        });
        return data;
      } catch (error) {
        const errorMessage =
          typeof messages.error === "function" ? messages.error(error) : messages.error;
        updateToast(id, {
          variant: "error",
          title: errorMessage,
        });
        throw error;
      }
    },
    [addToast, updateToast]
  );

  const value: ToastContextType = {
    toasts,
    addToast,
    removeToast,
    updateToast,
    success,
    error,
    warning,
    info,
    promise,
  };

  return (
    <ToastContext.Provider value={value}>
      {children}
      {toasts.map(toast => (
        <Toast
          key={toast.id}
          open={toast.open}
          onClose={() => removeToast(toast.id)}
          variant={toast.variant}
          position={toast.position}
          size={toast.size}
          duration={toast.duration}
          icon={toast.icon}
          title={toast.title}
          description={toast.description}
          showCloseButton={toast.showCloseButton}
          animation={toast.animation}
          className={toast.className}
        >
          {toast.children}
        </Toast>
      ))}
    </ToastContext.Provider>
  );
};

import React, { useEffect, useRef, useState } from "react";
import { cn, tw } from "@/lib/utils";

export interface TooltipProps {
  /**
   * The content to display inside the tooltip
   */
  content: React.ReactNode;
  /**
   * The trigger element that shows the tooltip
   */
  children: React.ReactNode;
  /**
   * The position of the tooltip relative to the trigger
   * @default "auto"
   */
  position?: "auto" | "top" | "bottom" | "left" | "right";
  /**
   * The visual style of the tooltip
   * @default "dark"
   */
  variant?: "dark" | "light" | "primary" | "success" | "warning" | "error";
  /**
   * The size of the tooltip
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Control the border radius of the tooltip
   * @default "md"
   */
  rounded?: "none" | "sm" | "md" | "lg" | "xl" | "full";
  /**
   * Whether the tooltip is disabled
   * @default false
   */
  disabled?: boolean;
  /**
   * Delay in milliseconds before showing the tooltip
   * @default 300
   */
  delay?: number;
  /**
   * Custom class name for the tooltip container
   */
  className?: string;
  /**
   * Custom class name for the tooltip content
   */
  tooltipClassName?: string;
  /**
   * Whether to show an arrow pointing to the trigger
   * @default true
   */
  showArrow?: boolean;
  /**
   * ID for the tooltip element
   */
  id?: string;
  /**
   * Maximum width of the tooltip
   * @default "sm"
   */
  maxWidth?: "xs" | "sm" | "md" | "lg" | "xl" | "none";
}

// Base styles
const tooltipBase = tw`absolute z-50 px-3 py-2 text-sm font-medium shadow-lg transition-opacity duration-200`;

// Max width options
const maxWidthOptions = {
  xs: tw`max-w-xs`,
  sm: tw`max-w-sm`,
  md: tw`max-w-md`,
  lg: tw`max-w-lg`,
  xl: tw`max-w-xl`,
  none: tw`max-w-none`,
};

// Variants
const variants = {
  dark: tw`bg-foreground text-background`,
  light: tw`border border-border bg-popover text-popover-foreground`,
  primary: tw`bg-primary text-primary-foreground`,
  success: tw`bg-success text-success-foreground`,
  warning: tw`bg-warning text-warning-foreground`,
  error: tw`bg-destructive text-destructive-foreground`,
};

// Sizes
const sizes = {
  sm: tw`px-2 py-1 text-xs`,
  md: tw`px-3 py-2 text-sm`,
  lg: tw`px-4 py-3 text-base`,
};

// Rounded options
const roundedOptions = {
  none: tw`rounded-none`,
  sm: tw`rounded-sm`,
  md: tw`rounded-md`,
  lg: tw`rounded-lg`,
  xl: tw`rounded-xl`,
  full: tw`rounded-full`,
};

// Arrow styles
const arrowBase = tw`absolute h-2 w-2 rotate-45 transform`;
const arrowVariants = {
  dark: tw`bg-foreground`,
  light: tw`border-border bg-popover`,
  primary: tw`bg-primary`,
  success: tw`bg-success`,
  warning: tw`bg-warning`,
  error: tw`bg-destructive`,
};

const getArrowPosition = (position: string) => {
  switch (position) {
    case "top":
      return tw`bottom-[-4px] left-1/2 -translate-x-1/2 transform`;
    case "bottom":
      return tw`top-[-4px] left-1/2 -translate-x-1/2 transform`;
    case "left":
      return tw`top-1/2 right-[-4px] -translate-y-1/2 transform`;
    case "right":
      return tw`top-1/2 left-[-4px] -translate-y-1/2 transform`;
    default:
      return "";
  }
};

export const Tooltip: React.FC<TooltipProps> = ({
  content,
  children,
  position = "auto",
  variant = "dark",
  size = "md",
  rounded = "md",
  disabled = false,
  delay = 300,
  className = "",
  tooltipClassName = "",
  showArrow = true,
  id,
  maxWidth = "none",
  ...props
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const initialPosition =
    position === "auto" ? "top" : (position as "top" | "bottom" | "left" | "right");
  const [actualPosition, setActualPosition] = useState(initialPosition);
  const triggerRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const showTooltip = () => {
    if (disabled) return;
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setIsVisible(true), delay);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setIsVisible(false);
  };

  useEffect(() => {
    if (isVisible && tooltipRef.current && triggerRef.current) {
      // Use requestAnimationFrame to ensure tooltip is fully rendered before calculating position
      requestAnimationFrame(() => {
        if (tooltipRef.current && triggerRef.current) {
          const tooltipRect = tooltipRef.current.getBoundingClientRect();
          const triggerRect = triggerRef.current.getBoundingClientRect();
          const viewportWidth = window.innerWidth;
          const viewportHeight = window.innerHeight;

          let newPosition: "top" | "bottom" | "left" | "right";

          if (position === "auto") {
            // Calculate available space for each direction
            const spaceTop = triggerRect.top;
            const spaceBottom = viewportHeight - triggerRect.bottom;
            const spaceLeft = triggerRect.left;
            const spaceRight = viewportWidth - triggerRect.right;

            // Priority order: top > left > right > bottom
            const positions = [
              { position: "top" as const, space: spaceTop },
              { position: "left" as const, space: spaceLeft },
              { position: "right" as const, space: spaceRight },
              { position: "bottom" as const, space: spaceBottom },
            ];

            // Find the first position that has enough space
            let bestPosition: "top" | "bottom" | "left" | "right" | null = null;

            for (const { position: pos, space } of positions) {
              const requiredSpace =
                pos === "top" || pos === "bottom" ? tooltipRect.height + 8 : tooltipRect.width + 8;
              if (space >= requiredSpace) {
                bestPosition = pos;
                break;
              }
            }

            // Fallback to top if no position has enough space
            newPosition = bestPosition || "top";
          } else {
            // Check if current position would overflow and flip if necessary
            newPosition = position as "top" | "bottom" | "left" | "right";
            switch (position) {
              case "top":
                if (triggerRect.top - tooltipRect.height - 8 < 0) {
                  newPosition = "bottom";
                }
                break;
              case "bottom":
                if (triggerRect.bottom + tooltipRect.height + 8 > viewportHeight) {
                  newPosition = "top";
                }
                break;
              case "left":
                if (triggerRect.left - tooltipRect.width - 8 < 0) {
                  newPosition = "right";
                }
                break;
              case "right":
                if (triggerRect.right + tooltipRect.width + 8 > viewportWidth) {
                  newPosition = "left";
                }
                break;
            }
          }

          setActualPosition(newPosition);
        }
      });
    }
  }, [isVisible, position, content]);

  const getPositionStyles = () => {
    const offset = 12;

    switch (actualPosition) {
      case "top":
        return {
          bottom: "100%",
          left: "50%",
          transform: "translateX(-50%)",
          marginBottom: `${offset}px`,
        };
      case "bottom":
        return {
          top: "100%",
          left: "50%",
          transform: "translateX(-50%)",
          marginTop: `${offset}px`,
        };
      case "left":
        return {
          right: "100%",
          top: "50%",
          transform: "translateY(-50%)",
          marginRight: `${offset}px`,
        };
      case "right":
        return {
          left: "100%",
          top: "50%",
          transform: "translateY(-50%)",
          marginLeft: `${offset}px`,
        };
      default:
        return {};
    }
  };

  const tooltipClasses = cn(
    tooltipBase,
    variants[variant],
    sizes[size],
    roundedOptions[rounded],
    maxWidthOptions[maxWidth],
    maxWidth !== "none" ? "break-words whitespace-normal" : "whitespace-nowrap",
    isVisible ? "opacity-100" : "pointer-events-none opacity-0",
    tooltipClassName
  );

  const arrowClasses = cn(arrowBase, arrowVariants[variant], getArrowPosition(actualPosition));

  return (
    <div className={cn("relative inline-block", className)} {...props}>
      <div
        ref={triggerRef}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        onFocus={showTooltip}
        onBlur={hideTooltip}
        className="inline-block"
        aria-describedby={id}
      >
        {children}
      </div>

      <div
        ref={tooltipRef}
        id={id}
        role="tooltip"
        className={tooltipClasses}
        style={getPositionStyles()}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
      >
        {content}
        {showArrow && <div className={arrowClasses} />}
      </div>
    </div>
  );
};

Tooltip.displayName = "Tooltip";

import React from "react";
import { cn, tw } from "@/lib/utils";

export interface TopLoaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The current progress value (0-100). Set to null for indeterminate state
   * @default null
   */
  progress?: number | null;
  /**
   * Whether the loader is visible
   * @default true
   */
  show?: boolean;
  /**
   * The height of the loader bar
   * @default "md"
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /**
   * The color variant of the loader
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "success" | "warning" | "error";
  /**
   * Custom color for the loader (overrides variant)
   */
  color?: string;
  /**
   * Animation speed
   * @default "normal"
   */
  speed?: "slow" | "normal" | "fast";
  /**
   * Whether to show a glow effect
   * @default false
   */
  glow?: boolean;
  /**
   * Z-index for the loader
   * @default 50
   */
  zIndex?: number;
  /**
   * Custom class name for the loader bar
   */
  barClassName?: string;
}

const base = tw`fixed top-0 left-0 w-full transform-gpu overflow-hidden transition-all duration-300 ease-out`;

const sizes = {
  xs: tw`h-0.5`,
  sm: tw`h-1`,
  md: tw`h-1.5`,
  lg: tw`h-2`,
  xl: tw`h-3`,
};

// Added text colors to variants for glow effect to work correctly
const variants = {
  primary: tw`bg-primary text-primary`,
  secondary: tw`bg-muted-foreground text-muted-foreground`,
  success: tw`bg-success text-success`,
  warning: tw`bg-warning text-warning`,
  error: tw`bg-destructive text-destructive`,
};

const speeds = {
  slow: tw`transition-all duration-500 ease-out`,
  normal: tw`transition-all duration-300 ease-out`,
  fast: tw`transition-all duration-200 ease-out`,
};

const glowEffect = tw`shadow-lg shadow-current/50`;

const smoothWidthTransition = tw`transition-[width] duration-300 ease-out`;

const indeterminateAnimation = tw`animate-[indeterminate_1.5s_ease-in-out_infinite]`;

export const TopLoader = React.forwardRef<HTMLDivElement, TopLoaderProps>(
  (
    {
      progress = null,
      show = true,
      size = "md",
      variant = "primary",
      color,
      speed = "normal",
      glow = false,
      zIndex = 50,
      className = "",
      barClassName = "",
      ...props
    },
    ref
  ) => {
    // Calculate width based on progress with smooth transitions
    const progressValue = progress === null ? 100 : Math.min(Math.max(progress, 0), 100);
    const width = `${progressValue}%`;

    // Determine if indeterminate
    const isIndeterminate = progress === null;

    return (
      <div
        ref={ref}
        className={cn(
          base,
          speeds[speed],
          show ? "opacity-100" : "pointer-events-none opacity-0",
          className
        )}
        style={{ zIndex }}
        role="progressbar"
        aria-valuenow={isIndeterminate ? undefined : progress || 0}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="Loading progress"
        {...props}
      >
        <div
          className={cn(
            "h-full w-full max-w-full overflow-hidden",
            sizes[size],
            !color && variants[variant],
            glow && glowEffect,
            !isIndeterminate && smoothWidthTransition,
            isIndeterminate && indeterminateAnimation,
            barClassName
          )}
          style={{
            width: width,
            backgroundColor: color,
            boxShadow: glow ? `0 0 10px ${color || "currentColor"}` : undefined,
            willChange: !isIndeterminate ? "width" : undefined,
          }}
        />
      </div>
    );
  }
);

TopLoader.displayName = "TopLoader";

