// #region State Management (useReducer)
interface PlayerState {
  isPlaying: boolean;
  isMuted: boolean;
  isLoading: boolean;
  isFullscreen: boolean;
  isScrubbing: boolean;
  showSettings: boolean;
  currentTime: number;
  duration: number;
  bufferedTime: number;
  volume: number;
  playbackRate: number;
  activeTrack: string | null;
}
type PlayerAction =
  | { type: "SET_PLAYING"; payload: boolean }
  | { type: "SET_MUTED"; payload: boolean }
  | { type: "TOGGLE_SETTINGS" }
  | { type: "SET_FULLSCREEN"; payload: boolean }
  | { type: "SET_LOADING"; payload: boolean }
  | { type: "SET_SCRUBBING"; payload: boolean }
  | { type: "SET_PLAYBACK_RATE"; payload: number }
  | { type: "SET_ACTIVE_TRACK"; payload: string | null }
  | { type: "SET_VOLUME"; payload: number }
  | { type: "SET_TIME"; payload: number }
  | { type: "SET_DURATION"; payload: number }
  | { type: "SET_BUFFERED_TIME"; payload: number };
const initialState: PlayerState = {
  isPlaying: false,
  isMuted: false,
  isLoading: true,
  isFullscreen: false,
  isScrubbing: false,
  showSettings: false,
  currentTime: 0,
  duration: 0,
  bufferedTime: 0,
  volume: 1,
  playbackRate: 1,
  activeTrack: null,
};
function playerReducer(state: PlayerState, action: PlayerAction): PlayerState {
  switch (action.type) {
    case "SET_PLAYING":
      return { ...state, isPlaying: action.payload };
    case "SET_MUTED":
      return { ...state, isMuted: action.payload };
    case "TOGGLE_SETTINGS":
      return { ...state, showSettings: !state.showSettings };
    case "SET_LOADING":
      return { ...state, isLoading: action.payload };
    case "SET_FULLSCREEN":
      return { ...state, isFullscreen: action.payload };
    case "SET_SCRUBBING":
      return { ...state, isScrubbing: action.payload };
    case "SET_PLAYBACK_RATE":
      return {
        ...state,
        playbackRate: action.payload,
        showSettings: false,
      };
    case "SET_ACTIVE_TRACK":
      return {
        ...state,
        activeTrack: action.payload,
        showSettings: false,
      };
    case "SET_VOLUME":
      return { ...state, volume: action.payload };
    case "SET_TIME":
      return { ...state, currentTime: action.payload };
    case "SET_DURATION":
      return { ...state, duration: action.payload };
    case "SET_BUFFERED_TIME":
      return { ...state, bufferedTime: action.payload };
    default:
      return state;
  }
}
// #endregion

type FeedbackType = "forward" | "rewind" | "volume" | "play" | "pause";
type Feedback = { type: FeedbackType; key: number; value?: number };

